_PACKAGE_WORDS = ("প্যাকেজ", "প্যাক", "বান্ডেল")


_BN_DIGITS = str.maketrans("০১২৩৪৫৬৭৮৯", "0123456789")


def _glossary_en(text):
    """শেষ চেষ্টা: শব্দ-ভিত্তিক অনুবাদ (নেটওয়ার্ক ছাড়াই)।"""
    out = str(text or "")
    for bn, en in _EN_WORDS:
        if bn in out:
            out = out.replace(bn, en)
    for _w in _PACKAGE_WORDS:
        out = out.replace(_w, "Package")
    return out


# লাইনের শুরুতে লেবেল — পরে যা-ই থাকুক (পণ্যের নাম, স্ট্যাটাস, দাম) ইংরেজি হবে
_EN_PREFIX = [
    ("🛍 পণ্য: ", "🛍 Product: "),
    ("🧾 <b>অর্ডার #", "🧾 <b>Order #"),
    ("⚙️ স্ট্যাটাস: ", "⚙️ Status: "),
    ("📅 তারিখ: ", "📅 Date: "),
    ("🏷 ধরন: ", "🏷 Type: "),
    ("💵 দাম: ", "💵 Price: "),
    ("💵 মূল্য: ", "💵 Amount: "),
    ("📦 স্টক: ", "📦 Stock: "),
    ("📉 সর্বনিম্ন: ", "📉 Minimum: "),
    ("💰 আপনার ব্যালেন্স: ", "💰 Your balance: "),
    ("➡️ কেনার পরে থাকবে: ", "➡️ After purchase: "),
    ("⏳ পেন্ডিং অর্ডার (", "⏳ Pending orders ("),
    ("🔢 পরিমাণ: ", "🔢 Quantity: "),
    ("💵 মোট: ", "💵 Total: "),
    ("🆔 অর্ডার: ", "🆔 Order: "),
]

# সংখ্যা/তারিখ/আইডি → {{n}} — একই বাক্যের ভিন্ন মানেও ক্যাশ কাজ করবে
_NUM_MASK_RE = _re.compile(r"\d[\d.,:/\-]*")
_TR_OFF_TILL = 0.0          # নেটওয়ার্ক ফেল করলে এই সময় পর্যন্ত আর চেষ্টা নয়
_TR_FAIL_COOLDOWN = 300.0   # ৫ মিনিট


def _mask_nums(text):
    vals = []

    def _sub(m):
        vals.append(m.group(0))
        return "{{%d}}" % len(vals)

    return _NUM_MASK_RE.sub(_sub, str(text)), vals


def _unmask_nums(text, vals):
    for i, v in enumerate(vals, 1):
        text = text.replace("{{%d}}" % i, v)
    return text


def _tr_net(key):
    """Google Translate — ফেল/টাইমআউটে সার্কিট ব্রেকার, তাই বারবার অপেক্ষা নয়।"""
    global _TR_OFF_TILL
    if _time.time() < _TR_OFF_TILL:
        return key
    try:
        url = ("https://translate.googleapis.com/translate_a/single"
               "?client=gtx&sl=bn&tl=en&dt=t&q=" + urllib.parse.quote(key))
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
        try:
            with urllib.request.urlopen(req, timeout=2.5) as r:
                data = _json.loads(r.read())
        except Exception:
            # sl=auto দিয়ে আরেকবার (মিশ্র ভাষার লেখাও অনুবাদ হয়)
            url2 = ("https://translate.googleapis.com/translate_a/single"
                    "?client=gtx&sl=auto&tl=en&dt=t&q=" + urllib.parse.quote(key))
            req2 = urllib.request.Request(url2, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req2, timeout=2.5) as r:
                data = _json.loads(r.read())
        out = "".join(seg[0] for seg in data[0] if seg[0]).strip()
    except Exception:
        _TR_OFF_TILL = _time.time() + _TR_FAIL_COOLDOWN
        return key
    return out or key


def _tr_line(line):
    """এক লাইন অনুবাদ — অভিধান → মেমরি ক্যাশ → নেটওয়ার্ক।"""
    src = str(line)
    if not src.strip() or not _BN_RE.search(src):
        return src
    masked, vals = _mask_nums(src)
    key = masked.strip()
    hit = _EN_FAST.get(key)
    if hit:
        return _unmask_nums(hit, vals)
    for _bp, _ep in _EN_PREFIX:
        if key.startswith(_bp):
            _tail = key[len(_bp):].strip()
            if _tail:
                _tv = _EN_FAST.get(_tail)
                if _tv:
                    return _unmask_nums(_ep + _tv, vals)
                if not _BN_RE.search(_tail):
                    return _unmask_nums(_ep + _tail, vals)
            break
    ck = "L|" + key
    cached = _translation_cache.get(ck)
    if cached is None:
        out = _tr_net(key)
        if out == key:            # অনুবাদ হয়নি — শব্দ-ভিত্তিক ফলব্যাক (ক্যাশে বিষ রাখব না)
            return _unmask_nums(_glossary_en(key), vals)
        cached = out
        if len(_translation_cache) >= _TRANSLATION_CACHE_MAX:
            for _k in list(_translation_cache.keys())[:len(_translation_cache) // 2]:
                _translation_cache.pop(_k, None)
        _translation_cache[ck] = cached
        _i18n_db_put(ck, cached)
    return _unmask_nums(cached, vals)


def translate_to_en(text):
    """বাংলা → ইংরেজি। লাইন ধরে ধরে, সংখ্যা মাস্ক করে (ক্যাশ হিট বেশি), পাল্টাপাল্টি অনুবাদ।"""
    if not text or not isinstance(text, str) or not _BN_RE.search(text):
        return text
    text = text.translate(_BN_DIGITS)     # বাংলা সংখ্যা → ইংরেজি সংখ্যা
    if "\n" not in text:
        return _tr_line(text)
    parts = text.split("\n")
    todo, done = [], {}
    for ln in parts:
        if ln in done or not ln.strip() or not _BN_RE.search(ln) or ln in todo:
            continue
        masked, vals = _mask_nums(ln)
        hit = _EN_FAST.get(masked.strip())
        if hit:
            done[ln] = _unmask_nums(hit, vals)
            continue
        cached = _translation_cache.get("L|" + masked.strip())
        if cached:
            done[ln] = _unmask_nums(cached, vals)
            continue
        _pfx_done = None
        for _bp, _ep in _EN_PREFIX:
            if masked.strip().startswith(_bp):
                _tail = masked.strip()[len(_bp):].strip()
                if _tail:
                    _tv = _EN_FAST.get(_tail)
                    if _tv:
                        _pfx_done = _ep + _tv
                    elif not _BN_RE.search(_tail):
                        _pfx_done = _ep + _tail
                break
        if _pfx_done is not None:
            done[ln] = _unmask_nums(_pfx_done, vals)
            continue
        todo.append(ln)
    if todo:
        try:
            import concurrent.futures as _cf
            with _cf.ThreadPoolExecutor(max_workers=min(6, len(todo))) as _ex:
                for _ln, _res in zip(todo, _ex.map(_tr_line, todo)):
                    done[_ln] = _res
        except Exception:
            for _ln in todo:
                done[_ln] = _tr_line(_ln)
    return "\n".join(done.get(ln, ln) for ln in parts)


_TR_MEM = {}


def tr_for_user(uid, text):
    """ইউজারের ভাষা অনুযায়ী টেক্সট (en হলে Google অনুবাদ, মেমরি + DB ক্যাশ)।"""
    try:
        if not text or not isinstance(text, str):
            return text
        if get_lang(uid) != "en":
            return text
        _mk = str(text)[:200]
        _hit = _TR_MEM.get(_mk)
        if _hit is not None:
            return _hit
        _out = translate_to_en(text)
        if _out and _out != text:
            if len(_TR_MEM) > 4000:      # মেমরি সীমিত রাখি
                _TR_MEM.clear()
            _TR_MEM[_mk] = _out
        return _out
    except Exception:
        return text


def md_escape(text):
    for ch in ('*', '_', '`', '['):
        text = text.replace(ch, f'\\{ch}')
    return text

# ──────────────── ভাষা গার্ড — English ইউজারের জন্য বাংলা আউটগোয়িং অটো ইংরেজি ────────────────
# বটের শত শত হার্ডকোড মেসেজ/বাটন এখানে এক জায়গায় ধরা হয়:
#   • ইউজারের lang='en' হলে: বাংলা টেক্সট/ক্যাপশন → translate_to_en (cached),
#     বাংলা বাটন-লেবেল → ইংরেজি (মূল markup/button অপরিবর্তিত থাকে, copy হয়)
#   • অনুবাদ ভেঙে Telegram 400 এলে (markdown/HTML) মূল টেক্সট দিয়ে আবার পাঠাবে
#   • lang='bn' (ডিফল্ট) ইউজার, গ্রুপ, চ্যানেল — কোনো মেসেজ ছোঁয় না, বাংলা হুবহু থাকে
#   • ইংরেজি-অনলি ইউজার-মেসেজগুলো নিচে হাতে bn/en করা (withdrawal success, error ইত্যাদি)
import copy as _copymod

_BN_RE = _re.compile(r"[ঀ-৿]")
_TAG_SPLIT = _re.compile(r"(<[^<>]{1,80}>)")


def _translate_html_en(text):
    """HTML ট্যাগ অটুট রেখে ভেতরের বাংলা অংশ ইংরেজি করো।"""
    parts = _TAG_SPLIT.split(str(text or ""))
    out = []
    for seg in parts:
        if not seg:
            continue
        if seg.startswith("<") and seg.endswith(">"):
            out.append(seg)
        elif _BN_RE.search(seg) and seg.strip():
            out.append(translate_to_en(seg))
        else:
            out.append(seg)
    return "".join(out)

def _mk_with_rows(markup, rows):
    """একই ধরনের নতুন markup, ভেতরের রো বদলানো (PTB-তে immutable)।"""
    try:
        return type(markup)(rows)
    except Exception:
        pass
    try:
        nm = _copymod.copy(markup)
        object.__setattr__(nm, "keyboard" if hasattr(markup, "keyboard")
                           else "inline_keyboard", rows)
        return nm
    except Exception:
        return markup


def _btn_retitled(btn, new_text):
    """একই বাটনের কপি, শুধু টেক্সট বদলানো (PTB-তে text immutable)।"""
    try:
        nb = _copymod.copy(btn)
        object.__setattr__(nb, "text", new_text)
        return nb
    except Exception:
        pass
    try:
        d = btn.to_dict()
        d.pop("text", None)
        return type(btn)(text=new_text, **d)
    except Exception:
        return btn


def _i18n_markup_en(markup, translator):
    """ReplyMarkup-এর বাংলা বাটন-লেবেল ইংরেজি করো — মূল object ছোঁয় না।"""
    rows = getattr(markup, "keyboard", None) or getattr(markup, "inline_keyboard", None)
    if not rows:
        return markup
    new_rows, touched = [], False
    for row in rows:
        new_row = []
        for btn in row:
            t = getattr(btn, "text", None)
            if isinstance(t, str) and _BN_RE.search(t):
                new_row.append(_btn_retitled(btn, translator(t)))
                touched = True
            else:
                new_row.append(btn)
        new_rows.append(new_row)
    if not touched:
        return markup
    return _mk_with_rows(markup, new_rows)


async def _i18n_markup_en_async(markup):
    """বাটন-লেবেলগুলো একসাথে (সমান্তরাল) অনুবাদ — একটা একটা করে অপেক্ষা নয়।"""
    rows = getattr(markup, "keyboard", None) or getattr(markup, "inline_keyboard", None)
    if not rows:
        return markup
    labels = []
    for row in rows:
        for btn in row:
            t = getattr(btn, "text", None)
            if isinstance(t, str) and _BN_RE.search(t) and t not in labels:
                labels.append(t)
    if not labels:
        return markup
    try:
        results = await asyncio.gather(
            *(asyncio.to_thread(translate_to_en, lab) for lab in labels))
    except Exception:
        return markup
    mapping = dict(zip(labels, results))
    new_rows, touched = [], False
    for row in rows:
        new_row = []
        for btn in row:
            t = getattr(btn, "text", None)
            if isinstance(t, str) and t in mapping and mapping[t] != t:
                new_row.append(_btn_retitled(btn, mapping[t]))
                touched = True
            else:
                new_row.append(btn)
        new_rows.append(new_row)
    if not touched:
        return markup
    return _mk_with_rows(markup, new_rows)


async def _i18n_out(text, markup, chat_id):
    """ইউজারের lang='en' হলে বাংলা আউটগোয়িং টেক্সট+বাটন ইংরেজি; নাহলে অপরিবর্তিত।"""
    if not text and not markup:
        return text, markup
    if chat_id is None:
        return text, markup
    _has_bn = bool((isinstance(text, str) and _BN_RE.search(text))) or any(
        isinstance(getattr(b, "text", None), str) and _BN_RE.search(b.text)
        for _row in (getattr(markup, "keyboard", None)
                     or getattr(markup, "inline_keyboard", None) or [])
        for b in _row) if markup is not None else bool(
        isinstance(text, str) and _BN_RE.search(text))
    if not _has_bn:
        return text, markup     # কিছুই অনুবাদ করার নেই — DB/নেটওয়ার্ক ছোঁব না
    try:
        lang = _get_lang_fast(chat_id)
        if lang is None:
            lang = await asyncio.to_thread(get_lang, chat_id)
        if lang != 'en':
            return text, markup
        if isinstance(text, str) and _BN_RE.search(text):
            if "<" in text and ">" in text:
                text = await asyncio.to_thread(_translate_html_en, text)
            else:
                text = await asyncio.to_thread(translate_to_en, text)
        if markup is not None:
            markup = await _i18n_markup_en_async(markup)
    except Exception:
        pass
    return text, markup


def _i18n_patch_method(cls, name, *, text_pos=None, text_kw="text", chat_get=None):
    """PTB আউটগোয়িং মেথডে ভাষা-গার্ড বসাও — অনুবাদ ভেঙে পাঠালে মূল দিয়ে retry।"""
    orig = getattr(cls, name, None)
    if orig is None or getattr(orig, "_i18n", False):
        return
    async def _wrapped(self, *args, **kwargs):
        args = list(args)
        if text_pos is not None and len(args) > text_pos:
            cur = args[text_pos]
        else:
            cur = kwargs.get(text_kw)
        orig_mk = kwargs.get("reply_markup")
        chat_id = chat_get(self, args, kwargs) if chat_get else None
        nt, nm = await _i18n_out(cur, orig_mk, chat_id)
        changed = (nt is not cur) or (nm is not orig_mk)
        if text_pos is not None and len(args) > text_pos:
            args[text_pos] = nt
        elif nt is not cur:
            kwargs[text_kw] = nt
        if nm is not orig_mk:
            kwargs["reply_markup"] = nm
        try:
            return await orig(self, *args, **kwargs)
        except Exception:
            if not changed:
                raise
            # অনুবাদ markdown/HTML ভেঙে দিয়েছে — মূল টেক্সট দিয়ে আবার পাঠাও
            if text_pos is not None and len(args) > text_pos:
                args[text_pos] = cur
            else:
                kwargs[text_kw] = cur
            kwargs["reply_markup"] = orig_mk
            return await orig(self, *args, **kwargs)
    _wrapped._i18n = True
    _wrapped.__name__ = name
    setattr(cls, name, _wrapped)


try:
    from telegram import Message as _TgMessage, Bot as _TgBot, CallbackQuery as _TgCallbackQuery
except Exception:
    _TgMessage = _TgBot = _TgCallbackQuery = None

