# ── নতুন ইউজার notification — bot restart এ ctx.user_data হারালেও কাজ করবে ──
_notified_set: set = set()   # uid set — double-notification বন্ধ (max 10,000 — পুরনো clear হয়)

def _notified_set_add(uid: int):
    """_notified_set এ uid যোগ করো। ১০,০০০ পার হলে পুরো set মুছে নতুন শুরু।"""
    global _notified_set
    if len(_notified_set) >= 10_000:
        _notified_set = set()
    _notified_set.add(uid)

# ──────────────────────────── DATABASE ────────────────────────────
# যখনই টাকা/ডাটা বদলায় → True হয় → background job Telegram এ backup পাঠায়
_db_dirty = False
_app = None   # set in post_init — immediate backup scheduling এর জন্য
_backup_task_pending = False  # duplicate immediate task তৈরি হওয়া ঠেকায়

def _mark_dirty():
    global _db_dirty, _backup_task_pending
    _db_dirty = True

    # ── Method 1: asyncio event loop (সবচেয়ে নির্ভরযোগ্য — job_queue ছাড়াই কাজ করে) ──
    # async handler থেকে call হলে event loop running থাকে, তাই সরাসরি task create করা যায়।
    if not _backup_task_pending and _app is not None:
        try:
            loop = asyncio.get_running_loop()
            _backup_task_pending = True
            async def _delayed_backup():
                global _backup_task_pending
                await asyncio.sleep(3)
                _backup_task_pending = False
                if _app is not None:
                    # lock: আগের full-report চলতে থাকলে নতুনটা অপেক্ষা করবে,
                    # একসাথে একাধিক backup চলে DB ও CPU নিজে থেকেই বাড়তে দেয় না
                    async with _dirty_backup_lock:
                        await _run_dirty_backup_now(_app.bot)
            _dbt = loop.create_task(_delayed_backup())
            _background_tasks.add(_dbt); _dbt.add_done_callback(_bg_task_done)
        except RuntimeError:
            pass  # event loop নেই (e.g. init time) — Method 2 fallback নেবে

    # ── Method 2: job_queue fallback (APScheduler থাকলে extra safety net) ──
    if _app is not None and _app.job_queue is not None:
        try:
            existing = _app.job_queue.get_jobs_by_name("dirty_immediate")
            for j in existing:
                j.schedule_removal()
            _app.job_queue.run_once(job_dirty_backup, when=3, name="dirty_immediate")
        except Exception:
            pass

mark_db_dirty = _mark_dirty  # alias

class _CursorWrapper:
      """psycopg2 cursor wrapper — SQLite compat: c.execute(...).fetchone() chaining"""
      __slots__ = ("_cur", "_conn", "_last_id", "_rowcount", "_soft", "_ret_row")

      def __init__(self, conn):
          self._conn     = conn
          self._cur      = conn.cursor(cursor_factory=psycopg2.extras.RealDictCursor)
          self._last_id  = None
          self._ret_row  = None      # INSERT … RETURNING row — fetchone আবার দেবে
          self._rowcount = 0
          self._soft     = False   # True → init/migration মোড (নিচে execute দেখুন)

      def execute(self, sql, params=None):
          if self._soft:
              # init/migration মোড: প্রতি statement নিজের savepoint-এ চলে।
              # একটা ব্যর্থ হলেও (যেমন টেবিল তখনো নেই) বাকি DDL নষ্ট হয় না —
              # ফ্রেশ DB-তেও init_db আর ক্র্যাশ করে না।
              try:
                  self._cur.execute("SAVEPOINT _sp_init")
              except psycopg2.Error:
                  try:
                      self._conn.rollback()
                      self._cur.execute("SAVEPOINT _sp_init")
                  except Exception:
                      return self
              try:
                  self._cur.execute(sql, params)
                  _soft_rc = self._cur.rowcount if self._cur.rowcount is not None else 0
                  self._cur.execute("RELEASE SAVEPOINT _sp_init")
                  self._rowcount = _soft_rc
              except psycopg2.Error as _se:
                  log.warning(f"[DB] init skip: {str(sql).strip()[:70]} → {str(_se)[:90]}")
                  try:
                      self._cur.execute("ROLLBACK TO SAVEPOINT _sp_init")
                  except Exception:
                      try: self._conn.rollback()
                      except Exception: pass
                  self._rowcount = 0
              return self
          _tq_sql = _time.perf_counter()
          try:
              self._cur.execute(sql, params)
          except psycopg2.errors.InFailedSqlTransaction:
              # আগের query fail করেছিল, transaction aborted — rollback করে clean state ফিরিয়ে আনো
              try: self._conn.rollback()
              except Exception: pass
              raise
          except psycopg2.OperationalError as _oe:
              # নেটওয়ার্ক লেভেলের error (SSL EOF / server closed) — connection মৃত
              try: self._conn.rollback()
              except Exception: pass
              if _is_transient_db_error(_oe):
                  try: self._conn.close()
                  except Exception: pass
              raise
          except psycopg2.Error:
              # যেকোনো DB error-এ transaction dirty হতে পারে — rollback করো
              try: self._conn.rollback()
              except Exception: pass
              raise
          self._rowcount = self._cur.rowcount if self._cur.rowcount is not None else 0
          try:      # কোন query ধীর — লগে ধরা পড়বে
              _dq = _time.perf_counter() - _tq_sql
              if _dq > 0.8:
                  log.warning(f"[DB-SLOW] {_dq:.2f}s {str(sql).splitlines()[0][:90]}")
          except Exception:
              pass
          if "RETURNING" in sql.upper() and sql.strip().upper().startswith("INSERT"):
              try:
                  row = self._cur.fetchone()
                  if row:
                      self._ret_row = row
                      for k in ("id", "user_id"):
                          if k in row:
                              self._last_id = row[k]
                              break
              except Exception:
                  pass
          return self

      def executemany(self, sql, seq):
          self._cur.executemany(sql, seq)
          self._rowcount = self._cur.rowcount if self._cur.rowcount is not None else 0
          return self

      def fetchone(self):
          if self._ret_row is not None:
              row, self._ret_row = self._ret_row, None
              return dict(row)
          try:
              row = self._cur.fetchone()
              return dict(row) if row else None
          except Exception:
              return None

      def fetchall(self):
          if self._ret_row is not None:
              row, self._ret_row = self._ret_row, None
              return [dict(row)]
          try:
              rows = self._cur.fetchall() or []
              return [dict(r) for r in rows]
          except Exception:
              return []

      @property
      def rowcount(self):
          return self._rowcount

      @property
      def lastrowid(self):
          return self._last_id

      def __iter__(self):
          return iter(self.fetchall())

      def __getitem__(self, idx):
          try:
              return list((self._cur.fetchone() or {}).values())[idx]
          except Exception:
              return None


