def _ensure_indexes():
    """হট কোয়েরির ইনডেক্স — একবারই তৈরি হয়, পরে ফ্ল্যাগ দেখে বাদ (বট/ওয়েব দুটোই দ্রুত হয়)।"""
    _ver = str(len(_DB_INDEX_SQL))
    try:
        if (get_setting("db_indexes_v1") or "") == _ver:
            return 0          # এই ভার্সনের সব ইনডেক্স আগেই তৈরি
    except Exception:
        pass
    ok = 0
    try:
        with _c() as c:
            # devices(user_id, device_hash) unique index বানানোর আগে পুরোনো ডুপ্লিকেট সরাও
            try:
                c.execute("DELETE FROM devices WHERE id NOT IN "
                          "(SELECT MIN(id) FROM devices GROUP BY user_id, device_hash)")
            except Exception as _de:
                log.debug(f"[IDX] devices dedupe skip: {_de}")
            for q in _DB_INDEX_SQL:
                try:
                    c.execute(q)
                    ok += 1
                except Exception as e:
                    log.debug(f"[IDX] skip {q[:48]}: {e}")
    except Exception as e:
        log.warning(f"[IDX] ইনডেক্স তৈরি ব্যর্থ: {e}")
        return 0
    if ok == len(_DB_INDEX_SQL):     # সব না হলে পরের বুটে আবার চেষ্টা (নতুন টেবিল/রাইট)
        try:
            set_setting("db_indexes_v1", _ver)
        except Exception:
            pass
    log.info(f"[IDX] {ok}/{len(_DB_INDEX_SQL)} ইনডেক্স প্রস্তুত")
    return ok


def _backfill_devices():
    """users/verifications-এ থাকা device_hash → devices টেবিলে (একবার)।
    এতে আগের ভেরিফাই করা অ্যাকাউন্টগুলোও এক-ফোন নিয়মে ধরা পড়বে।"""
    try:
        if (get_setting("devices_backfill_v1") or "") == "1":
            return 0
    except Exception:
        pass
    total = 0
    stmts = [
        # users.device_hash → devices
        "INSERT INTO devices (user_id, device_hash, ua, platform, first_seen, last_seen, ip) "
        "SELECT u.user_id, u.device_hash, '', '', COALESCE(u.verified_at,''), "
        "COALESCE(NULLIF(u.last_seen,''), u.verified_at, ''), COALESCE(u.last_ip,'') "
        "FROM users u WHERE COALESCE(u.device_hash,'') <> '' AND NOT EXISTS ("
        " SELECT 1 FROM devices d WHERE d.user_id=u.user_id AND d.device_hash=u.device_hash)",
        # verifications.device_hash → devices
        "INSERT INTO devices (user_id, device_hash, ua, platform, first_seen, last_seen, ip) "
        "SELECT v.user_id, v.device_hash, '', '', COALESCE(v.verified_at,''), "
        "COALESCE(v.verified_at,''), COALESCE(v.ip,'') "
        "FROM verifications v WHERE COALESCE(v.device_hash,'') <> '' AND NOT EXISTS ("
        " SELECT 1 FROM devices d WHERE d.user_id=v.user_id AND d.device_hash=v.device_hash)",
    ]
    try:
        with _c() as c:
            for q in stmts:
                try:
                    total += int(c.execute(q).rowcount or 0)
                except Exception as e:
                    log.debug(f"[DEVICE-BACKFILL] skip: {e}")
    except Exception as e:
        log.warning(f"[DEVICE-BACKFILL] ব্যর্থ: {e}")
        return 0
    try:
        set_setting("devices_backfill_v1", "1")
    except Exception:
        pass
    log.info(f"[DEVICE-BACKFILL] {total}টি ডিভাইস রেকর্ড যোগ হলো")
    return total


# ── Connection Pool — প্রতি query তে নতুন TCP connection খরচ বাঁচায় ──────
_conn_pool: "_pg_pool.ThreadedConnectionPool | None" = None

def _get_pool() -> "_pg_pool.ThreadedConnectionPool":
    global _conn_pool
    if _conn_pool is None or _conn_pool.closed:
        try:
            _conn_pool = _pg_pool.ThreadedConnectionPool(
                minconn=2,           # minconn বেশি হলে প্রথম রিকোয়েস্টেই ১০টা remote
                                     # connection খুলতে গিয়ে /start কয়েক সেকেন্ড আটকে যেত
                maxconn=30,          # concurrent updates বেশি হলেও pool exhaust হবে না
                dsn=DATABASE_URL,
                connect_timeout=10,
                keepalives=1,        # idle connection ড্রপ হওয়া থেকে বাঁচায়
                keepalives_idle=30,  # ৩০s idle হলে keepalive packet পাঠাও
                keepalives_interval=10,
                keepalives_count=5,
            )
        except Exception:
            _conn_pool = None
            raise
    return _conn_pool


def _warm_pool():
    """চালু হওয়ার সময়ই কয়েকটা connection তৈরি করে রাখো (প্রথম /start যেন ধীর না হয়)।"""
    try:
        _get_pool()
        with _c() as c:
            c.execute("SELECT 1").fetchone()
        log.info("[DB] pool warm-up done")
    except Exception as _e:
        log.warning(f"[DB] pool warm-up ব্যর্থ: {str(_e)[:100]}")


def _warm_pool_async():
    try:
        threading.Thread(target=_warm_pool, daemon=True, name="db-warm").start()
    except Exception:
        pass


# ── Transient (নেটওয়ার্ক) DB error — SSL EOF / server closed connection ──
_TRANSIENT_DB_HINTS = (
    "ssl syscall", "eof detected", "server closed the connection",
    "connection already closed", "terminating connection", "connection reset",
    "could not receive data", "broken pipe", "consuming input failed",
    "connection timed out", "no route to host", "ssl connection has been closed",
)

_conn_seen = {}          # id(conn) → শেষ ব্যবহারের monotonic সময়


def _is_transient_db_error(e) -> bool:
    try:
        s = str(e).lower()
    except Exception:
        return False
    return any(h in s for h in _TRANSIENT_DB_HINTS)


def _reset_pool():
    """ভাঙা/stale connection-এ ভরা pool ফেলে নতুন pool বানায় (হালকা, নিরাপদ)।"""
    global _conn_pool
    try:
        old = _conn_pool
        _conn_pool = None
        if old is not None:
            try:
                old.closeall()
            except Exception:
                pass
    except Exception:
        _conn_pool = None
    try:
        _conn_seen.clear()
    except Exception:
        pass
    log.info("[DB] connection pool রিসেট করা হয়েছে")


def _ping_conn(conn) -> bool:
    """Connection এখনো জীবিত কি না — হালকা SELECT 1।"""
    try:
        cur = conn.cursor()
        cur.execute("SELECT 1")
        cur.fetchone()
        cur.close()
        return True
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        return False


class _ConnCtx:
    """with _c() as c: → pool থেকে connection নাও, শেষে ফিরিয়ে দাও।

    • stale (সার্ভার বন্ধ করে দেওয়া) connection ধরা পড়লে ফেলে নতুন নেয়
    • প্রথম চেষ্টায় ব্যর্থ হলে pool রিসেট করে আবার চেষ্টা করে
    """
    __slots__ = ("_conn", "_wrapper", "_from_pool")

    def _drop(self):
        try:
            if self._conn is not None:
                try:
                    _conn_seen.pop(id(self._conn), None)
                except Exception:
                    pass
                if self._from_pool:
                    try:
                        _get_pool().putconn(self._conn, close=True)
                    except Exception:
                        try: self._conn.close()
                        except Exception: pass
                else:
                    try: self._conn.close()
                    except Exception: pass
        except Exception:
            pass
        self._conn = None

    def __enter__(self):
        _last = None
        for _attempt in range(2):
            self._from_pool = False
            self._conn = None
            try:
                self._conn = _get_pool().getconn()
                self._from_pool = True
            except Exception as _pe:
                _last = _pe
                _reset_pool()
                try:
                    self._conn = psycopg2.connect(DATABASE_URL,
                                                  connect_timeout=10)
                    self._from_pool = False
                except Exception as _de:
                    _last = _de
                    self._conn = None
            if self._conn is None:
                continue
            try:
                self._conn.autocommit = False
            except Exception:
                pass
            if getattr(self._conn, "closed", 0):
                self._drop()
                continue
            # ১৫s+ পড়ে থাকা connection জীবিত কিনা দেখে নাও (stale → SSL EOF ঠেকায়)
            try:
                _prev = _conn_seen.get(id(self._conn), 0)
                if _prev and (_time.monotonic() - _prev) > 15:
                    if not _ping_conn(self._conn):
                        self._drop()
                        continue
            except Exception:
                pass
            self._wrapper = _CursorWrapper(self._conn)
            return self._wrapper
        raise _last or psycopg2.OperationalError("DB connection পাওয়া যায়নি")

    def __exit__(self, exc_type, exc_val, exc_tb):
        _broken = False
        _commit_err = None
        if exc_type is None:
            try:
                self._conn.commit()
            except Exception as _ce:
                _broken = True
                _commit_err = _ce
                try: self._conn.rollback()
                except Exception: pass
        else:
            _broken = True
            try: self._conn.rollback()
            except Exception: pass
        # সুস্থ connection-এর শেষ ব্যবহারের সময় মনে রাখো (stale ধরার জন্য)
        try:
            if not _broken and self._conn is not None and not getattr(self._conn, "closed", 0):
                if len(_conn_seen) > 200:
                    _conn_seen.clear()
                _conn_seen[id(self._conn)] = _time.monotonic()
        except Exception:
            pass
        # Error হলে ভাঙা connection pool-এ ফেরত না দিয়ে বন্ধ করো
        if self._from_pool:
            try:
                pool = _get_pool()
                pool.putconn(self._conn, close=_broken)
            except Exception:
                try: self._conn.close()
                except Exception: pass
        else:
            try: self._conn.close()
            except Exception: pass
        # Commit fail হলে caller কে জানাও — silent failure বন্ধ
        if _commit_err is not None:
            raise _commit_err
        return False


def _c():
    return _ConnCtx()


_COCKROACH_RETRY_KEYS = ("SerializationFailure", "TransactionRetry", "restart transaction")

def _db_with_retry(fn, max_tries=4):
    """CockroachDB SerializationFailure auto-retry — nested _db_NNNN() function wrap করো।
    Usage: result = await asyncio.to_thread(_db_with_retry, _db_func)
    """
    for _attempt in range(max_tries):
        try:
            return fn()
        except Exception as _e:
            if _attempt < max_tries - 1 and any(k in str(_e) for k in _COCKROACH_RETRY_KEYS):
                _time.sleep(0.05 * (2 ** _attempt))  # 50ms, 100ms, 200ms backoff
                continue
            raise


def _rget(row, key, default=None):
    """dict row থেকে safe get।"""
    if row is None:
        return default
    try:
        v = row[key]
        return default if v is None else v
    except (KeyError, TypeError, IndexError):
        return default


def _md_esc(text: str) -> str:
    """Telegram Markdown v1-এ special characters escape করো যাতে parse error না হয়।"""
    if not text: return text
    for ch in ['_', '*', '`', '[']:
        text = text.replace(ch, f'\\{ch}')
    return text

def _is_md_parse_err(e) -> bool:
    s = str(e).lower()
    return "can't parse entities" in s or "can't find end" in s or "parse entities" in s

_MD_FALLBACK_PATCHED = False

def patch_bot_markdown_fallback(bot):
    """
    Global safety net: কোথাও যদি ভুলবশত escape না করা raw text
    parse_mode="Markdown"/"MarkdownV2" দিয়ে পাঠানো হয় এবং Telegram
    'Can't parse entities' error দেয়, তাহলে স্বয়ংক্রিয়ভাবে plain text
    (parse_mode ছাড়া) দিয়ে retry করবে — যাতে মেসেজ পাঠানোই সম্পূর্ণ ব্যর্থ না হয়।
    এটা bot.send_message/send_photo/edit_message_text/edit_message_caption
    সব জায়গায় কাজ করে, কারণ message.reply_text()/reply_photo() ভিতরে
    এই একই bot method গুলোই কল করে।

    গুরুত্বপূর্ণ: python-telegram-bot এর Bot/ExtBot ক্লাস __slots__ ব্যবহার
    করে, তাই bot.send_message = ... (instance attribute) সেট করলে
    "Attribute can't be set" crash হয়। তাই ইনস্ট্যান্স নয়, ক্লাসের উপর
    (type(bot)) patch করতে হবে।
    """
    global _MD_FALLBACK_PATCHED
    if _MD_FALLBACK_PATCHED:
        return
    cls = type(bot)
    _orig = {
        "send_message":         cls.send_message,
        "send_photo":           cls.send_photo,
        "edit_message_text":    cls.edit_message_text,
        "edit_message_caption": cls.edit_message_caption,
    }

    def _wrap(name):
        _orig_fn = _orig[name]
        async def _wrapped(self, *args, **kwargs):
            try:
                return await _orig_fn(self, *args, **kwargs)
            except TgBadRequest as e:
                if kwargs.get("parse_mode") and _is_md_parse_err(e):
                    log.warning(f"[MD-FALLBACK] {name}: parse error ধরা পড়েছে, plain text এ fallback করা হচ্ছে — {e}")
                    kwargs["parse_mode"] = None
                    return await _orig_fn(self, *args, **kwargs)
                raise
        return _wrapped

    cls.send_message         = _wrap("send_message")
    cls.send_photo           = _wrap("send_photo")
    cls.edit_message_text    = _wrap("edit_message_text")
    cls.edit_message_caption = _wrap("edit_message_caption")
    _MD_FALLBACK_PATCHED = True

def _count(row):
    """RealDictCursor COUNT(*)/COALESCE result থেকে int বের করো।"""
    if row is None:
        return 0
    if isinstance(row, dict):
        for v in row.values():
            try: return int(v) if v is not None else 0
            except (TypeError, ValueError): pass
        return 0
    try:
        return int(list(row.values())[0])
    except Exception:
        return 0
# ═══════════════════ SECURITY / VERIFICATION (Phase 1) ═══════════════════
# নতুন টেবিল/কলাম সবই additive — পুরোনো user/balance/task/withdrawal ডেটা অক্ষত।
try:
    import vtoken as _vtoken
except Exception:      # file না থাকলেও verification চলবে — নিচে inline fallback
    _vtoken = None


class _InlineToken:
    """vtoken.py না থাকলে একই base64+HMAC অ্যালগরিদমে টোকেন (panel-ও এটাই বোঝে)।"""

    DEFAULT_TTL = 24 * 3600

    @staticmethod
    def _secret():
        import hashlib as _h, os as _o
        s = (_o.environ.get("VERIFY_SECRET") or "").strip()
        if not s:
            s = (_o.environ.get("BOT_TOKEN") or "").strip()
        if not s:
            s = "task-earn-bot-verify-fallback"
        return s.encode("utf-8")

    @classmethod
    def _sign(cls, body):
        import hashlib as _h, hmac as _hm
        return _hm.new(cls._secret(), body.encode("utf-8"), _h.sha256).hexdigest()[:24]

    @classmethod
    def make_token(cls, uid, ttl=DEFAULT_TTL):
        import base64 as _b64
        exp = int(_time.time()) + int(ttl)
        body = f"{int(uid)}.{exp}"
        raw = f"{body}.{cls._sign(body)}"
        return _b64.urlsafe_b64encode(raw.encode("utf-8")).decode("ascii").rstrip("=")

    @classmethod
    def parse_token(cls, token):
        import base64 as _b64, hmac as _hm
        if not token:
            return None
        try:
            pad = "=" * (-len(token) % 4)
            raw = _b64.urlsafe_b64decode((token + pad).encode("ascii")).decode("utf-8")
            uid_s, exp_s, sig = raw.rsplit(".", 2)
            if not _hm.compare_digest(sig, cls._sign(f"{uid_s}.{exp_s}")):
                return None
            if int(exp_s) < int(_time.time()):
                return None
            return int(uid_s)
        except Exception:
            return None


def _vrf_tok():
    """vtoken মডিউল থাকলে সেটাই, নাহলে inline fallback।"""
    return _vtoken if _vtoken is not None else _InlineToken

