def _col_missing(err) -> bool:
    """'column ... does not exist' ধাঁচের এরর? (পুরোনো DB / আধা-মাইগ্রেটেড)"""
    t = str(err).lower()
    return ("does not exist" in t or "undefined column" in t) and "column" in t


def _users_have_all_columns(table: str = "users") -> bool:
    """একটাই হালকা কোয়েরি — সব কলাম আগেই আছে কি না (থাকলে ১৭টা DDL বাঁচে)।"""
    want = {q.split("EXISTS")[1].split()[0].lower() for q in _USERS_COLUMN_SQL}
    try:
        with _c() as c:
            rows = c.execute(
                "SELECT column_name FROM information_schema.columns WHERE table_name=%s",
                (table,)).fetchall()
        have = {str(r["column_name"] or "").lower() for r in rows}
        return bool(have) and want.issubset(have)
    except Exception:
        return False          # চেক ব্যর্থ → নিরাপদ দিকে, migration চালাও


def _ensure_users_columns(table: str = "users"):
    """users-এর সব দরকারি কলাম নিশ্চিত করো — প্রতিবার শুরুতে, ব্যর্থ হলেও বট চলবে।"""
    if _users_have_all_columns(table):
        log.info("[MIGRATE] users কলাম আগেই আছে — DDL লাগবে না")
        return True
    ok, miss = 0, []
    try:
        with _c() as c:
            for q in _USERS_COLUMN_SQL:
                try:
                    c.execute(q if table == "users" else q.replace("users", table, 1))
                    ok += 1
                except Exception as e:
                    miss.append(str(e)[:80])
                    try:
                        log.warning(f"[MIGRATE] {q.split('EXISTS')[1].strip()[:40]} ব্যর্থ: {e}")
                    except Exception:
                        pass
    except Exception as e:
        log.warning(f"[MIGRATE] কলাম মাইগ্রেশন ব্যর্থ: {e}")
        return False
    if miss:
        log.warning(f"[MIGRATE] {len(miss)} কলাম যোগ হয়নি ({ok} ok)")
    else:
        log.info(f"[MIGRATE] users কলাম প্রস্তুত ({ok}/{len(_USERS_COLUMN_SQL)})")
    return not miss


def init_security_db():
    """Verification/security টেবিল + users এর নতুন কলাম তৈরি (idempotent)।"""
    _t0 = _time.time()
    # ── v2: vrf_pass কলাম — v1 ফ্ল্যাগ থাকলেও এই মাইগ্রেশন চলবে ──
    try:
        _ensure_users_columns()      # ⚠️ ফ্ল্যাগ নির্বিশেষে সবসময় — পুরোনো DB-তে নতুন কলাম যোগ হয়
        if (get_setting("security_schema_v2") or "") != "1":
            with _c() as _c2:
                _c2.execute("ALTER TABLE users ADD COLUMN IF NOT EXISTS vrf_pass INTEGER DEFAULT 0")
            set_setting("security_schema_v2", "1")
            log.info("[SECURITY-DB] v2 কলাম vrf_pass প্রস্তুত")
        _SEC_STATE["v2"] = "done"
    except Exception as _v2e:
        log.warning(f"[SECURITY-DB] v2 কলাম ব্যর্থ (verification বন্ধ থাকবে): {_v2e}")
    # ⚠️ আগে এখানে "schema_v1" ফ্ল্যাগ থাকলে পুরো DDL বাদ যেত → পরে যোগ করা কলাম/টেবিল
    # পুরোনো DB-তে তৈরি হতো না ("column vrf_notice_build does not exist")।
    # এখন CREATE ... IF NOT EXISTS গুলো প্রতিবার চলে (দ্রুত, idempotent) — drift হবে না।
    try:
        with _SafeDDL() as c:
            c.execute(
                """
                CREATE TABLE IF NOT EXISTS verifications (
                    user_id     BIGINT PRIMARY KEY,
                    status      TEXT DEFAULT 'pending',
                    method      TEXT DEFAULT 'web',
                    attempts    INTEGER DEFAULT 0,
                    created_at  TEXT DEFAULT '',
                    verified_at TEXT DEFAULT '',
                    ip          TEXT DEFAULT '',
                    country     TEXT DEFAULT '',
                    device_hash TEXT DEFAULT ''
                )
                """
            )
            c.execute(
                """
                CREATE TABLE IF NOT EXISTS devices (
                    id          BIGSERIAL PRIMARY KEY,
                    user_id     BIGINT,
                    device_hash TEXT,
                    ua          TEXT DEFAULT '',
                    platform    TEXT DEFAULT '',
                    first_seen  TEXT DEFAULT '',
                    last_seen   TEXT DEFAULT '',
                    ip          TEXT DEFAULT ''
                )
                """
            )
            c.execute(
                """
                CREATE TABLE IF NOT EXISTS user_ips (
                    user_id      BIGINT,
                    ip           TEXT,
                    country_code TEXT DEFAULT '',
                    country      TEXT DEFAULT '',
                    city         TEXT DEFAULT '',
                    isp          TEXT DEFAULT '',
                    first_seen   TEXT DEFAULT '',
                    last_seen    TEXT DEFAULT '',
                    hits         INTEGER DEFAULT 1,
                    PRIMARY KEY (user_id, ip)
                )
                """
            )
            c.execute(
                """
                CREATE TABLE IF NOT EXISTS ip_history (
                    id           BIGSERIAL PRIMARY KEY,
                    user_id      BIGINT,
                    ip           TEXT,
                    country_code TEXT DEFAULT '',
                    seen_at      TEXT DEFAULT ''
                )
                """
            )
            c.execute(
                """
                CREATE TABLE IF NOT EXISTS ip_geo_cache (
                    ip           TEXT PRIMARY KEY,
                    country_code TEXT DEFAULT '',
                    country      TEXT DEFAULT '',
                    city         TEXT DEFAULT '',
                    isp          TEXT DEFAULT '',
                    is_mobile    INTEGER DEFAULT -1,
                    is_vpn       INTEGER DEFAULT -1,
                    created_at   TEXT DEFAULT ''
                )
                """
            )
            for _ddl in ("ALTER TABLE ip_geo_cache ADD COLUMN IF NOT EXISTS is_mobile INTEGER DEFAULT -1",
                         "ALTER TABLE ip_geo_cache ADD COLUMN IF NOT EXISTS is_vpn INTEGER DEFAULT -1"):
                try:
                    c.execute(_ddl)
                except Exception:
                    pass
            c.execute(
                """
                CREATE TABLE IF NOT EXISTS task_notify_queue (
                    id         BIGSERIAL PRIMARY KEY,
                    kind       TEXT DEFAULT '',
                    task_id    BIGINT DEFAULT 0,
                    user_id    BIGINT DEFAULT 0,
                    msg        TEXT DEFAULT '',
                    created_at TEXT DEFAULT '',
                    processed  INTEGER DEFAULT 0
                )
                """
            )
            for _ddl in ("ALTER TABLE task_notify_queue ADD COLUMN IF NOT EXISTS user_id BIGINT DEFAULT 0",
                         "ALTER TABLE task_notify_queue ADD COLUMN IF NOT EXISTS msg TEXT DEFAULT ''"):
                try:
                    c.execute(_ddl)
                except Exception:
                    pass
            c.execute(
                """
                CREATE TABLE IF NOT EXISTS security_alerts (
                    id          BIGSERIAL PRIMARY KEY,
                    kind        TEXT DEFAULT '',
                    user_id     BIGINT DEFAULT 0,
                    related_uid BIGINT DEFAULT 0,
                    ip          TEXT DEFAULT '',
                    country     TEXT DEFAULT '',
                    device_hash TEXT DEFAULT '',
                    detail      TEXT DEFAULT '',
                    status      TEXT DEFAULT 'new',
                    created_at  TEXT DEFAULT '',
                    handled_by  BIGINT DEFAULT 0,
                    handled_at  TEXT DEFAULT ''
                )
                """
            )
            c.execute(
                """
                CREATE TABLE IF NOT EXISTS admin_actions (
                    id         BIGSERIAL PRIMARY KEY,
                    admin_id   BIGINT DEFAULT 0,
                    action     TEXT DEFAULT '',
                    target_uid BIGINT DEFAULT 0,
                    detail     TEXT DEFAULT '',
                    ip         TEXT DEFAULT '',
                    created_at TEXT DEFAULT ''
                )
                """
            )
            _ensure_users_columns()
            log.info(f"[SECURITY-DB] tables+columns ready ({_time.time() - _t0:.1f}s)")
    except Exception as _e:
        log.error(f"[SECURITY-DB] init ব্যর্থ: {_e}")
        return
    # ── schema তৈরি → ফ্ল্যাগ সেভ (পরের রিস্টার্টে DDL একেবারে বাদ) ──
    try:
        set_setting("security_schema_v1", "1")
    except Exception as _sfe:
        log.warning(f"[SECURITY-DB] schema flag ব্যর্থ: {_sfe}")
    _SEC_STATE["schema"] = "done"
    log.info(f"[SECURITY-DB] schema প্রস্তুত ({_time.time() - _t0:.1f}s)")


_SEC_STATE = {"schema": "pending", "v2": "pending", "grandfather": "pending"}


def _security_heavy_init():
    """ইনডেক্স + grandfather — আলাদা thread-এ, বট চালু আটকাবে না।
    grandfather শেষ না হওয়া পর্যন্ত verification বন্ধ থাকবে (কেউ আটকাবে না)।"""
    _t0 = _time.time()
    for _idx in (
        "CREATE INDEX IF NOT EXISTS idx_users_country ON users(country)",
        "CREATE INDEX IF NOT EXISTS idx_users_verified ON users(verified)",
        "CREATE INDEX IF NOT EXISTS idx_wd_user_status ON withdrawals(user_id, status)",
        "CREATE INDEX IF NOT EXISTS idx_devices_hash ON devices(device_hash)",
        "CREATE INDEX IF NOT EXISTS idx_user_ips_ip ON user_ips(ip)",
        "CREATE INDEX IF NOT EXISTS idx_ip_hist_user ON ip_history(user_id)",
        "CREATE INDEX IF NOT EXISTS idx_alerts_created ON security_alerts(created_at)",
    ):
        try:
            with _c() as cc:
                cc.execute(_idx)
            log.info(f"[SECURITY-DB] index ok: {_idx.split()[5]} ({_time.time() - _t0:.1f}s)")
        except Exception as _ie:
            log.warning(f"[SECURITY-DB] index skip: {_ie}")
    try:
        if (get_setting("security_grandfather_done") or "") == "1":
            _SEC_STATE["grandfather"] = "done"
            log.info("[SECURITY-DB] grandfather আগেই হয়েছে — verification ON")
            return
        with _c() as cc:
            cc.execute(
                "UPDATE users SET verified=1, "
                "verified_at=CASE WHEN COALESCE(verified_at,'')='' "
                "THEN COALESCE(joined_at,'') ELSE verified_at END "
                "WHERE COALESCE(verified,0)=0"
            )
        set_setting("security_grandfather_done", "1")
        _SEC_STATE["grandfather"] = "done"
        log.info(f"[SECURITY-DB] grandfather সম্পন্ন ({_time.time() - _t0:.1f}s) → verification ON")
    except Exception as _ge:
        log.error(f"[SECURITY-DB] grandfather ব্যর্থ — verification বন্ধ থাকবে: {_ge}")


def _security_boot():
    """startup-এর security কাজ (DDL → ইনডেক্স → grandfather) — পুরোটাই background।"""
    try:
        init_security_db()
    except Exception as _e:
        log.error(f"[SECURITY-DB] boot DDL ব্যর্থ: {_e}")
    if _SEC_STATE.get("schema") != "done":
        log.error("[SECURITY-DB] schema তৈরি হয়নি — verification বন্ধ থাকবে")
        return
    try:
        _security_heavy_init()
    except Exception as _e:
        log.error(f"[SECURITY-DB] heavy init ব্যর্থ: {_e}")
    log.info(
        "[VRF] enabled=%s state=%s base=%s token=%s",
        verify_enabled(), dict(_SEC_STATE), _vrf_panel_base() or "-",
        "vtoken.py" if _vtoken else "inline",
    )


def verify_enabled():
    """Verification চালু কি না — শুধু vrf_pass কলাম + লিংক + সেটিং দেখে।
    (schema/grandfather আটকে গেলেও verification চলবে — নতুন ফ্লো তাদের উপর নির্ভর করে না।)"""
    if _SEC_STATE.get("v2") != "done":
        return False
    if _vrf_panel_base() == "":
        return False
    try:
        return (get_setting("verify_enabled") or "on") != "off"
    except Exception:
        return True


def vrf_is_verified(uid):
    """DB থেকে verified স্ট্যাটাস। DB error হলে True (ইউজার আটকে না যায়)।"""
    try:
        with _c() as c:
            r = c.execute("SELECT verified FROM users WHERE user_id=%s", (uid,)).fetchone()
        if not r:
            return True
        return int(r["verified"] or 0) == 1
    except Exception:
        return True


def vrf_pass_on(uid):
    """নতুন verification ফ্লো পার হয়েছে কি না (vrf_pass=1)।
    DB error হলে True — কেউ ভুল করে আটকে না যায়।"""
    try:
        with _c() as c:
            r = c.execute("SELECT vrf_pass FROM users WHERE user_id=%s", (uid,)).fetchone()
        if not r:
            return False
        return int(_fval(r, 0) or 0) == 1
    except Exception:
        return True


def vrf_mark_pass(uid):
    _VRF_SILENT_MEMO.pop(uid, None)   # verify সফল → সাথে সাথে বট কথা বলবে
    try:
        with _c() as c:
            c.execute("UPDATE users SET vrf_pass=1 WHERE user_id=%s", (uid,))
    except Exception as _e:
        log.debug(f"[VRF] pass mark ব্যর্থ uid={uid}: {_e}")


_VRF_SILENT_MEMO: "dict[int, tuple[bool, float]]" = {}   # uid → (silent?, monotonic ts)
_VRF_SILENT_TTL = 20.0  # verify/ব্যান পথগুলো নিজেরাই memo ক্লিয়ার করে, তাই ২০s নিরাপদ


def _vrf_silent_now(uid):
    """মেমো ছাড়া আসল কাজ: verify on? vrf_pass? (২টি DB/setting চেক)"""
    try:
        if not verify_enabled():
            return False
    except Exception:
        return False
    # ADMIN-ও ব্যতিক্রম নয় — তাকেও /start + verify করতে হবে
    return not vrf_pass_on(uid)


def vrf_silent(uid):
    """True = বট এই ইউজারকে কোনো উত্তর দেবে না।
    verify + /start এর আগে বট পুরোপুরি চুপ (শুধু /start আর verify বাটন কাজ করে)।
    ⚡ ৩ সেকেন্ডের মেমো: এক আপডেটে _gate + on_callback + guard ২-৩ বার ডাক করে এবং
    রিসেটের পর সবাই unverified — প্রতি ডাকে DB SELECT যাওয়া যেত, এখন ১ বারই যায়।"""
    now_ts = _time.monotonic()
    m = _VRF_SILENT_MEMO.get(uid)
    if m is not None and now_ts - m[1] < _VRF_SILENT_TTL:
        return m[0]
    res = _vrf_silent_now(uid)
    if len(_VRF_SILENT_MEMO) > 5000:   # memory bounded
        for _k in [k for k, (_, t) in _VRF_SILENT_MEMO.items() if now_ts - t >= _VRF_SILENT_TTL]:
            del _VRF_SILENT_MEMO[_k]
    _VRF_SILENT_MEMO[uid] = (res, now_ts)
    return res


# ═══════════ SECURITY PHASE 2 — মাল্টি-অ্যাকাউন্ট ডিটেকশন ═══════════
# একই ডিভাইস (device hash) বা একই IP-তে বেশি অ্যাকাউন্ট = ব্যান + অ্যাডমিন অ্যালার্ট।
# সব কিছু fail-safe: কোনো ধাপ ব্যর্থ হলে ইউজার আটকাবে না।
_SEC_CHK_TS = {}


def _sec_cfg():
    """setting থেকে থ্রেশহোল্ড (না থাকলে ডিফল্ট)।"""
    def _int(key, default):
        try:
            return int(get_setting(key) or default)
        except Exception:
            return default
    try:
        auto = (get_setting("sec_auto_ban") or "on").strip().lower() != "off"
    except Exception:
        auto = True
    try:
        # ডিফল্ট off — মোবাইল CGNAT-এ এক IP-তে শত শত ইউজার, ব্লক করলে আসল ইউজার আটকাবে
        ip_block = (get_setting("sec_ip_block") or "off").strip().lower() == "on"
    except Exception:
        ip_block = False
    return {
        # ১ ফোন = ১ অ্যাকাউন্ট; এক IP-তে ২টি পর্যন্ত (VPN/মোবাইল NAT — IP শুধু সতর্কতা)
        "device_limit": max(1, _int("sec_device_limit", 1)),
        "ip_limit": max(1, _int("sec_ip_limit", 1)),
        "auto_ban": auto,
        "ip_block": ip_block,
    }


def sec_multi_scan(uid):
    """একই ডিভাইস/আইপিতে অন্য কতজন — গুনে রিপোর্ট দেয়।"""
    out = {"device_hash": "", "ip": "", "country": "", "device_n": 1, "ip_n": 1}
    try:
        with _c() as c:
            r = c.execute(
                "SELECT device_hash, last_ip, reg_ip, reg_country FROM users WHERE user_id=%s", (uid,)
            ).fetchone()
    except Exception as _e:
        log.warning(f"[SEC2] scan user পড়া যায়নি uid={uid}: {_e}")
        return out
    if not r:
        return out
    dh = (r["device_hash"] or "") if r["device_hash"] else ""
    ip = (r["last_ip"] or r["reg_ip"] or "") if (r["last_ip"] or r["reg_ip"]) else ""
    out["device_hash"] = dh
    out["ip"] = ip
    out["country"] = (r["reg_country"] or "") if r["reg_country"] else ""
    # users.device_hash ফাঁকা হলে verifications থেকে নাও — পুরোনো ইউজারও ধরা পড়বে
    if not dh:
        try:
            with _c() as c:
                _v = c.execute(
                    "SELECT device_hash FROM verifications WHERE user_id=%s "
                    "AND COALESCE(device_hash,'')<>'' "
                    "ORDER BY COALESCE(verified_at,'') DESC LIMIT 1",
                    (uid,)).fetchone()
            if _v and _v["device_hash"]:
                dh = str(_v["device_hash"])
                out["device_hash"] = dh
        except Exception as _e:
            log.debug(f"[SEC2] verifications device পড়া যায়নি: {_e}")
    if dh:
        try:
            with _c() as c:
                n = c.execute(
                    "SELECT COUNT(DISTINCT user_id) AS n FROM devices WHERE device_hash=%s AND user_id<>%s",
                    (dh, uid),
                ).fetchone()
            out["device_n"] = int(_count(n)) + 1
        except Exception as _e:
            log.debug(f"[SEC2] device count ব্যর্থ: {_e}")
    if ip:
        try:
            with _c() as c:
                n1 = c.execute(
                    "SELECT COUNT(DISTINCT user_id) AS n FROM user_ips WHERE ip=%s AND user_id<>%s",
                    (ip, uid),
                ).fetchone()
                n2 = c.execute(
                    "SELECT COUNT(DISTINCT user_id) AS n FROM users "
                    "WHERE (last_ip=%s OR reg_ip=%s) AND user_id<>%s",
                    (ip, ip, uid),
                ).fetchone()
            out["ip_n"] = max(int(_count(n1)), int(_count(n2))) + 1
        except Exception as _e:
            log.debug(f"[SEC2] ip count ব্যর্থ: {_e}")
    return out


def _unban_iponly_sync():
    """শুধু IP-জনিত কারণে ব্যান হওয়া অ্যাকাউন্ট আনব্যান (ডিভাইস রুল লঙ্ঘনকারী নয়)।"""
    out = []
    try:
        with _c() as c:
            rows = c.execute(
                "SELECT user_id, ban_reason FROM users WHERE COALESCE(is_banned,0)=1"
            ).fetchall()
        for r in rows:
            rsn = r["ban_reason"] or ""
            low = rsn.lower()
            if "ip" not in low:
                continue
            if "ডিভাইস" in rsn or "device" in low:
                continue
            out.append(int(r["user_id"]))
        for _u in out:
            with _c() as c:
                c.execute("UPDATE users SET is_banned=0, ban_reason='' WHERE user_id=%s", (_u,))
            try:
                _invalidate_user_cache(_u)
            except Exception:
                pass
    except Exception as e:
        log.warning(f"[SEC2] unban_iponly ব্যর্থ: {e}")
    return len(out)


def sec_add_alert(kind, uid, related_uid=0, ip="", country="", device_hash="", detail=""):
    try:
        with _c() as c:
            c.execute(
                "INSERT INTO security_alerts (kind, user_id, related_uid, ip, country, "
                "device_hash, detail, status, created_at) VALUES (%s,%s,%s,%s,%s,%s,%s,'new',%s)",
                (kind, uid, related_uid, ip, country, device_hash, str(detail)[:500], now()),
            )
    except Exception as _e:
        log.warning(f"[SEC2] alert সেভ ব্যর্থ uid={uid}: {_e}")


def sec_set_flags(uid, ban=False, risk=0, reason=""):
    """is_suspicious/risk_score/ban সেট (প্রতিটাAlাদা, fail-safe)।"""
    try:
        with _c() as c:
            c.execute(
                "UPDATE users SET is_suspicious=1, risk_score=COALESCE(risk_score,0)+%s WHERE user_id=%s",
                (int(risk), uid),
            )
    except Exception as _e:
        log.debug(f"[SEC2] suspicion flag ব্যর্থ uid={uid}: {_e}")
    if not ban:
        return True
    try:
        with _c() as c:
            c.execute(
                "UPDATE users SET is_banned=1, ban_reason=%s WHERE user_id=%s",
                (str(reason)[:200], uid),
            )
        try:
            _invalidate_user_cache(uid)
        except Exception:
            pass
        return True
    except Exception as _e:
        log.warning(f"[SEC2] ban ব্যর্থ uid={uid}: {_e}")
        return False


async def sec_after_verify(bot, uid, lang="bn"):
    """verification সফল হওয়ার পর একবার মাল্টি-অ্যাকাউন্ট চেক (১২ ঘণ্টায় একবার)।"""
    if uid == ADMIN_ID:
        return
    _now_ts = _time.time()
    if (_now_ts - _SEC_CHK_TS.get(uid, 0)) < 12 * 3600:
        return
    _SEC_CHK_TS[uid] = _now_ts
    try:
        info = await asyncio.to_thread(sec_multi_scan, uid)
    except Exception as _e:
        log.warning(f"[SEC2] scan ব্যর্থ uid={uid}: {_e}")
        return
    cfg = _sec_cfg()
    # limit=1 → দ্বিতীয় অ্যাকাউন্টেই ধরা পড়বে (নিজে বাদ দিয়ে গোনা হয়)
    device_hit = int(info["device_n"]) > cfg["device_limit"]
    ip_hit = int(info["ip_n"]) > cfg["ip_limit"]
    if not (device_hit or ip_hit):
        return
    if ip_hit and not device_hit:
        # ── শুধু IP মিলেছে (VPN/মোবাইল NAT-এ সাধারণ ব্যাপার) → ব্যান নয়, শুধু নোট ──
        try:
            await asyncio.to_thread(
                sec_add_alert, "suspicious_ip", uid, 0, info["ip"], info["country"],
                info["device_hash"], f"একই IP-তে {info['ip_n']}টি অ্যাকাউন্ট (ব্যান হয়নি)",
            )
        except Exception as _ie:
            log.debug(f"[SEC2] ip note ব্যর্থ uid={uid}: {_ie}")
        return
    why = []
    if device_hit:
        why.append(f"একই ডিভাইসে {info['device_n']}টি অ্যাকাউন্ট")
    if ip_hit:
        why.append(f"একই IP-তে {info['ip_n']}টি অ্যাকাউন্ট")
    detail = " | ".join(why)
    banned = False
    if device_hit and cfg["auto_ban"]:
        banned = await asyncio.to_thread(
            sec_set_flags, uid, True, 40, f"multi-account: {detail}"
        )
    else:
        await asyncio.to_thread(sec_set_flags, uid, False, 15, detail)
    await asyncio.to_thread(
        sec_add_alert, "multi_account", uid, 0, info["ip"], info["country"],
        info["device_hash"], detail,
    )
    # ── অ্যাডমিনকে সাথে সাথে জানাও (Settings → Notifications বন্ধ থাকলে DM যাবে না;
    #    alert সবসময় security_alerts টেবিলে থাকে) ──
    try:
        if (await asyncio.to_thread(get_setting, "notify_security") or "on") == "off":
            raise RuntimeError("notify_security off")
        u = await asyncio.to_thread(get_user, uid)
        uname = (u.get("username") or "") if u else ""
        fname = (u.get("full_name") or "") if u else ""
        bal = (u.get("balance") if u else 0) or 0
        rows = [[
            InlineKeyboardButton("✅ Unban", callback_data=f"sec_unban_{uid}"),
            InlineKeyboardButton("🗑 Ignore", callback_data=f"sec_ignore_{uid}"),
        ]]
        await bot.send_message(
            ADMIN_ID,
            "🚨 *মাল্টি-অ্যাকাউন্ট সনাক্ত*\n\n"
            f"👤 ইউজার: [{_md_esc(fname) or 'User'}](tg://user?id={uid})\n"
            f"🆔 `{uid}`" + (f" (@{uname})" if uname else "") + "\n"
            f"💰 ব্যালান্স: `{round(float(bal), 4)}$`\n\n"
            f"📱 {detail}\n"
            f"🌐 IP: `{info['ip'] or '-'}`\n"
            f"🔑 Device: `{(info['device_hash'] or '-')[:16]}`\n\n"
            f"{'🚫 অ্যাকাউন্ট ব্যান করা হয়েছে' if banned else '⚠️ সন্দেহজনক হিসেবে চিহ্নিত (ব্যান নয়)'}",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup(rows),
            disable_web_page_preview=True,
        )
    except Exception as _e:
        log.warning(f"[SEC2] admin alert পাঠানো যায়নি: {_e}")
    if banned:
        try:
            await bot.send_message(
                uid,
                "🚫 *আপনার অ্যাকাউন্ট ব্যান করা হয়েছে*\n\n"
                "একই ডিভাইসে একাধিক অ্যাকাউন্ট ব্যবহার ধরা পড়েছে।\n"
                "ভুল মনে হলে অ্যাডমিনের সাথে যোগাযোগ করুন।"
                if lang != "en" else
                "🚫 *Your account has been banned*\n\n"
                "Multiple accounts on the same device were detected.\n"
                "Contact the admin if you think this is a mistake.",
                parse_mode="Markdown",
            )
        except Exception:
            pass


def _ip_retention_once():
    """Settings → IP data retention (দিন): user_ips/ip_history এর পুরোনো row মুছে দেয়।
    ডিফল্ট ৯০ দিন; খালি/ভুল মান হলে ৯০ ধরা হয়। কাজ না থাকলে ০ রিটার্ন, ক্র্যাশ নয়।"""
    try:
        _v = (get_setting("sec_ip_retention_days") or "").strip()
        days = int(_v) if _v.isdigit() else 90
    except Exception:
        days = 90
    if days < 1:
        return 0
    # panel.py epoch-second স্ট্রিং রাখে (user_ips.last_seen / ip_history.seen_at)
    _cut = str(int((datetime.now(timezone.utc) - timedelta(days=days)).timestamp()))
    n = 0
    try:
        with _c() as c:
            cur = c.execute(
                "DELETE FROM user_ips  WHERE last_seen ~ '^[0-9]+$' AND last_seen < %s", (_cut,))
            n += int(cur.rowcount or 0)
            cur = c.execute(
                "DELETE FROM ip_history WHERE seen_at ~ '^[0-9]+$' AND seen_at < %s", (_cut,))
            n += int(cur.rowcount or 0)
    except Exception as _e:
        log.warning(f"[RETENTION] cleanup ব্যর্থ: {_e}")
        return 0
    if n:
        log.info(f"[RETENTION] {days} দিনের পুরোনো IP row মুছেছে: {n}")
    return n


async def _ip_retention_loop():
    """১২ ঘণ্টায় একবার IP retention cleanup চালায়।"""
    while True:
        try:
            await asyncio.sleep(12 * 3600)
            await asyncio.to_thread(_ip_retention_once)
        except asyncio.CancelledError:
            raise
        except Exception as _e:
            log.debug(f"[RETENTION] {_e}")


async def sec_callback(update, ctx):
    """অ্যালার্টের ✅ Unban / 🗑 Ignore বাটন (শুধু অ্যাডমিন)।"""
    q = update.callback_query
    try:
        await q.answer()
    except Exception:
        pass
    uid = q.from_user.id
    try:
        if not await asyncio.to_thread(is_admin, uid):
            return
    except Exception:
        return
    d = q.data or ""
    try:
        target = int(d.rsplit("_", 1)[1])
    except Exception:
        return
    done = ""
    if d.startswith("sec_unban_"):
        try:
            with _c() as c:
                c.execute(
                    "UPDATE users SET is_banned=0, ban_reason='', is_suspicious=0 WHERE user_id=%s",
                    (target,),
                )
            try:
                _invalidate_user_cache(target)
            except Exception:
                pass
            done = "✅ Unbanned"
            try:
                await ctx.bot.send_message(
                    target,
                    "✅ *আপনার অ্যাকাউন্ট আবার চালু হয়েছে।*\n\nএখন বট ব্যবহার করতে পারবেন।",
                    parse_mode="Markdown",
                )
            except Exception:
                pass
        except Exception as _e:
            done = f"❌ ব্যর্থ: {_e}"
    else:
        try:
            with _c() as c:
                c.execute(
                    "UPDATE security_alerts SET status='ignored', handled_by=%s, handled_at=%s "
                    "WHERE user_id=%s AND status='new'",
                    (uid, now(), target),
                )
        except Exception:
            pass
        done = "🗑 Ignored"
    try:
        await q.edit_message_text(
            f"{(q.message.text or '')[:3500]}\n\n— {done} (`{target}`)",
            parse_mode="Markdown",
        )
    except Exception:
        pass


