def vrf_token(uid, ttl_hours=None):
    try:
        ttl = int(ttl_hours or get_setting("verify_ttl_hours") or 24)
    except Exception:
        ttl = 24
    try:
        return _vrf_tok().make_token(uid, ttl * 3600)
    except Exception as _e:
        log.warning(f"[VRF] token বানাতে ব্যর্থ: {_e}")
        return ""


def vrf_link(uid):
    base = _vrf_panel_base()
    tok = vrf_token(uid)
    if not base or not tok:
        return ""
    return f"{base}/v/{tok}"


def vrf_note_attempt(uid, kind="verify_check"):
    try:
        with _c() as c:
            c.execute(
                "INSERT INTO verifications (user_id, status, attempts, created_at) "
                "VALUES (%s,'pending',1,%s) ON CONFLICT (user_id) DO UPDATE SET "
                "attempts=verifications.attempts+1",
                (uid, now()),
            )
    except Exception as _e:
        log.debug(f"[VRF] attempt note ব্যর্থ uid={uid}: {_e}")


def _ip_kind(ip):
    """IP-এর ধরন — 'mobile' | 'vpn' | 'wifi' | '' (অজানা)। কোনো নেটওয়ার্ক কল নয়।

    ⚠️ মোবাইল ডেটায় (CGNAT) এক IP-তে শত শত ইউজার — সেখানে ব্লক করলে আসল
    ইউজার আটকে যাবে। তাই মোবাইল/VPN/অজানা IP-তে verify আটকায় না, শুধু
    প্যানেলে IP + ধরন দেখায়। ব্লক হয় শুধু সাধারণ (Wi-Fi/ব্রডব্যান্ড) IP-তে।
    """
    ip = (ip or "").strip()
    if not ip:
        return ""
    try:
        _p = ip.split(".")
        # CGNAT 100.64.0.0/10 — মোবাইল ক্যারিয়ারের শেয়ার্ড রেঞ্জ
        if len(_p) == 4 and _p[0] == "100" and 64 <= int(_p[1]) <= 127:
            return "mobile"
    except Exception:
        pass
    try:
        with _c() as c:
            r = c.execute("SELECT is_mobile, is_vpn FROM ip_geo_cache WHERE ip=%s", (ip,)).fetchone()
    except Exception:
        return ""
    if not r:
        return ""
    def _i(v):
        try:
            return int(v)
        except Exception:
            return -1
    _m, _v = _i(r["is_mobile"]), _i(r["is_vpn"])
    if _v == 1:
        return "vpn"
    if _m == 1:
        return "mobile"
    if _m == 0 and _v == 0:
        return "wifi"
    return ""


def _vrf_limit_reason(uid):
    """এক ফোন/এক IP নিয়ম ভাঙছে কি না — "device" / "ip" / ""."""
    try:
        cfg = _sec_cfg()
        with _c() as c:
            r = c.execute(
                "SELECT device_hash, last_ip, reg_ip FROM users WHERE user_id=%s", (uid,)
            ).fetchone()
            if not r:
                return ""
            dh = r["device_hash"] or ""
            ip = r["last_ip"] or r["reg_ip"] or ""
            if dh:
                n1 = c.execute(
                    "SELECT COUNT(DISTINCT user_id) AS n FROM devices "
                    "WHERE device_hash=%s AND user_id<>%s", (dh, uid)).fetchone()
                n2 = c.execute(
                    "SELECT COUNT(*) AS n FROM users WHERE device_hash=%s AND user_id<>%s",
                    (dh, uid)).fetchone()
                if max(int(_count(n1)), int(_count(n2))) >= max(1, int(cfg["device_limit"])):
                    return "device"
            _kind = _ip_kind(ip) if ip else ""
            if _kind == "vpn":
                # 🛡️ VPN/Proxy দিয়ে verify নয় — বন্ধ করে আবার করতে হবে
                return "vpn"
            if ip and cfg.get("ip_block") and _kind == "wifi":
                # ⚠️ শুধু অ্যাডমিন চালু করলে (sec_ip_block=on); ডিফল্টে IP কাউকে আটকায় না
                # ⚠️ মোবাইল/VPN/অজানা IP-তে ব্লক নেই — শুধু সাধারণ Wi-Fi/ব্রডব্যান্ডে
                i1 = c.execute(
                    "SELECT COUNT(DISTINCT user_id) AS n FROM user_ips "
                    "WHERE ip=%s AND user_id<>%s", (ip, uid)).fetchone()
                i2 = c.execute(
                    "SELECT COUNT(*) AS n FROM users WHERE (last_ip=%s OR reg_ip=%s) "
                    "AND user_id<>%s", (ip, ip, uid)).fetchone()
                if max(int(_count(i1)), int(_count(i2))) >= max(2, int(cfg["ip_limit"])):
                    return "ip"
    except Exception as e:
        log.debug(f"[VRF] limit reason ব্যর্থ uid={uid}: {e}")
    return ""


async def _vrf_send_blocked(bot, uid, reason, lang=None):
    """নিয়ম ভাঙলে verify প্রম্পটের বদলে স্পষ্ট বার্তা (১০ মিনিটে একবার)।"""
    if lang is None:
        lang = await asyncio.to_thread(get_lang, uid)
    _now_ts = _time.time()
    if (_now_ts - _VRF_PROMPT_TS.get(uid, 0)) < 600:
        return
    _VRF_PROMPT_TS[uid] = _now_ts
    if reason == "device":
        bn = ("🚫 *এক ফোনে একটির বেশি অ্যাকাউন্ট চলবে না*\n\n"
              "এই ফোন দিয়ে ইতিমধ্যে একটি অ্যাকাউন্ট চলছে।\n"
              "দ্বিতীয় অ্যাকাউন্ট verify করা যাবে না।\n\n"
              "ভুল মনে হলে অ্যাডমিনের সাথে যোগাযোগ করুন।")
        en = ("🚫 *Only one account per phone is allowed*\n\n"
              "An account is already active on this phone.\n"
              "A second account can not be verified.\n\n"
              "Contact the admin if you think this is a mistake.")
    elif reason == "vpn":
        bn = ("🛡️ *VPN / Proxy শনাক্ত হয়েছে*\n\n"
              "VPN বন্ধ করে মোবাইল ডেটা বা Wi-Fi দিয়ে আবার verify করুন।\n"
              "VPN চালু থাকলে verify সম্পন্ন হবে না।")
        en = ("🛡️ *VPN / Proxy detected*\n\n"
              "Turn off the VPN and verify again using mobile data or Wi-Fi.\n"
              "Verification can not complete while a VPN is active.")
    else:
        bn = ("🚫 *এই ইন্টারনেট (IP) দিয়ে আর অ্যাকাউন্ট চলবে না*\n\n"
              "একই IP-তে সর্বোচ্চ ২টি অ্যাকাউন্ট খোলা যায়।\n"
              "👉 Wi-Fi বন্ধ করে মোবাইল ডেটা দিয়ে আবার চেষ্টা করুন।")
        en = ("🚫 *No more accounts from this IP*\n\n"
              "Up to 2 accounts per IP are allowed.\n"
              "👉 Turn off Wi-Fi and try again with mobile data.")
    try:
        await bot.send_message(uid, bn if lang != "en" else en, parse_mode="Markdown")
    except Exception as e:
        log.debug(f"[VRF] block msg ব্যর্থ uid={uid}: {e}")


async def _vrf_gate_msg(bot, uid):
    """True = এগোতে পারবে। False = verify prompt পাঠানো হয়েছে।"""
    # ADMIN-সহ সবাই verify প্রম্পট পাবে (আগের verified হলেও)
    if not verify_enabled():
        return True
    if await asyncio.to_thread(vrf_pass_on, uid):
        return True
    lang = await asyncio.to_thread(get_lang, uid)
    _blk = await asyncio.to_thread(_vrf_limit_reason, uid)
    if _blk:
        # ১ ফোন = ১ অ্যাকাউন্ট / IP সীমা — verify লিংক না দিয়ে কারণ জানাও
        await _vrf_send_blocked(bot, uid, _blk, lang)
        return False
    await _vrf_send_prompt(bot, uid, lang)
    return False


_VRF_PROMPT_TS = {}


async def _vrf_send_prompt(bot, uid, lang=None, force=False):
    if lang is None:
        lang = await asyncio.to_thread(get_lang, uid)
    # একই ইউজারকে ২০ সেকেন্ডের মধ্যে আবার একই প্রম্পট নয় (বারবার চাপলে স্প্যাম হবে না)
    _now_ts = _time.time()
    if not force and (_now_ts - _VRF_PROMPT_TS.get(uid, 0)) < 20:
        return
    _VRF_PROMPT_TS[uid] = _now_ts
    link = await asyncio.to_thread(vrf_link, uid)
    if not link:
        log.error(f"[VRF] PANEL_BASE_URL সেট নেই — uid={uid} verify লিংক বানানো যাচ্ছে না")
        try:
            await bot.send_message(
                uid,
                ("⚠️ *Verification লিংক এখন কাজ করছে না।*\n\nঅ্যাডমিনকে জানান — "
                 "তিনি ঠিক করলে আবার /start দিন।" if lang != "en" else
                 "⚠️ *The verification link is not available right now.*\n\n"
                 "Please tell the admin, then send /start again."),
                parse_mode="Markdown")
        except Exception:
            pass
        return False
    # ⚠️ ইউজারের চাহিদা: আগের মতোই *একটাই লিংক*, একবার।
    #    লিংকটা মেসেজের ভেতরে ক্লিকযোগ্য লেখা হিসেবে যায় (ফুল URL দেখা যায় না),
    #    নিচে শুধু "✅ I verified" বাটন থাকে — তাই দুইবার লিংক দেখায় না।
    rows = [[InlineKeyboardButton("✅ I verified", callback_data="vrf_check")]]
    txt = VERIFY_TEXT_EN if lang == "en" else VERIFY_TEXT_BN
    _link_line = ("\n\n[🔗 Verify করুন](%s)" % link) if lang != "en" else ("\n\n[🔗 Tap to Verify](%s)" % link)
    try:
        await bot.send_message(uid, txt + _link_line, parse_mode="Markdown",
                               reply_markup=InlineKeyboardMarkup(rows),
                               disable_web_page_preview=True)
        return True
    except Exception as _e:
        log.warning(f"[VRF] prompt পাঠাতে ব্যর্থ uid={uid}: {_e}")
        return False


async def _vrf_handle_check(update, ctx, q, uid):
    """'I Verified' বাটন — DB থেকে স্ট্যাটাস যাচাই করে রেজিস্ট্রেশন এগিয়ে নেয়।"""
    lang = await asyncio.to_thread(get_lang, uid)
    # ── একবারই: আগেই pass হয়ে গেলে আর কিছু হবে না ──
    if await asyncio.to_thread(vrf_pass_on, uid):
        try:
            await q.answer("✅ Verified — মেনু খুলছে…")
        except Exception:
            pass
        try:
            await q.message.edit_reply_markup(reply_markup=None)
        except Exception:
            pass
        # ওয়েবে verify করা ইউজার এখানে চাপলে মেনু যেন আসে (নীরব না থাকে)
        await _vrf_after_web_verify(uid, ctx.bot)
        ctx.user_data.pop("state", None)
        return
    ok = await asyncio.to_thread(vrf_is_verified, uid)
    if not ok:
        await asyncio.to_thread(vrf_note_attempt, uid)
        try:
            await q.answer("❌ এখনো verified হয়নি!" if lang == "bn" else "❌ Not verified yet!",
                           show_alert=True)
        except Exception:
            pass
        await _vrf_send_prompt(ctx.bot, uid, lang)
        return
    try:
        await q.message.edit_reply_markup(reply_markup=None)
    except Exception:
        pass
    await asyncio.to_thread(vrf_mark_pass, uid)
    try:
        await sec_after_verify(ctx.bot, uid, lang)
    except Exception as _sec_e:
        log.debug(f"[SEC2] post-verify চেক ব্যর্থ: {_sec_e}")
    await ctx.bot.send_message(
        uid,
        "✅ *Verification successful!*\n\nএখন আপনি Task করতে পারবেন।" if lang == "bn"
        else "✅ *Verification successful!*\n\nYou now have access to tasks.",
        parse_mode="Markdown",
    )
    ctx.user_data.pop("state", None)
    try:
        _missing = await check_ch(update, ctx)
        if _missing:
            await join_prompt(update, uid)
            return
    except Exception as _ce:
        log.debug(f"[VRF] channel check ব্যর্থ uid={uid}: {_ce}")
    await _send_welcome(update, ctx, uid)


_VRF_WELCOME_TS = {}
_VRF_SIG_READY = False


def _vrf_sig_ensure():
    """প্যানেল → বট সিগন্যাল টেবিল (একবারই তৈরি হয়)।"""
    global _VRF_SIG_READY
    if _VRF_SIG_READY:
        return
    try:
        with _c() as c:
            c.execute("CREATE TABLE IF NOT EXISTS vrf_signals (id BIGSERIAL PRIMARY KEY, "
                      "user_id BIGINT, created_at TEXT DEFAULT '', processed INTEGER DEFAULT 0)")
        _VRF_SIG_READY = True
    except Exception as e:
        log.debug(f"[VRF] vrf_signals তৈরি ব্যর্থ: {e}")


def _vrf_pending_signals():
    """প্যানেল থেকে আসা 'verify শেষ' সিগন্যাল (processed=0) → uid তালিকা।"""
    _vrf_sig_ensure()
    out = []
    try:
        with _c() as c:
            rows = c.execute("SELECT id, user_id FROM vrf_signals "
                             "WHERE processed=0 ORDER BY id LIMIT 20").fetchall()
            for r in rows:
                try:
                    c.execute("UPDATE vrf_signals SET processed=1 WHERE id=%s", (r["id"],))
                except Exception:
                    pass
                out.append(int(r["user_id"] or 0))
    except Exception as e:
        log.debug(f"[VRF] signal পড়া ব্যর্থ: {e}")
    return [u for u in out if u > 0]


def _vrf_mark_signals_done(uid):
    try:
        with _c() as c:
            c.execute("UPDATE vrf_signals SET processed=1 WHERE user_id=%s AND processed=0", (uid,))
    except Exception:
        pass


async def _vrf_after_web_verify(uid, bot=None):
    """ওয়েব প্যানেলে verification সফল হওয়ার সাথে সাথে বট নিজেই welcome+মেনু পাঠায়।"""
    try:
        uid = int(uid)
    except Exception:
        return
    if uid <= 0:
        return
    _VRF_SILENT_MEMO.pop(uid, None)   # প্যানেলে verify শেষ → সাথে সাথে gate খুলে দাও
    _t = _time.time()
    if _t - _VRF_WELCOME_TS.get(uid, 0) < 60:
        return          # এইমাত্র পাঠানো হয়েছে — ডাবল মেসেজ নয়
    _VRF_WELCOME_TS[uid] = _t
    try:
        if not await asyncio.to_thread(vrf_pass_on, uid):
            await asyncio.to_thread(vrf_mark_pass, uid)
        bot = bot or (_app.bot if _app else None)
        if bot is None:
            return
        try:
            lang = await asyncio.to_thread(get_lang, uid)
        except Exception:
            lang = "bn"
        try:
            kb = await asyncio.to_thread(main_kb, uid)
        except Exception:
            kb = None
        _uk = "welcome_msg_bn" if lang == "bn" else "welcome_msg_en"
        # ── চ্যানেল জয়েন বাকি থাকলে welcome নয়, জয়েন প্রম্পট ──
        try:
            _chans = await asyncio.to_thread(get_req_channels)
        except Exception:
            _chans = []
        if _chans:
            _miss = False
            for _ch in _chans:
                try:
                    _mbr = await bot.get_chat_member(_ch["ch_id"], uid)
                    if _mbr.status in [ChatMemberStatus.LEFT, ChatMemberStatus.BANNED]:
                        _miss = True
                        break
                except Exception:
                    continue        # bot-side সমস্যা → ইউজারকে আটকাই না
            if _miss:
                if await _send_join_prompt_bot(bot, uid, lang):
                    return
        try:
            custom_w = await asyncio.to_thread(get_setting, _uk)
        except Exception:
            custom_w = None
        if not await _bot_accessible(uid):
            try:
                await bot.send_message(uid, T(uid, "bot_off"), parse_mode="Markdown")
            except Exception:
                pass
            return
        try:
            welcome_text = custom_w if custom_w else T(uid, "welcome")
        except Exception:
            welcome_text = "🎉 স্বাগতম!"
        try:
            await bot.send_message(
                uid,
                "✅ *Verification successful!*\n\nএখন আপনি Task করতে পারবেন।" if lang == "bn"
                else "✅ *Verification successful!*\n\nYou now have access to tasks.",
                parse_mode="Markdown",
            )
        except Exception as _m1:
            log.debug(f"[VRF] success মেসেজ ব্যর্থ uid={uid}: {_m1}")
        await bot.send_message(uid, welcome_text, parse_mode="Markdown", reply_markup=kb)
        await asyncio.to_thread(_vrf_mark_signals_done, uid)
        log.info(f"[VRF] web verify → welcome পাঠানো হলো uid={uid}")
    except Exception as e:
        _VRF_WELCOME_TS.pop(uid, None)   # ব্যর্থ হলে আবার চেষ্টা করার সুযোগ
        log.warning(f"[VRF] auto-welcome ব্যর্থ uid={uid}: {e}")



def init_db():
    with _c() as c:
        # soft মোড: এক statement fail করলেও বাকি টেবিল/কলাম তৈরি চলবে
        try:
            c._soft = True
        except Exception:
            pass
        # ── Core tables ──────────────────────────────────────────
