def _reset_onboarding_sync(keep_admin=True):
    """সব ইউজারকে আবার শুরু থেকে — verification + onboarding রিসেট (একবারই)।
    ⚠️ balance, points, রেফারেল, task/withdraw ইতিহাস — কোনো ডেটা/টাকা মোছে না।"""
    n = 0
    with _c() as c:
        if keep_admin:
            cur = c.execute(
                "UPDATE users SET vrf_pass=0, verified=0 "
                "WHERE user_id<>%s AND COALESCE(vrf_pass,0)<>0", (ADMIN_ID,))
        else:
            cur = c.execute(
                "UPDATE users SET vrf_pass=0, verified=0 WHERE COALESCE(vrf_pass,0)<>0")
        try:
            n = int(cur.rowcount or 0)
        except Exception:
            n = 0
        try:
            c.execute("DELETE FROM vrf_signals")
        except Exception:
            pass
    for _d in (_user_cache, _VRF_PROMPT_TS, _VRF_WELCOME_TS, _VRF_SILENT_MEMO):
        try:
            _d.clear()
        except Exception:
            pass
    return n


def _restart_user_flow(uid):
    """একজন ইউজারকে আবার শুরু থেকে — শুধু verification/onboarding state রিসেট।
    ⚠️ balance, points, referred_by/রেফারেল, task ও withdraw ইতিহাস, ban, ডিভাইস/IP —
    কোনো ডেটা ছোঁয়া হয় না। এর পর ওই ইউজার /start চাপলে নতুন ইউজারের মতো ফ্লো পাবে।"""
    try:
        uid = int(uid)
    except Exception:
        return False
    if uid <= 0:
        return False
    try:
        try:
            with _c() as c:
                c.execute("UPDATE users SET vrf_pass=0, verified=0, verified_at='', "
                          "vrf_notice_build='', vrf_force=1 WHERE user_id=%s", (uid,))
        except Exception as e:
            if not _col_missing(e):
                raise
            # পুরোনো DB-তে vrf_notice_build কলাম নেই → বাকিটা অন্তত রিসেট হোক
            log.warning(f"[RESTART] uid={uid} vrf_notice_build ছাড়া রিসেট: {e}")
            with _c() as c:
                c.execute("UPDATE users SET vrf_pass=0, verified=0, verified_at='' "
                          "WHERE user_id=%s", (uid,))
    except Exception as e:
        log.warning(f"[RESTART] uid={uid} রিসেট ব্যর্থ: {e}")
        return False
    # ── ডিভাইস / IP / ভেরিফিকেশন রেকর্ড মুছে দাও ─────────────────────
    # আগের ফোন-হ্যাশ ও IP রয়ে গেলে নতুন verify আটকে যেত; restart মানে
    # ওই ইউজারের জন্য সব পুরোনো verification-চিহ্ন বাদ, একেবারে নতুন করে।
    _clr = {}
    try:
        with _c() as c:
            for _t in ("verifications", "devices", "user_ips", "ip_history"):
                try:
                    _r = c.execute(f"DELETE FROM {_t} WHERE user_id=%s", (uid,))
                    _clr[_t] = _r.rowcount or 0
                except Exception as _e:
                    log.debug(f"[RESTART] {_t} clear skip uid={uid}: {_e}")
    except Exception as _e:
        log.warning(f"[RESTART] device/ip clear ব্যর্থ uid={uid}: {_e}")
    for _d in (_user_cache, _lang_cache, _VRF_PROMPT_TS, _VRF_WELCOME_TS, _VRF_SILENT_MEMO):
        try:
            _d.pop(uid, None)
        except Exception:
            pass
    try:
        _vrf_mark_signals_done(uid)   # পুরোনো 'verify শেষ' সিগন্যাল আগে মেনু পাঠাবে না
    except Exception:
        pass
    log.info(f"[RESTART] uid={uid} শুরু থেকে চালু (টাকা/পয়েন্ট/রেফার অক্ষত, "
             f"মুছেছে: {_clr})")
    return _clr if _clr else True

