def count_approved_tasks_for_user(uid):
    """User-এর মোট completed task count।
    - gmails status='approved' → regular task + category task (category submission-ও gmails-এ যায়)
    - tg_task_completions → TG task (auto-approved, gmails-এ যায় না)
    category_task_completions গোনা হয় না — ওগুলো gmails-এ already আছে।
    """
    with _c() as c:
        g  = _count(c.execute("SELECT COUNT(*) FROM gmails WHERE user_id=%s AND status='approved'", (uid,)).fetchone())
        tg = _count(c.execute("SELECT COUNT(*) FROM tg_task_completions WHERE user_id=%s", (uid,)).fetchone())
    total = g + tg
    # FB/IG — আলাদা টেবিল; প্যানেল থেকে approve হওয়া জমাও গোনা হয়
    # (আগে বাদ পড়ত, তাই Referral Event bonus কখনো ট্রিগার হতো না)
    for _tbl in ("fb_submissions", "ig_submissions"):
        try:
            with _c() as c:
                total += _count(c.execute(
                    f"SELECT COUNT(*) FROM {_tbl} WHERE user_id=%s AND status='approved'",
                    (uid,)).fetchone())
        except Exception as _e:
            log.debug(f"[count_tasks] {_tbl} বাদ: {_e}")
    # ডিলিট হয়ে যাওয়া লগের archived approved কাউন্টও যোগ (হিসাব অটুট)
    try:
        with _c() as c:
            total += _count(c.execute(
                "SELECT COALESCE(SUM(n_approved),0) FROM task_archive_counts WHERE user_id=%s",
                (uid,)).fetchone())
    except Exception as _e:
        log.debug(f"[count_tasks] archive বাদ: {_e}")
    return total

def give_ref_event_bonus(event_id, referrer_id, referred_id, bonus_amount):
    """Referral Event বোনাস — ON CONFLICT দিয়ে একবারই; টাকা add_bal দিয়ে যোগ।"""
    try:
        with _c() as c:
            result = c.execute(
                "INSERT INTO referral_event_rewards (event_id,referrer_id,referred_id,rewarded_at) "
                "VALUES (%s,%s,%s,%s) ON CONFLICT DO NOTHING",
                (event_id, referrer_id, referred_id, now())
            )
            inserted = result.rowcount > 0
    except Exception as _e:
        log.warning(f"[REF_EVENT] give_ref_event_bonus failed: {_e}")
        return False
    if not inserted:
        return False
    if not add_bal(referrer_id, bonus_amount):
        # ইউজার DB-তে নেই — reward row ফিরিয়ে দাও যাতে পরে আবার চেষ্টা হয়
        try:
            with _c() as c:
                c.execute(
                    "DELETE FROM referral_event_rewards WHERE event_id=%s "
                    "AND referrer_id=%s AND referred_id=%s",
                    (event_id, referrer_id, referred_id))
        except Exception:
            pass
        log.warning(f"[REF_EVENT] referrer={referrer_id} DB তে নেই — বোনাস দেওয়া যায়নি")
        return False
    return True


