def categ_task_user_done(task_id, user_id):
    """Returns True if user has reached their per_user_limit for this category task."""
    task = get_category_task(task_id)
    per_user_limit = _rget(task, 'per_user_limit', 1) if task else 1
    if per_user_limit == 0: return False  # 0 = unlimited
    task_name = task['name'] if task else ''
    count = get_user_categ_task_submit_count(task_name, user_id)
    return count >= per_user_limit

def categ_task_slots_left(tid):
    t = get_category_task(tid)
    if not t: return 0
    if t["max_completions"] == 0: return -1
    return max(0, t["max_completions"] - t["completed_count"])

def categ_task_mark_done(task_id, user_id):
    """Returns True if this call actually marked done (first time), False if already done
    অথবা সব স্লট পূর্ণ (slot claim atomic — completed_count কখনো max ছাড়বে না)।"""
    with _c() as c:
        # ON CONFLICT DO NOTHING — psycopg2 exception তোলে না, শুধু rowcount=0 হয়
        ins = c.execute("INSERT INTO category_task_completions (task_id,user_id,done_at) VALUES (%s,%s,%s) ON CONFLICT DO NOTHING", (task_id, user_id, now()))
        if ins.rowcount == 0:
            return False  # ইতিমধ্যে done — completed_count double-count হবে না
        # Slot claim — একসাথে অনেকে submit করলেও max_completions ছাড়বে না
        _claim = c.execute(
            "UPDATE category_tasks SET completed_count=completed_count+1 "
            "WHERE id=%s AND (max_completions=0 OR completed_count<max_completions)",
            (task_id,)
        )
        if _claim.rowcount == 0:
            # স্লট শেষ — এই completion আনডো করে caller কে False দাও
            c.execute("DELETE FROM category_task_completions WHERE task_id=%s AND user_id=%s", (task_id, user_id))
            return False
        t = c.execute("SELECT max_completions,completed_count FROM category_tasks WHERE id=%s", (task_id,)).fetchone()
        if t and t["max_completions"] > 0 and t["completed_count"] >= t["max_completions"]:
            c.execute("UPDATE category_tasks SET is_active=0 WHERE id=%s", (task_id,))
    return True  # Bug #6 fix: এই call-ই প্রথমবার mark করেছে — True return করো

# ── Stats helper ──────────────────────────────────────────────────
_stats_cache_val = None
_stats_cache_ts  = 0.0
_STATS_CACHE_TTL = 45.0  # ৪৫ সেকেন্ড — বড় ডেটাবেসে বারবার COUNT না করে দ্রুত খোলে

def get_stats():
    global _stats_cache_val, _stats_cache_ts
    now_ts = _time.monotonic()
    if _stats_cache_val is not None and (now_ts - _stats_cache_ts) < _STATS_CACHE_TTL:
        return _stats_cache_val
    ag = None
    aw = None
    pg = None
    pw = None
    tot_bal = None
    total = None
    with _c() as c:
        total   = _count(c.execute("SELECT COUNT(*) FROM users").fetchone())
        tot_bal = _count(c.execute("SELECT COALESCE(SUM(balance),0) FROM users").fetchone())
        pg = _count(c.execute("SELECT COUNT(*) FROM gmails WHERE status='pending'").fetchone())
        pw = _count(c.execute("SELECT COUNT(*) FROM withdrawals WHERE status='pending'").fetchone())
        ag = _count(c.execute("SELECT COUNT(*) FROM gmails WHERE status='approved'").fetchone())
        aw = _count(c.execute("SELECT COUNT(*) FROM withdrawals WHERE status='approved'").fetchone())
    _stats_cache_val = (total, tot_bal, pg, pw, ag, aw)
    _stats_cache_ts  = now_ts
    return _stats_cache_val

def display_name(u_row):
    if u_row and u_row["username"]: return f"@{u_row['username']}"
    if u_row and u_row["full_name"]: return u_row["full_name"]
    return "Unknown"

def _build_user_profile(uid, u=None):
    if u is None:
        u = get_user(uid)
    if not u:
        return f"❌ `{uid}` ID দিয়ে কোনো user পাওয়া যায়নি।", None
    with _c() as c:
        ref_count = _count(c.execute("SELECT COUNT(*) FROM users WHERE referred_by=%s",           (uid,)).fetchone())
        sub_count = _count(c.execute("SELECT COUNT(*) FROM gmails WHERE user_id=%s",               (uid,)).fetchone())
        sub_app   = _count(c.execute("SELECT COUNT(*) FROM gmails WHERE user_id=%s AND status='approved'", (uid,)).fetchone())
        wd_count  = _count(c.execute("SELECT COUNT(*) FROM withdrawals WHERE user_id=%s",          (uid,)).fetchone())
        wd_app    = _count(c.execute("SELECT COUNT(*) FROM withdrawals WHERE user_id=%s AND status='approved'", (uid,)).fetchone())
        tg_done   = _count(c.execute("SELECT COUNT(*) FROM tg_task_completions WHERE user_id=%s",  (uid,)).fetchone())
        cat_done  = _count(c.execute("SELECT COUNT(*) FROM category_task_completions WHERE user_id=%s", (uid,)).fetchone())
        # FB / IG সিট হিসাব (approved / rejected / pending)
        _fb_st = {"approved": 0, "rejected": 0, "pending": 0, "total": 0}
        _ig_st = {"approved": 0, "rejected": 0, "pending": 0, "total": 0}
        try:
            c.execute("CREATE TABLE IF NOT EXISTS seat_archive ("
                      "user_id BIGINT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, "
                      "n BIGINT NOT NULL DEFAULT 0, updated_at TEXT DEFAULT '', "
                      "UNIQUE(user_id, kind, status))")
        except Exception:
            pass
        for _tbl, _dst in (("fb_submissions", _fb_st), ("ig_submissions", _ig_st)):
            try:
                for _r in c.execute(
                        "SELECT COALESCE(status,'pending') AS st, COUNT(*) AS n "
                        f"FROM {_tbl} WHERE user_id=%s GROUP BY COALESCE(status,'pending')",
                        (uid,)).fetchall():
                    _k = str(_r["st"])
                    if _k in _dst:
                        _dst[_k] = int(_r["n"] or 0)
                    _dst["total"] += int(_r["n"] or 0)
            except Exception:
                pass
        # আগে ডিলিট হওয়া সারির হিসাব (user_hist) — প্রোফাইলে যোগ হবে
        _hist = {}
        try:
            c.execute("CREATE TABLE IF NOT EXISTS user_hist ("
                      "user_id BIGINT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, "
                      "n BIGINT NOT NULL DEFAULT 0, updated_at TEXT DEFAULT '', "
                      "UNIQUE(user_id, kind, status))")
        except Exception:
            pass
        try:
            for _r in c.execute(
                    "SELECT kind, status, n FROM user_hist WHERE user_id=%s",
                    (uid,)).fetchall():
                _hist[(str(_r["kind"]), str(_r["status"]))] = int(_r["n"] or 0)
        except Exception:
            _hist = {}
        for _kind, _dst in (("fb", _fb_st), ("ig", _ig_st)):
            for _k in ("approved", "rejected", "pending"):
                _n = _hist.get((_kind, _k), 0)
                if _n:
                    _dst[_k] += _n
                    _dst["total"] += _n
        # উইথড্র / টাস্কের ডিলিট-হিসাবও আগের গণনার সাথে যোগ
        _wd_arch = {k: _hist.get(("wd", k), 0) for k in ("approved", "pending", "rejected")}
        _tk_arch = {k: _hist.get(("task", k), 0) for k in ("approved", "pending", "rejected")}
    name_str  = _md_esc(f"@{u['username']}" if u["username"] else (u["full_name"] or "Unknown"))
    ban_icon  = "🚫 Banned" if u["is_banned"] else "✅ Active"
    ref_by    = u["referred_by"]
    if ref_by:
        ref_u = get_user(ref_by)
        rn = _md_esc(f"@{ref_u['username']}" if ref_u and ref_u["username"] else
              (ref_u["full_name"] if ref_u and ref_u["full_name"] else str(ref_by)))
        ref_by_str = f"`{ref_by}` ({rn})"
    else:
        ref_by_str = "_কেউ নেই_"
    # Country display
    try:
        _ctry_raw = (u["country"] or "").upper().strip()
    except Exception:
        _ctry_raw = ""
    if _ctry_raw and _ctry_raw in COUNTRY_MAP:
        _ctry_flag, _ctry_name = COUNTRY_MAP[_ctry_raw]
        country_str = f"{_ctry_flag} {_ctry_name} (`{_ctry_raw}`)"
    elif _ctry_raw:
        country_str = f"`{_ctry_raw}` _(অজানা)_"
    else:
        country_str = "_সেট হয়নি_"
    text = (
        f"👤 *User Profile*\n\n"
        f"🆔 *ID:* `{uid}`\n"
        f"📛 *নাম:* {name_str}\n"
        f"📱 *Full Name:* {_md_esc(u['full_name']) if u['full_name'] else '_নেই_'}\n"
        f"📅 *Join Date:* `{u['joined_at']}`\n"
        f"🌐 *Language:* `{u['lang'] or 'bn'}`\n"
        f"🌍 *দেশ:* {country_str}\n"
        f"💰 *Balance:* `{round(u['balance'],4)}$ USDT`\n"
        f"🔰 *Status:* {ban_icon}\n\n"
        f"👥 *Referred By:* {ref_by_str}\n"
        f"🔗 *মোট Referrals:* `{ref_count}` জন\n\n"
        f"📋 *Task Submissions:* `{sub_count + _tk_arch['approved'] + _tk_arch['pending'] + _tk_arch['rejected']}` টি "
        f"✅`{sub_app + _tk_arch['approved']}` approved\n"
        f"💸 *Withdrawals:* `{wd_count + _wd_arch['approved'] + _wd_arch['pending'] + _wd_arch['rejected']}` টি "
        f"✅`{wd_app + _wd_arch['approved']}` approved\n"
        f"📡 *TG Tasks Done:* `{tg_done}` টি\n"
        f"📁 *Category Tasks Done:* `{cat_done}` টি\n"
        f"📘 *FB সিট:* `{_fb_st['total']}` — ✅`{_fb_st['approved']}` "
        f"❌`{_fb_st['rejected']}` ⏳`{_fb_st['pending']}`\n"
        f"📸 *IG সিট:* `{_ig_st['total']}` — ✅`{_ig_st['approved']}` "
        f"❌`{_ig_st['rejected']}` ⏳`{_ig_st['pending']}`"
    )
    ban_btn = (InlineKeyboardButton("✅ Unban", callback_data=f"adm_uunban_{uid}")
               if u["is_banned"] else InlineKeyboardButton("🚫 Ban", callback_data=f"adm_uban_{uid}"))
    kb = InlineKeyboardMarkup([
        [ban_btn,
         InlineKeyboardButton("💬 Message", callback_data=f"adm_umsg_{uid}")],
        [InlineKeyboardButton("➕ Balance যোগ", callback_data=f"adm_uaddbal_{uid}"),
         InlineKeyboardButton("➖ Balance কাটো", callback_data=f"adm_udedbal_{uid}")],
        [InlineKeyboardButton("🌍 দেশ পরিবর্তন করুন", callback_data=f"adm_uchcountry_{uid}")],
        [InlineKeyboardButton(f"👥 Referrals ({ref_count}জন)", callback_data=f"adm_urefs_{uid}"),
         InlineKeyboardButton(f"📧 Submissions ({sub_count})", callback_data=f"adm_usubs_{uid}")],
        [InlineKeyboardButton(f"💸 Withdrawals ({wd_count})", callback_data=f"adm_uwds_{uid}")],
    ])
    return text, kb

def mask_addr_short(addr):
    if len(addr) <= 12: return addr[:4] + "*****" + addr[-4:]
    return addr[:6] + "*****" + addr[-6:]

# ──────────────────────────── 🛒 SHOP / দোকান ────────────────────────────
# ইউজার ব্যালেন্স দিয়ে কিনবে। auto → txt/লাইন স্টক থেকে অটো ডেলিভারি,
# manual → অর্ডার pending, অ্যাডমিন নিজে কনটেন্ট পাঠাবে (অথবা রিফান্ড)।

def _shop_cur():
    try:
        v = (get_setting("shop_currency") or "").strip()
    except Exception:
        v = ""
    return v or "$"


def _seq_no(kind, oid):
    """ইউজারকে দেখানোর ছোট নম্বর — প্রথম অর্ডার/ডিপোজিট = #1।"""
    _t = "shop_orders" if kind == "shop" else "deposits"
    try:
        with _c() as c:
            r = c.execute(f"SELECT COUNT(*) AS n FROM {_t} WHERE id <= %s",
                          (int(oid),)).fetchone()
        n = int(r["n"] or 0) if r else 0
        return n or int(oid)
    except Exception:
        return int(oid)


def shop_no(oid):
    return _seq_no("shop", oid)


def dep_no(oid):
    return _seq_no("dep", oid)


def _shop_money(v):
    """দাম/ব্যালেন্স — ছোট অঙ্কও পুরো দেখাবে (0.0001 → `0.0001`, 0 নয়)।"""
    try:
        n = float(v or 0)
    except Exception:
        n = 0.0
    try:
        s = _amt(n)
    except Exception:
        s = f"{n:.8f}".rstrip("0").rstrip(".")
    return f"{s or '0'} {_shop_cur()}"


def _shop_ddl():
    with _c() as c:
        for _q in (
            """CREATE TABLE IF NOT EXISTS shop_categories (
                id         BIGSERIAL PRIMARY KEY,
                name       TEXT DEFAULT '',
                emoji      TEXT DEFAULT '🛍',
                sort_order INTEGER DEFAULT 0,
                is_active  INTEGER DEFAULT 1,
                created_at TEXT DEFAULT ''
            )""",
            """CREATE TABLE IF NOT EXISTS shop_products (
                id           BIGSERIAL PRIMARY KEY,
                category_id  BIGINT DEFAULT 0,
                name         TEXT DEFAULT '',
                description  TEXT DEFAULT '',
                price        REAL DEFAULT 0,
                deliver_type TEXT DEFAULT 'auto',
                ref_pct      REAL DEFAULT -1,
                fields       TEXT DEFAULT '',
                is_active    INTEGER DEFAULT 1,
                sort_order   INTEGER DEFAULT 0,
                created_at   TEXT DEFAULT ''
            )""",
            """CREATE TABLE IF NOT EXISTS shop_stock (
                id         BIGSERIAL PRIMARY KEY,
                product_id BIGINT DEFAULT 0,
                content    TEXT DEFAULT '',
                added_at   TEXT DEFAULT '',
                sold       INTEGER DEFAULT 0,
                sold_to    BIGINT DEFAULT 0,
                sold_at    TEXT DEFAULT ''
            )""",
            """CREATE TABLE IF NOT EXISTS shop_orders (
                id           BIGSERIAL PRIMARY KEY,
                user_id      BIGINT DEFAULT 0,
                product_id   BIGINT DEFAULT 0,
                product_name TEXT DEFAULT '',
                price        REAL DEFAULT 0,
                status       TEXT DEFAULT 'delivered',
                content      TEXT DEFAULT '',
                created_at   TEXT DEFAULT '',
                delivered_at TEXT DEFAULT ''
            )""",
            "CREATE INDEX IF NOT EXISTS shop_stock_unsold ON shop_stock (product_id, sold)",
        ):
            try:
                c.execute(_q)
            except Exception as _she:
                log.warning(f"[SHOP] DDL স্কিপ: {str(_she)[:90]}")
        for _mig in (
            "ALTER TABLE shop_stock ADD COLUMN IF NOT EXISTS added_at TEXT DEFAULT ''",
            "ALTER TABLE shop_stock ADD COLUMN IF NOT EXISTS sold_to BIGINT DEFAULT 0",
            "ALTER TABLE shop_stock ADD COLUMN IF NOT EXISTS sold_at TEXT DEFAULT ''",
            "ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS delivered_at TEXT DEFAULT ''",
            "ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS deliver_type TEXT DEFAULT 'auto'",
            "ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS ref_pct REAL DEFAULT -1",
            "ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS fields TEXT DEFAULT ''",
            "ALTER TABLE shop_categories ADD COLUMN IF NOT EXISTS plan_kind TEXT DEFAULT ''",
            "ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS plan_id BIGINT DEFAULT 0",
        ):
            try:
                c.execute(_mig)
            except Exception:
                pass
        for _q in ():
            try:
                c.execute(_q)
            except Exception:
                pass
        # ── প্রথমবার চালু হলে ডিফল্ট ক্যাটাগরি (পরে এডিট/ডিলিট করা যাবে) ──
        try:
            _seed = c.execute("SELECT value FROM settings WHERE key=%s",
                              ("shop_seeded",)).fetchone()
            if not _seed or str(_seed["value"] or "") != "1":
                _n = c.execute("SELECT COUNT(*) AS n FROM shop_categories").fetchone()
                if int((_n or {})["n"] or 0) == 0:
                    _defs = (("📧", "Mail"), ("🌐", "VPN"), ("🔌", "Proxy-IP"),
                             ("📨", "Other Domain Mail"), ("🔑", "Recovery Added Mail"),
                             ("🤖", "Meta Ai"))
                    for _i, (_em, _nm) in enumerate(_defs, start=1):
                        c.execute(
                            "INSERT INTO shop_categories (name, emoji, sort_order, is_active, created_at) "
                            "VALUES (%s,%s,%s,1,%s)", (_nm, _em, _i, now()))
                c.execute("INSERT INTO settings (key,value) VALUES (%s,%s) "
                          "ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value",
                          ("shop_seeded", "1"))
                log.info("[SHOP] ডিফল্ট ক্যাটাগরি সিড হয়েছে")
        except Exception as _sed:
            log.debug(f"[SHOP] seed স্কিপ: {_sed}")


_SHOP_PLAN_DDL = [False]


def _shop_plan_ddl():
    if _SHOP_PLAN_DDL[0]:
        return
    try:
        with _c() as c:
            c.execute("""CREATE TABLE IF NOT EXISTS shop_plans (
                id          BIGSERIAL PRIMARY KEY,
                category_id BIGINT NOT NULL,
                label       TEXT DEFAULT '',
                kind        TEXT DEFAULT 'days',
                value       REAL DEFAULT 0,
                sort_order  INTEGER DEFAULT 0,
                is_active   INTEGER DEFAULT 1,
                created_at  TEXT DEFAULT ''
            )""")
    except Exception as e:
        log.debug(f"[SHOP-PLAN] table: {str(e)[:80]}")
    try:
        with _c() as c:
            c.execute("ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS plan_id BIGINT DEFAULT 0")
            try:
                c.execute("ALTER TABLE shop_categories ADD COLUMN IF NOT EXISTS plan_kind TEXT DEFAULT ''")
            except Exception:
                pass
    except Exception:
        try:
            with _c() as c:
                c.execute("ALTER TABLE shop_products ADD COLUMN plan_id BIGINT DEFAULT 0")
        except Exception:
            pass
    try:
        with _c() as c:
            c.execute("SELECT plan_id FROM shop_products LIMIT 1").fetchone()
        _SHOP_PLAN_DDL[0] = True
    except Exception:
        log.debug("[SHOP-PLAN] plan_id এখনো নেই — পরে আবার")


def shop_plans(cid=None, only_active=True):
    _shop_plan_ddl()
    sql = "SELECT * FROM shop_plans WHERE 1=1"
    args = []
    if only_active:
        sql += " AND COALESCE(is_active,1)=1"
    if cid is not None:
        sql += " AND category_id=%s"; args.append(int(cid))
    sql += " ORDER BY sort_order, id"
    try:
        with _c() as c:
            return c.execute(sql, tuple(args)).fetchall()
    except Exception:
        return []


def shop_plan(pid):
    _shop_plan_ddl()
    try:
        with _c() as c:
            return c.execute("SELECT * FROM shop_plans WHERE id=%s", (int(pid),)).fetchone()
    except Exception:
        return None


def shop_plan_add(cid, label, kind="days", value=0):
    _shop_plan_ddl()
    kind = "mb" if str(kind).lower() in ("mb", "gb", "mb/gb", "data") else "days"
    try:
        val = float(value or 0)
    except Exception:
        val = 0.0
    with _c() as c:
        c.execute("INSERT INTO shop_plans (category_id,label,kind,value,sort_order,is_active,created_at)"
                  " VALUES (%s,%s,%s,%s,%s,1,%s)",
                  (int(cid), (label or "")[:60], kind, val,
                   int(c.execute("SELECT COALESCE(MAX(sort_order),0)+1 AS n FROM shop_plans "
                                 "WHERE category_id=%s", (int(cid),)).fetchone()["n"] or 1), now()))


def shop_plan_del(pid):
    _shop_plan_ddl()
    with _c() as c:
        c.execute("UPDATE shop_products SET plan_id=0 WHERE plan_id=%s", (int(pid),))
        c.execute("DELETE FROM shop_plans WHERE id=%s", (int(pid),))


def shop_plan_label(pl, cat_kind=""):
    """প্ল্যানের বাটন-লেবেল: নিজের নাম → নাহলে ক্যাটাগরির ধরন অনুযায়ী '৩ দিন' / '৫ GB'।

    cat_kind দিলে ক্যাটাগরির ধরনই ধরা হয় (পুরোনো ভুল kind-এর প্যাকও ঠিক দেখায়)।
    """
    try:
        v = float(pl["value"] or 0)
    except Exception:
        v = 0.0
    vs = int(v) if v == int(v) else round(v, 2)
    lb = str(pl["label"] or "").strip()
    if lb:
        return lb[:40]      # নিজের দেওয়া নাম (যেমন "১ মাস", "India Proxy") আগে
    _k = str(cat_kind or "").strip().lower() or str(pl["kind"] or "days")
    if _k == "mb":
        return f"{vs}"          # Proxy-তে অটো MB/GB নয় — নাম দিতেই হবে
    return f"{vs} দিন"


def shop_cats(only_active=True):
    _shop_plan_ddl()      # plan_kind কলাম নিশ্চিত
    sql = "SELECT * FROM shop_categories"
    if only_active:
        sql += " WHERE COALESCE(is_active,1)=1"
    sql += " ORDER BY sort_order, id"
    with _c() as c:
        return c.execute(sql).fetchall()


def _onoff(v):
    """is_active-এর সঠিক মান — 0 মানে বন্ধ।
    ⚠️ `int(v or 1)` লিখলে 0-ও 1 হয়ে যায় (বন্ধ ক্যাটাগরি চালু দেখাত)।
    """
    if v is None or v == "":
        return 1
    try:
        return 0 if int(v) == 0 else 1
    except Exception:
        return 1


def shop_cat(cid):
    _shop_plan_ddl()
    with _c() as c:
        return c.execute("SELECT * FROM shop_categories WHERE id=%s", (cid,)).fetchone()


def shop_cat_set_active(cid, active):
    """ক্যাটাগরি চালু/বন্ধ — বন্ধ থাকলে ইউজারের দোকানে দেখাবে না।"""
    with _c() as c:
        c.execute("UPDATE shop_categories SET is_active=%s WHERE id=%s",
                  (1 if active else 0, int(cid)))


def shop_cat_add(name, emoji="🛍"):
    with _c() as c:
        r = c.execute(
            "INSERT INTO shop_categories (name, emoji, sort_order, is_active, created_at) "
            "VALUES (%s,%s,%s,1,%s) RETURNING id",
            ((name or "")[:80], (emoji or "🛍")[:8],
             int(c.execute("SELECT COALESCE(MAX(sort_order),0)+1 AS n FROM shop_categories").fetchone()["n"] or 1),
             now())).fetchone()
    return int(r["id"]) if r else 0


def shop_products(cid=None, only_active=True, plan_id=None):
    _shop_plan_ddl()
    sql = ("SELECT p.*, "
           "(SELECT COUNT(*) FROM shop_stock s WHERE s.product_id=p.id AND COALESCE(s.sold,0)=0) AS stock, "
           "(SELECT COUNT(*) FROM shop_stock s2 WHERE s2.product_id=p.id AND COALESCE(s2.sold,0)=1) AS sold_n "
           "FROM shop_products p WHERE 1=1")
    args = []
    if only_active:
        sql += " AND COALESCE(p.is_active,1)=1"
    if cid is not None:
        sql += " AND COALESCE(p.category_id,0)=%s"
        args.append(int(cid))
    if plan_id is not None:
        sql += " AND COALESCE(p.plan_id,0)=%s"
        args.append(int(plan_id))
    sql += " ORDER BY p.sort_order, p.id"
    with _c() as c:
        return c.execute(sql, tuple(args)).fetchall()


