def shop_product_set_ref(pid, pct):
    """পণ্যের রেফার কমিশন % — -1 মানে ডিফল্ট (গ্লোবাল) %।"""
    try:
        v = float(pct)
    except Exception:
        v = -1.0
    v = -1.0 if v < 0 else min(90.0, v)
    with _c() as c:
        c.execute("UPDATE shop_products SET ref_pct=%s WHERE id=%s", (v, int(pid)))
    return v


_SHOP_FIELD_MAX = 8


def shop_product_fields(p):
    """পণ্যের ফিল্ড-নামের তালিকা — যেমন ["Number","Username","Password"]।"""
    try:
        if "fields" not in (p.keys() if hasattr(p, "keys") else []):
            return []
        raw = str(p["fields"] or "").strip()
    except Exception:
        return []
    if not raw:
        return []
    out = [x.strip()[:24] for x in re.split(r"[\n|,;]+", raw) if x.strip()]
    return out[:_SHOP_FIELD_MAX]


def shop_product_set_fields(pid, text):
    """ফিল্ড-নাম সেভ (লাইন/`,`/`|` দিয়ে আলাদা)। খালি বা `-` = মুছে ফেলা।"""
    raw = str(text or "").strip()
    if raw in ("-", "—"):
        raw = ""
    parts = [x.strip()[:24] for x in re.split(r"[\n|,;]+", raw) if x.strip()]
    val = "|".join(parts[:_SHOP_FIELD_MAX])
    with _c() as c:
        c.execute("UPDATE shop_products SET fields=%s WHERE id=%s", (val, int(pid)))
    return parts[:_SHOP_FIELD_MAX]


def _shop_split_item(line):
    """স্টকের এক লাইনকে ফিল্ডে ভাগ করে — ট্যাব / | / , / ২+ স্পেস / স্পেস।"""
    sline = str(line or "").strip()
    if not sline:
        return []
    for sep in ("\t", "|", ","):
        if sep in sline:
            return [x.strip() for x in sline.split(sep) if x.strip()]
    parts = [x.strip() for x in re.split(r"\s{2,}", sline) if x.strip()]
    if len(parts) > 1:
        return parts
    return [x for x in sline.split() if x]


def shop_product_ref_pct(p):
    """পণ্যের কার্যকর কমিশন % (None = গ্লোবাল ডিফল্ট ব্যবহার হবে)।"""
    try:
        keys = p.keys() if hasattr(p, "keys") else []
        if "ref_pct" not in keys:
            return None
        v = p["ref_pct"]
        if v is None:
            return None
        v = float(v)
    except Exception:
        return None
    return None if v < 0 else min(90.0, v)


async def shop_pay_referral(bot, uid, p, total):
    """শপ কেনায় রেফারারকে কমিশন — প্রতি পণ্যের % থাকলে সেটাই।"""
    try:
        rid = await asyncio.to_thread(get_referred_by, uid)
        if not rid or int(rid) == int(uid):
            return 0.0
        base = float(total or 0)
        if base <= 0:
            return 0.0
        _pct = shop_product_ref_pct(p)
        if _pct is None:
            _pct = await asyncio.to_thread(get_shop_ref_pct)
        if _pct is not None and _pct <= 0:
            return 0.0
        try:
            _nm = str(p.get("name") or "Shop")
        except Exception:
            _nm = "Shop"
        return await _pay_commission(bot, int(rid), uid, base, f"🛍 {_nm}"[:60], pct=_pct)
    except Exception as e:
        log.warning(f"[SHOP] রেফার কমিশন ব্যর্থ uid={uid}: {e}")
        return 0.0


