def _mask_uname(name):
    """চ্যানেলে ইউজারের নাম আধা-মাস্ক: `Zia uddin` → `Zia***n`."""
    t = str(name or "").strip()
    if not t:
        return "***"
    if t.isdigit():
        return t[:2] + "***" + t[-1:]
    core = t[1:] if t.startswith("@") else t
    if len(core) <= 3:
        return core[:1] + "***"
    return core[:3] + "***" + core[-1:]


_USED_TX_DDL = [False]


def _used_tx_ddl():
    """used_txids টেবিল + deposits.admin_hidden কলাম — একবারই।"""
    if _USED_TX_DDL[0]:
        return
    try:
        with _c() as c:
            c.execute("CREATE TABLE IF NOT EXISTS used_txids ("
                      "txid TEXT PRIMARY KEY, user_id BIGINT DEFAULT 0, "
                      "amount REAL DEFAULT 0, created_at TEXT DEFAULT '')")
        try:
            with _c() as c:
                c.execute("ALTER TABLE deposits ADD COLUMN IF NOT EXISTS "
                          "admin_hidden INTEGER NOT NULL DEFAULT 0")
        except Exception:
            try:      # SQLite/পুরোনো PG — IF NOT EXISTS ছাড়া
                with _c() as c:
                    c.execute("ALTER TABLE deposits ADD COLUMN admin_hidden "
                              "INTEGER NOT NULL DEFAULT 0")
            except Exception:
                pass
        # ⚠️ যাচাই: কলাম সত্যিই যোগ হয়েছে কি না। আগে ALTER ব্যর্থ হলেও ফ্ল্যাগ
        # True হয়ে যেত → পরে আর কখনো চেষ্টা হতো না, admin_hidden থাকত না।
        _ok_col = True
        try:
            with _c() as c:
                c.execute("SELECT admin_hidden FROM deposits LIMIT 1").fetchone()
        except Exception:
            _ok_col = False
        if _ok_col:
            _USED_TX_DDL[0] = True
        else:
            log.warning("[USEDTX] deposits.admin_hidden এখনো যোগ হয়নি — পরে আবার চেষ্টা হবে")
    except Exception as e:
        log.debug(f"[USEDTX] ddl: {str(e)[:100]}")


def _tx_key(txid=""):
    return re.sub(r"\s+", "", str(txid or "")).upper()[:120]


def dep_tx_used(txid="", exclude_oid=0):
    """এই TxID আগে একবারও ব্যবহার হয়েছে কি না — ডিপোজিট রো ডিলিট হলেও ধরা পড়ে."""
    k = _tx_key(txid)
    if not k:
        return False
    # ⚠️ QR-এ `qr:3555` = নাম্বারের শেষ ৪ ডিজিট — আসল TxID নয়,
    #    একই ইউজার দুইবার ৩৫৫৫ দিলে আগে "TxID আগে ব্যবহার হয়েছে" বলে
    #    আটকে যেত। তাই এগুলো ডুপ্লিকেট হিসেবে ধরা হয় না।
    if k.startswith("QR:"):
        return False
    _used_tx_ddl()
    try:
        with _c() as c:
            if c.execute("SELECT 1 FROM used_txids WHERE txid=%s", (k,)).fetchone():
                return True
    except Exception:
        pass
    try:
        with _c() as c:
            row = c.execute(
                "SELECT id FROM deposits WHERE id<>%s AND LOWER(COALESCE(txid,''))=%s LIMIT 1",
                (int(exclude_oid or 0), k.lower())).fetchone()
        return bool(row)
    except Exception:
        return False


def dep_tx_mark(txid="", uid=0, amount=0.0):
    """TxID চিরতরে 'ব্যবহৃত' হিসেবে চিহ্নিত করো (ডিপোজিট রো মুছলেও থাকে)।"""
    k = _tx_key(txid)
    if not k or k.startswith("QR:"):
        return False
    _used_tx_ddl()
    try:
        with _c() as c:
            c.execute("INSERT INTO used_txids (txid,user_id,amount,created_at) "
                      "VALUES (%s,%s,%s,%s) ON CONFLICT (txid) DO NOTHING",
                      (k, int(uid or 0), float(amount or 0), now()))
        return True
    except Exception as e:
        log.debug(f"[USEDTX] mark: {str(e)[:80]}")
        return False


_PERF_IDX = [False]


def _perf_indexes():
    """হট কুয়েরির ইনডেক্স — প্রথম بارেই তৈরি, পরে skip।"""
    if _PERF_IDX[0]:
        return
    try:
        with _c() as c:
            for _q2 in (
                "CREATE INDEX IF NOT EXISTS idx_wd_user_status ON withdrawals(user_id, status)",
                "CREATE INDEX IF NOT EXISTS idx_gm_user_status ON gmails(user_id, status)",
                "CREATE INDEX IF NOT EXISTS idx_dep_user_status ON deposits(user_id, status)",
                "CREATE INDEX IF NOT EXISTS idx_dep_status_created ON deposits(status, created_at)",
                "CREATE INDEX IF NOT EXISTS idx_fb_task_status ON fb_submissions(task_id, status)",
                "CREATE INDEX IF NOT EXISTS idx_ig_task_status ON ig_submissions(task_id, status)",
                "CREATE INDEX IF NOT EXISTS idx_comm_user ON commissions(user_id)",
                "CREATE INDEX IF NOT EXISTS idx_userhist_user ON user_hist(user_id)",
            ):
                try:
                    c.execute(_q2)
                except Exception:
                    pass
        _PERF_IDX[0] = True
        log.info("[PERF] hot indexes ready")
    except Exception as _ie:
        log.debug(f"[PERF] index: {str(_ie)[:80]}")


def dep_hide_old(hours=24):
    """approved/rejected ডিপোজিট ১ দিন পর অ্যাডমিন প্যানেল থেকে সরাও
    (রো মুছি না — ইউজারের হিস্ট্রি অটুট থাকে)।"""
    _used_tx_ddl()
    cut = _time.time() * 1000 - int(hours) * 3600 * 1000
    ids = []
    try:
        with _c() as c:
            rows = c.execute(
                "SELECT id, created_at, COALESCE(admin_hidden,0) AS h FROM deposits "
                "WHERE status IN ('approved','rejected')").fetchall()
        for r in rows:
            if int(r["h"] or 0):
                continue
            ms = _dep_created_ms(r) or 0
            if ms and ms <= cut:
                ids.append(int(r["id"]))
        if ids:
            with _c() as c:
                for i in ids:
                    c.execute("UPDATE deposits SET admin_hidden=1 WHERE id=%s", (i,))
    except Exception as e:
        log.debug(f"[DEP-HIDE] {str(e)[:100]}")
        return 0
    return len(ids)


