            for _ra, _rt, _rw, _ru in _rec:
                lines.append(f"• `{_ra:g}$` · `{_ms_bd(_rw)}` · "
                             f"`{str(_rt)[:26]}`" + (" _(আগে ব্যবহৃত)_" if _ru else ""))
