def dep_new(uid, m, amount, txid="", note="", status="pending", proof="", uniq="",
            payer=""):
    oid = 0
    with _c() as c:
        cur = c.execute(
            "INSERT INTO deposits (user_id, method_id, method_name, kind, amount, status, "
            "txid, note, proof, uniq_code, payer_name, created_at) "
            "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING id",
            (int(uid), int(m["id"]), str(m["name"] or "")[:80], str(m["kind"] or "manual"),
             float(amount or 0), status, (txid or "").strip()[:120], (note or "")[:900],
             (proof or "").strip()[:400], (uniq or "").strip().upper()[:12],
             (payer or "").strip()[:60], now())
        )
        r = cur.fetchone()
        if r and r.get("id"):
            oid = int(r["id"])
        if not oid:
            try:
                oid = int(cur.lastrowid or 0)
            except Exception:
                oid = 0
        if not oid:
            try:
                _r = c.execute("SELECT id FROM deposits ORDER BY id DESC LIMIT 1").fetchone()
                oid = int(_r["id"]) if _r else 0
            except Exception:
                oid = 0
    return oid


_DEP_PROOF_STOP = {"binance", "pending", "payment", "deposit", "screenshot",
                   "google", "photos", "photo", "image", "transaction", "orderid",
                   "trxid", "txid", "usdt", "wallet", "amount", "phone", "bkash",
                   "nagad", "rocket", "manual", "approved", "rejected", "success"}


def _dep_proof_tokens(*vals):
    """প্রমাণ থেকে তুলনাযোগ্য টোকেন — TxID / হ্যাশ / Order ID / ফটো আইডি।

    "TrxID: 8877665544332211" → ["8877665544332211"]
    ছবির file_id-ও টোকেন হিসেবে ধরা হয়।
    """
    toks = []
    for v in vals:
        t = str(v or "").casefold()
        for _m in re.finditer(r"[a-z0-9]{6,}", t):
            k = _m.group(0)
            if k in _DEP_PROOF_STOP:
                continue
            # TxID / UID / ছবির file_id-তে ডিজিট থাকে; শুধু শব্দ হলে প্রমাণ নয়
            if sum(ch.isdigit() for ch in k) < 2 and len(k) < 25:
                continue
            if k not in toks:
                toks.append(k)
    return toks[:6]


def _dep_proof_key(text):
    """প্রমাণের মূল key (পুরোনো কলের জন্য)।"""
    toks = _dep_proof_tokens(text)
    return toks[0] if toks else ""


def _dep_proof_blob(txid="", photo="", text=""):
    """ডিপোজিটের প্রমাণ — নরমালাইজ করা টোকেনগুলো (| দিয়ে জোড়া)।"""
    return "|".join(_dep_proof_tokens(txid, photo, text))[:400]


def dep_proof_used(txid="", photo="", text="", exclude=0):
    """এই TxID / ছবি / প্রমাণ আগেই কোনো ডিপোজিটে ব্যবহার হয়েছে কি না।"""
    toks = _dep_proof_tokens(txid, photo, text)
    if not toks:
        return False
    with _c() as c:
        for k in toks:
            row = c.execute(
                "SELECT id FROM deposits WHERE id<>%s AND ("
                "LOWER(COALESCE(txid,''))=%s OR LOWER(COALESCE(proof,'')) LIKE %s) "
                "LIMIT 1",
                (int(exclude or 0), k, "%" + k + "%")).fetchone()
            if row:
                return True
    return False


