        if d == "adm_dep":
            return await _dep_admin_panel(q)
        if d == "depa:methods":
            return await _dep_admin_methods(q)
        if d == "depa:pend":
            return await _dep_admin_pending(q)
        if d == "depa:new":
            ctx.user_data["dep_new"] = {}
            ctx.user_data["state"] = "depa_new_name"
