    if st == "depa_new_addr":
        info["address"] = txt
        ctx.user_data["dep_new"] = info
        info["state_kind"] = info.get("kind")
        ctx.user_data["state"] = "depa_new_min"
        await update.message.reply_text(
            "📉 *ধাপ ৪/৪ — সর্বনিম্ন ডিপোজিট*\n\nশুধু সংখ্যা লিখুন (যেমন `1`)।",
            parse_mode="Markdown")
