async def on_document(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    if not update.effective_user:
        return
    uid = update.effective_user.id
    st  = ctx.user_data.get("state")

    # ── Admin: FB / IG Task ভিডিও (document হিসেবে) ──
    if st == "fbt_video_file":
        try:
            if await task_video_admin_file(update, ctx, str(st)):
                return
        except Exception as _tvd:
            log.warning(f"[TASK-VIDEO] ডকুমেন্ট আপলোড ব্যর্থ: {_tvd}")

    # ── Admin: Shop স্টক ফাইল (.txt) আপলোড ──
    if st and str(st).startswith("shopa_txt:") and await asyncio.to_thread(is_admin, uid):
        pid = int(str(st).split(":")[1])
        doc = update.message.document
        try:
            tf = await ctx.bot.get_file(doc.file_id)
            raw = await tf.download_as_bytearray()
            text = bytes(raw).decode("utf-8", "ignore")
        except Exception as e:
            await update.message.reply_text(f"❌ ফাইল পড়া যায়নি: {e}")
            return
        added, dup = await asyncio.to_thread(shop_add_stock, pid, text)
        ctx.user_data.pop("state", None)
        if not added and not dup:
            await update.message.reply_text("❌ ফাইলে কিছু পাওয়া যায়নি (<code>utf-8</code> txt দিন)।",
                                            parse_mode="HTML")
            return
        total = await asyncio.to_thread(shop_stock_count, pid)
        note = f"\n♻️ ডুপ্লিকেট বাদ: `{dup}`" if dup else ""
        await update.message.reply_text(
            f"✅ ফাইল থেকে `{added}` টা স্টক যোগ হয়েছে।{note}\n📥 এখন মোট স্টক: `{total}`",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🔙 পণ্যে ফিরুন", callback_data=f"shopa:p:{pid}")]]))
        return

    if st == "adm_restore_db" and await asyncio.to_thread(is_admin, uid):
        # PostgreSQL mode — file restore দরকার নেই
        ctx.user_data.pop("state", None)
        await update.message.reply_text(
            "ℹ️ *সব data ডাটাবেসে স্থায়ীভাবে সেভ থাকে।*\n\n"
            "🗄 প্রতিবার data বদলালে auto JSON backup ব্যাকআপ চ্যানেলে চলে যায়।",
            parse_mode="Markdown"
        )
        return

    # ── Admin: Demo Video (as document/file) — Category Task ─────
    if st == "adm_ctask_set_video_file" and await asyncio.to_thread(is_admin, uid):
        tid = ctx.user_data.pop("edit_ctask_id", None)
        ctx.user_data.pop("state", None)
        doc = update.message.document
        if doc and tid:
            await asyncio.to_thread(update_category_task, tid, "demo_video_id", doc.file_id)
            await update.message.reply_text(
                "✅ *Demo Video সেট হয়েছে!*\n\n"
                "Task এ এখন 'ভিডিও দেখুন' বাটন দেখা যাবে।",
                parse_mode="Markdown", reply_markup=await asyncio.to_thread(main_kb, uid))
        else:
            await update.message.reply_text("❌ ভিডিও পাওয়া যায়নি।", parse_mode="Markdown")
        return

    # ── Admin: Demo Video (as document/file) — Regular Task ──────
    if st == "adm_task_set_video_file" and await asyncio.to_thread(is_admin, uid):
        tid = ctx.user_data.pop("edit_tid", None)
        ctx.user_data.pop("state", None)
        doc = update.message.document
        if doc and tid:
            await asyncio.to_thread(update_task_field_val, tid, "demo_video_id", doc.file_id)
            await update.message.reply_text(
                "✅ *Demo Video সেট হয়েছে!*\n\n"
                "Task এ এখন 'ভিডিও দেখুন' বাটন দেখা যাবে।",
                parse_mode="Markdown", reply_markup=await asyncio.to_thread(main_kb, uid))
        else:
            await update.message.reply_text("❌ ভিডিও পাওয়া যায়নি।", parse_mode="Markdown")
        return
    # non-restore document — ignore


