async def cmd_webadmin(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Admin — ওয়েব প্যানেলের লিংক ও key (শুধু অ্যাডমিন)।"""
    u = update.effective_user
    if not u:
        return
    try:
        if not await asyncio.to_thread(is_admin, u.id):
            return
    except Exception:
        return
    base = _vrf_panel_base() or _VRF_BASE_FALLBACK
    key = ""
    try:
        key = (get_setting("admin_web_key") or "").strip()
        if not key:
            import base64 as _b64, os as _os
            key = _b64.urlsafe_b64encode(_os.urandom(9)).decode().rstrip("=")
            set_setting("admin_web_key", key)
    except Exception as _e:
        key = f"ERR {_e}"
    # গোপন এন্ট্রি-লিংক (?k=...) — কেউ URL অনুমান করে ঢুকতে পারবে না
    secret = ""
    try:
        # প্যানেলও আগে env দেখে — দুই জায়গায় একই কী না হলে লিংক 404 হতো
        import os as _os2
        secret = (_os2.environ.get("PANEL_URL_SECRET") or "").strip()
        if not secret:
            secret = (get_setting("panel_url_secret") or "").strip()
        if not secret:
            import base64 as _b64, os as _os
            secret = _b64.urlsafe_b64encode(_os.urandom(12)).decode().rstrip("=")
            set_setting("panel_url_secret", secret)
    except Exception:
        secret = ""
    link = f"{base}/admin" + (f"?k={secret}" if secret else "")
    await update.message.reply_text(
        f"🖥 *Admin Web Panel*\n\n🔗 {link}\n"
        f"👤 Username: `admin`\n🔑 Password: `{key}`\n\n"
        "🔒 উপরের লিংকটাই আসল দরজা — `?k=` ছাড়া `/admin` খুললে 404 দেখাবে.\n"
        "⚠️ লিংক/কি কারো সাথে শেয়ার করবেন না।",
        parse_mode="Markdown", disable_web_page_preview=True,
    )


