def _setup_uptimerobot():
    """
    UptimeRobot API দিয়ে monitor auto-register করো।
    Env vars:
      UPTIMEROBOT_API_KEY  — UptimeRobot Main API key (ur...)
      BOT_PUBLIC_URL       — (optional) override ping URL
    """
    api_key = _get_env("UPTIMEROBOT_API_KEY")

    # Public URL বের করো — API key থাকুক বা না থাকুক URL সবসময় log করো
    bot_url = _get_env("BOT_PUBLIC_URL")
    if not bot_url:
        domains = _get_env("REPLIT_DOMAINS")
        if domains:
            first_domain = domains.split(",")[0].strip()
            bot_url = f"https://{first_domain}"

    ping_url = (bot_url.rstrip("/") + "/api/bot-ping") if bot_url else ""

    if not api_key:
        return  # VPS-এ UptimeRobot optional — শুধু key থাকলে চলবে
    if not bot_url:
        return

    def _ur_post(endpoint, params):
        """UptimeRobot v2 POST — error হলে response body সহ log করো।"""
        data = urllib.parse.urlencode({**params, "api_key": api_key, "format": "json"}).encode()
        req = urllib.request.Request(
            f"https://api.uptimerobot.com/v2/{endpoint}",
            data=data,
            headers={
                "Content-Type": "application/x-www-form-urlencoded",
                "Cache-Control": "no-cache",
            },
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=15) as r:
                return _json.loads(r.read())
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", errors="replace")
            log.warning(f"[UptimeRobot] HTTP {e.code} — {body[:200]}")
            return None
        except Exception as e:
            log.warning(f"[UptimeRobot] request ব্যর্থ: {e}")
            return None

    try:
        # আগে চেক করো duplicate আছে কিনা
        result = _ur_post("getMonitors", {"search": "Task Earn Bot"})
        if result is None:
            log.warning(f"[UptimeRobot] getMonitors ব্যর্থ — URL টি manually দিন: {ping_url}")
            return
        if result.get("stat") == "ok" and result.get("monitors"):
            existing_url = result["monitors"][0].get("url", "")
            if existing_url != ping_url:
                log.info("[UptimeRobot] Monitor আছে কিন্তু URL পুরনো — update হবে না (manually করুন)।")
            else:
                log.info("✅ [UptimeRobot] Monitor আগে থেকেই আছে ✓")
            return

        # নতুন monitor তৈরি করো
        result2 = _ur_post("newMonitor", {
            "type":          "1",       # HTTP(s)
            "url":           ping_url,
            "friendly_name": "Task Earn Bot",
        })
        if result2 is None:
            log.warning(f"[UptimeRobot] newMonitor ব্যর্থ — manually দিন: {ping_url}")
            return
        if result2.get("stat") == "ok":
            mid = result2.get("monitor", {}).get("id", "?")
            log.info(f"✅ [UptimeRobot] Monitor তৈরি! ID={mid} | URL={ping_url}")
        else:
            err = result2.get("error", result2)
            log.warning(f"[UptimeRobot] Monitor তৈরি ব্যর্থ: {err} — manually দিন: {ping_url}")

    except Exception as e:
        log.warning(f"[UptimeRobot] setup ব্যর্থ: {e} — manually দিন: {ping_url}")


# ═══════════════════ FB / IG রিভিউ (approve · reject) ═══════════════════
# অ্যাডমিন প্যানেলে UID/Username লিস্ট দিয়ে approve/reject হয়। টাকা যোগ করা আর
# ইউজারকে নোটিফিকেশন পাঠানো — দুটোই বট করে, যাতে প্যানেল থেকে ব্যালেন্স বদলে
# বটের ক্যাশ (১০ মিনিট TTL) ভুল না দেখায়।

_REVIEW_READY = [False]
_REVIEW_TABLES = ("fb_submissions", "ig_submissions")
_REVIEW_LOOP = [None]     # বটের event loop (প্যানেল অন্য থ্রেড থেকে ডাকে)
_REVIEW_CTX = [None]      # job-এর জন্য context (bot সহ)
_REVIEW_DDL = (
    "ALTER TABLE fb_submissions ADD COLUMN IF NOT EXISTS paid INTEGER DEFAULT 1",
    "ALTER TABLE fb_submissions ADD COLUMN IF NOT EXISTS notified INTEGER DEFAULT 1",
    "ALTER TABLE fb_submissions ADD COLUMN IF NOT EXISTS reviewed_at TEXT DEFAULT ''",
    "ALTER TABLE ig_submissions ADD COLUMN IF NOT EXISTS paid INTEGER DEFAULT 1",
    "ALTER TABLE ig_submissions ADD COLUMN IF NOT EXISTS notified INTEGER DEFAULT 1",
    "ALTER TABLE ig_submissions ADD COLUMN IF NOT EXISTS reviewed_at TEXT DEFAULT ''",
    "CREATE INDEX IF NOT EXISTS idx_fbsub_notify ON fb_submissions (notified, status)",
    "CREATE INDEX IF NOT EXISTS idx_igsub_notify ON ig_submissions (notified, status)",
)


def _review_init():
    """paid / notified / reviewed_at কলাম — পুরনো DB-তেও নিরাপদে যোগ হয়।

    ⚠️ প্রতিটি statement আলাদা transaction-এ: আগে সব একসাথে চালানো হতো, আর
    ig_submissions টেবিল না থাকলে ওই ব্যর্থ statement পুরো transaction
    rollback করত — ফলে fb_submissions-এর notified/paid কলাম কখনো তৈরি হতো না
    এবং ওয়েব প্যানেলের approve-এ টাকা/রেফার কমিশন যোগ হতো না।
    """
    if _REVIEW_READY[0]:
        return
    ok = True
    for q in _REVIEW_DDL:
        try:
            with _c() as c:
                c.execute(q)
        except Exception as e:
            log.debug(f"[REVIEW] DDL skip: {q[:40]} → {e}")
            if "fb_submissions" in q or "idx_fbsub" in q:
                ok = False
    _REVIEW_READY[0] = ok


def _review_rows(limit=80):
    """notified=0 আর approved/rejected — প্যানেল সিদ্ধান্ত দিয়েছে, বট বাকি কাজ করবে।"""
    _review_init()
    out = []
    for table, task_tbl, idcol, pwdcol in (
        ("fb_submissions", "fb_tasks", "fb_uid", "fb_password"),
        ("ig_submissions", "ig_tasks", "ig_username", "ig_password"),
    ):
        try:
            with _c() as c:
                rows = c.execute(
                    f"SELECT s.id AS sid, s.user_id, s.status, s.{idcol} AS ident, "
                    f"       s.{pwdcol} AS pwd, s.data, COALESCE(s.paid,1) AS paid, "
                    f"       COALESCE(t.price,0) AS price, COALESCE(t.name,'') AS tname "
                    f"  FROM {table} s LEFT JOIN {task_tbl} t ON t.id=s.task_id "
                    f" WHERE s.notified=0 AND s.status IN ('approved','rejected') "
                    f" ORDER BY s.user_id, s.id LIMIT %s", (limit,)).fetchall()
        except Exception as e:
            log.debug(f"[REVIEW] {table} পড়া যায়নি: {e}")
            continue
        for r in rows or []:
            d = dict(r)
            d["table"] = table
            out.append(d)
    return out


def _review_pay(table, sub_id, uid, price):
    """approve + আগে পেইড না হলে — ঠিক একবারই টাকা যোগ।"""
    if table not in _REVIEW_TABLES:
        return False
    paid = False
    try:
        with _c() as c:
            cur = c.execute(
                f"UPDATE {table} SET paid=1 WHERE id=%s AND COALESCE(paid,0)=0", (sub_id,))
            if cur.rowcount:
                c.execute("UPDATE users SET balance=balance+%s WHERE user_id=%s", (price, uid))
                paid = True
    except Exception as e:
        log.warning(f"[REVIEW] pay ব্যর্থ {table}#{sub_id}: {e}")
        return False
    if paid:
        try:
            _invalidate_user_cache(uid)
            _mark_dirty()
        except Exception:
            pass
    return paid


def _review_mark(table, ids):
    """নোটিফিকেশন পাঠানো শেষ — আর পাঠানো হবে না।"""
    if table not in _REVIEW_TABLES:
        return
    try:
        with _c() as c:
            for i in ids:
                c.execute(f"UPDATE {table} SET notified=1 WHERE id=%s", (i,))
    except Exception as e:
        log.warning(f"[REVIEW] notified mark ব্যর্থ {table}: {e}")
        return
    # মেসেজ পাঠানো শেষ → এখন সংবেদনশীল ডেটা মুছে দাও (সারি থেকে যায়)
    try:
        _review_purge(table, ids)
    except Exception as e:
        log.warning(f"[REVIEW] purge {table}: {e}")


_PURGE_COLS = {
    "fb_submissions": ("fb_password", "login_first", "login_last", "login_password"),
    "ig_submissions": ("ig_password", "login_password"),
}


def _review_purge(table, ids=None):
    """review হয়ে গেলে (notified=1) সংবেদনশীল ডেটা মুছে ফেলো।

    পাসওয়ার্ড / লগইন নাম / কুকিজ-2FA সহ `data` JSON মুছে যায় — ডেটাবেস ছোট হয়।
    সারি, UID/Username, status, তারিখ থেকে যায় — তাই ইউজার কয়টা কাজ করেছে
    (আর ডুপ্লিকেট চেক) সবই আগের মতো কাজ করে।
    """
    if table not in _REVIEW_TABLES:
        return 0
    sets = ", ".join(f"{c}=''" for c in _PURGE_COLS[table]) + ", data='{}'"
    sql = (f"UPDATE {table} SET {sets} WHERE status IN ('approved','rejected') "
           f"AND COALESCE(notified,0)=1 AND COALESCE(data,'')<>'{{}}'")
    args = ()
    if ids:
        sql += f" AND id IN ({','.join(['%s'] * len(ids))})"
        args = tuple(ids)
    try:
        with _c() as c:
            cur = c.execute(sql, args) if args else c.execute(sql)
            return cur.rowcount or 0
    except Exception as e:
        log.warning(f"[REVIEW] purge ব্যর্থ {table}: {e}")
        return 0


def _review_2fa(data_raw):
    """জমার data থেকে 2FA কোড/key (থাকলে)।"""
    try:
        d = _json.loads(data_raw or "{}")
    except Exception:
        return ""
    if not isinstance(d, dict):
        return ""
    for k, v in d.items():
        kk = str(k).lower()
        if ("2fa" in kk or "totp" in kk or "2step" in kk) and str(v or "").strip():
            return str(v).strip()
    return ""


def _review_safe(v):
    """Telegram Markdown-এর code span ভাঙবে না।"""
    return str(v or "").replace("`", "'").replace("\n", " ").strip()


def _review_text(lang, status, items, added):
    """এক ইউজারের সব সিদ্ধান্ত এক মেসেজে।"""
    en = (lang == "en")
    n = len(items)
    if status == "approved":
        lines = [("✅ *Task approved!*" if en else "✅ *টাস্ক এপ্রুভ হয়েছে!*"),
                 (f"📋 Count: {n}" if en else f"📋 পরিমাণ: {n} টি"),
                 f"💰 {'Added' if en else 'যুক্ত হয়েছে'}: ${added:.2f}", ""]
        for it in items:
            tail = (f"+${float(it.get('paid_now') or 0):.2f} 😁"
                    if float(it.get("paid_now") or 0) > 0 else "✅")
            lines.append(f"✅ `{_review_safe(it.get('ident'))}` "
                         + ("approved: " if en else "এপ্রুভ হয়েছে: ") + tail)
    else:
        lines = [("❌ *Task rejected!*" if en else "❌ *টাস্ক রিজেক্ট হয়েছে!*"),
                 (f"📋 Count: {n}" if en else f"📋 পরিমাণ: {n} টি"),
                 ("_(wrong or banned ID)_" if en else "_(ভুল বা ব্যান আইডির কারণে)_"), ""]
        for it in items:
            bits = [f"`{_review_safe(it.get('ident'))}`"]
            pwd = _review_safe(it.get("pwd"))
            if pwd:
                bits.append(f"`{pwd}`")
            two = _review_safe(it.get("2fa"))
            if two:
                bits.append(f"2FA: `{two}`")
            lines.append("🚨 " + " | ".join(bits))
    return "\n".join(lines).strip()


def _review_chunks(text, limit=3500):
    """Telegram-এর ৪০৯৬ অক্ষরের সীমা — বড় লিস্ট টুকরো করে।"""
    out, cur = [], ""
    for line in (text or "").split("\n"):
        if cur and len(cur) + len(line) + 1 > limit:
            out.append(cur)
            cur = line
        else:
            cur = (cur + "\n" + line) if cur else line
    if cur:
        out.append(cur)
    return out or [""]


_REVIEW_BUSY = [False]


async def job_fb_ig_review(ctx):
    """প্যানেলে approve/reject হওয়া FB/IG জমা → টাকা যোগ + নোটিফিকেশন।

    instant hook আর ২০s job একসাথে চললে যেন ডাবল মেসেজ না যায় — busy guard।
    """
    if _REVIEW_BUSY[0]:
        return
    _REVIEW_BUSY[0] = True
    try:
        await _fb_ig_review_once(ctx)
    except Exception as e:
        log.warning(f"[REVIEW] job ব্যর্থ: {e}")
    finally:
        _REVIEW_BUSY[0] = False


def _fb_ig_admin_notify_on():
    """FB/IG approve হলে অ্যাডমিনকে টেলিগ্রাম মেসেজ যাবে কি না (ডিফল্ট: বন্ধ)।"""
    try:
        return str(get_setting("fb_ig_admin_notify") or "off").strip().lower() in ("on", "1", "yes", "true")
    except Exception:
        return False


async def _fb_ig_review_once(ctx):
    try:
        rows = await asyncio.to_thread(_review_rows)
    except Exception as e:
        log.warning(f"[REVIEW] rows পড়া ব্যর্থ: {e}")
        return
    if not rows:
        return
    groups = {}
    for r in rows:
        groups.setdefault((int(r["user_id"]), str(r["status"] or "")), []).append(r)
    for (uid, status), items in groups.items():
        added = 0.0
        for it in items:
            price = float(it.get("price") or 0)
            it["2fa"] = _review_2fa(it.get("data"))
            it["paid_now"] = 0.0
            if status == "approved" and price > 0 and not int(it.get("paid") or 0):
                try:
                    ok = await asyncio.to_thread(
                        _review_pay, it["table"], int(it["sid"]), uid, price)
                except Exception as e:
                    log.warning(f"[REVIEW] pay কাজ ব্যর্থ: {e}")
                    ok = False
                if ok:
                    it["paid_now"] = price
                    added += price
                    # ✅ রেফারেল কমিশন — TG/gmail task-এর মতোই।
                    # আগে FB/IG approve-এ কিছুই যেত না, তাই referrer টাকা পেত না।
                    try:
                        _rref = await asyncio.to_thread(get_referred_by, uid)
                        if _rref:
                            await _pay_commission(ctx.bot, _rref, uid, price,
                                                  it.get("tname") or "Task")
                    except Exception as _rce:
                        log.warning(f"[REVIEW] commission ব্যর্থ uid={uid}: {_rce}")
        try:
            lang = await asyncio.to_thread(get_lang, uid)
        except Exception:
            lang = "bn"
        for part in _review_chunks(_review_text(lang or "bn", status, items, added)):
            try:
                await ctx.bot.send_message(uid, part, parse_mode="Markdown")
            except Exception as e:
                # Markdown ভাঙলে plain-এ আবার — নোটিফিকেশন যেন আটকে না যায়
                try:
                    await ctx.bot.send_message(uid, part.replace("*", "").replace("`", ""))
                except Exception as e2:
                    log.warning(f"[REVIEW] notify ব্যর্থ uid={uid} {status}: {e2}")
        # অ্যাডমিনের Task Notification সেটিং (channel / dm / both / off) — প্যানেল থেকেই নিয়ন্ত্রণ।
        # আগে আলাদা `fb_ig_admin_notify` (ডিফল্ট off, প্যানেলে কোনো অপশনই নেই) গেট ছিল,
        # তাই প্যানেলে নোটিফিকেশন চালু করলেও FB/IG-এর মেসেজ যেত না।
        if status == "approved":
            for it in items:
                try:
                    await _notify_task_done_ch(
                        ctx.bot, uid, it.get("tname") or "Task", "",
                        float(it.get("price") or 0),
                        "Facebook" if it["table"] == "fb_submissions" else "Instagram")
                except Exception as e:
                    log.debug(f"[REVIEW] task notify: {e}")
        for table in _REVIEW_TABLES:
            ids = [int(it["sid"]) for it in items if it["table"] == table]
            if ids:
                try:
                    await asyncio.to_thread(_review_mark, table, ids)
                except Exception as e:
                    log.warning(f"[REVIEW] mark কাজ ব্যর্থ: {e}")


