# পাসওয়ার্ড ইউজারের কাছে চাওয়া হয় না — টাস্কে অ্যাডমিন যেটা সেট করেন সেটাই ব্যবহার হবে
_FB_HIDE_TYPES = ("password",)

# ইনপুট ভ্যালিডেশন টাইপ — key থেকে অনুমান, চাইলে ফিল্ডে type দিয়ে বদলানো যায়
_FB_TYPES = ("uid", "password", "cookies", "2fa", "email", "number", "text")


def _fb_guess_type(key):
    k = str(key or "").lower()
    if k in ("uid", "fb_uid", "user_id", "profile", "id"):
        return "uid"
    if "cookie" in k:
        return "cookies"
    if "2fa" in k or "totp" in k or "2step" in k:
        return "2fa"
    if "pass" in k:
        return "password"
    if "mail" in k:
        return "email"
    return "text"


def _fb_2fa_key(txt):
    """2FA key নরমালাইজ — স্পেস/ড্যাশ বাদ, বড় হাতের অক্ষর।"""
    return re.sub(r"[\s\-]+", "", str(txt or "")).upper()


def _fb_totp(secret, digits=6, period=30):
    """RFC 6238 — Facebook Authenticator-এর মতো ৬ ডিজিটের কোড।

    key-টা মানুষ হাতে লেখে বলে নানা রকম হয় (স্পেস, ড্যাশ, ছোট হাতের, ভুলে
    0/1/8/9)। যতটা সম্ভব ঠিক করে নিয়েও ডিকোড না হলে ValueError — কলে
    ধরা পড়ে ইউজারকে স্পষ্ট মেসেজ দেখানো হয় (আগে চুপচাপ কিছুই আসত না)।
    """
    import base64, hmac, hashlib, struct
    sec = _fb_2fa_key(secret)
    sec = sec.translate(str.maketrans({"0": "O", "1": "I", "8": "B"}))
    sec = re.sub(r"[^A-Z2-7]", "", sec)          # Base32-এ যা নেই বাদ
    if len(sec) < 8:
        raise ValueError("too short")
    key = None
    for cut in (0, 1, 2, 3, 4, 5, 6):
        cand = sec[:len(sec) - cut] if cut else sec
        if not cand:
            break
        try:
            key = base64.b32decode(cand + "=" * (-len(cand) % 8))
            break
        except Exception:
            continue
    if key is None:
        raise ValueError("bad key")
    counter = int(_time.time()) // period
    digest = hmac.new(key, struct.pack(">Q", counter), hashlib.sha1).digest()
    off = digest[-1] & 0x0F
    code = (struct.unpack(">I", digest[off:off + 4])[0] & 0x7FFFFFFF) % (10 ** digits)
    return str(code).zfill(digits)


# ── Cookie যাচাই — কোন কোন key নেই সেটা আলাদা করে বলে (photo-2 স্টাইল) ──
_COOKIE_KV = re.compile(r"([A-Za-z0-9_\-]+)\s*=\s*([^;\n\r]*)")


def _cookie_parse(txt):
    """কুকি স্ট্রিং → {name: value}। newline/tab আর URL-এনকোড (%3B %3D) দুটোই সামলায়।"""
    s = str(txt or "").strip()
    if "%3d" in s.lower() or "%3b" in s.lower():
        try:
            s = urllib.parse.unquote(s)
        except Exception:
            pass
    s = s.replace("\r", ";").replace("\n", ";").replace("\t", ";")
    out = {}
    for _k, _v in _COOKIE_KV.findall(s):
        _k = _k.strip().lower().lstrip(".")
        if _k and _k not in out:
            out[_k] = _v.strip().strip(";").strip()
    return out


def _cookie_missing(txt, required):
    ck = _cookie_parse(txt)
    return [k for k in required if not str(ck.get(k) or "").strip()]


def _cookie_err_msg(missing, example=""):
    """কোন key নেই — একটা একটা করে দেখাও, তারপর ঠিক করার নিয়ম।"""
    miss = "".join(f"\n• Missing {k}." for k in missing)
    ex = f"\n\nউদাহরণ: {example}" if example else ""
    bn = ("⚠️ আপনার দেওয়া Cookies সঠিক নয়:" + miss + ex +
          "\n\nসঠিক করে আবার পেস্ট করুন — ব্রাউজারের সম্পূর্ণ কুকি কপি করুন।")
    en = ("⚠️ That payload is not valid:" + miss + ex +
          "\n\nFix it and paste again — copy the full cookie string from your browser.")
    return bn, en


def _fb_validate(field, txt):
    """(ok, ভুলের বার্তা-বাংলা, ভুলের বার্তা-English, extra কোড) — ভুল হলে পরের ধাপে এগোবে না।"""
    typ = (field.get("type") or _fb_guess_type(field.get("key"))).lower()
    v = (txt or "").strip()
    if typ == "uid":
        if not re.fullmatch(r"\d{14,16}", v):
            return (False,
                    "⚠️ দুঃখিত, এটি সঠিক UID নয়! অনুগ্রহ করে ১৪ থেকে ১৬ সংখ্যার সঠিক UID-টি দিন।",
                    "⚠️ Sorry, this UID is not valid! Please send the correct 14–16 digit UID.",
                    None)
    elif typ == "cookies":
        _ck = _cookie_parse(v)
        _miss = _cookie_missing(v, ("c_user",))
        if not (_ck.get("xs") or _ck.get("sessionid")):
            _miss.append("xs")
        if _miss:
            _bn, _en = _cookie_err_msg(_miss, "c_user=100012345678901; xs=32%3Aabc...; datr=xyz")
            return False, _bn, _en, None
    elif typ == "password":
        if len(v) < 6:
            return (False, "⚠️ Password খুব ছোট মনে হচ্ছে — সঠিক Facebook Password দিন।",
                    "⚠️ That password looks too short — send the correct Facebook password.", None)
    elif typ == "2fa":
        key = _fb_2fa_key(v)
        # ইংরেজি অক্ষর/সংখ্যা, মিনিমাম ৪ অক্ষর (স্পেস/ড্যাশ বাদ দিয়ে)
        if not re.fullmatch(r"[A-Z0-9]{4,}", key) or len(re.findall(r"[A-Z]", key)) < 2:
            return (False,
                    "⚠️ এটি সঠিক 2FA key নয়!\nkey-টি *ইংরেজি অক্ষর ও সংখ্যায়* মিনিমাম ৪ অক্ষরের "
                    "হতে হবে (যেমন `EOH5 WAFU GQG3 ABUK`)।\nFacebook-এর *Settings → Security → "
                    "Two-factor authentication → Authentication app* থেকে key-টি কপি করুন।",
                    "⚠️ That is not a valid 2FA key!\nThe key must be in English letters/digits, "
                    "at least 4 characters (e.g. `EOH5 WAFU GQG3 ABUK`). Copy it from Facebook → "
                    "Settings → Security → Two-factor authentication → Authentication app.",
                    None)
        try:
            return True, "", "", _fb_totp(key)
        except Exception as _te:
            log.debug(f"[FB-2FA] key decode ব্যর্থ: {_te}")
            return (False,
                    "⚠️ এই key থেকে কোড বানানো গেল না — key-টা ঠিকভাবে কপি হয়নি।\n"
                    "Facebook → Settings → Security → Two-factor authentication → "
                    "Authentication app → *Setup key* থেকে শুধু ইংরেজি অক্ষর/সংখ্যা দিয়ে "
                    "আবার দিন (যেমন `EOH5 WAFU GQG3 ABUK`)।",
                    "⚠️ Could not build a code from that key — the key was copied wrong.\n"
                    "Copy the setup key again from Facebook → Settings → Security → "
                    "Two-factor authentication → Authentication app.",
                    None)
    elif typ == "email":
        if "@" not in v or "." not in v.split("@")[-1]:
            return (False, "⚠️ সঠিক ইমেইল দিন।", "⚠️ Please send a valid email.", None)
    elif typ == "number":
        if not re.fullmatch(r"\d+", v):
            return (False, "⚠️ শুধু সংখ্যা দিন।", "⚠️ Numbers only, please.", None)
    return True, "", "", None

