async def job_dep_name_watch(ctx):
    """পেন্ডিং নাম-ডিপোজিট — মেইল-মোডে কাজ `job_dep_mail_watch` করে (০ API কল)।"""
    try:
        if await asyncio.to_thread(lambda: mail_cfg()["on"]):
            return
    except Exception:
        pass
    try:
        pend = await asyncio.to_thread(_dep_pending_named, 30)
        if not pend:
            return
        _now_ms = int(_time.time() * 1000)
        wins = []
        for o in pend:
            try:
                _o = o if hasattr(o, "get") else dict(o)
                if not str(_o.get("payer_name") or ""):
                    continue
                _cm = dep_created_ms(_o)
                if _cm and _now_ms > _cm + DEP_NAME_AFTER_MS + DEP_NAME_SLACK_MS:
                    continue      # ১০ মিনিট পার → আর অটো চেক নয়
                _ws, _we = dep_name_window(_o, _now_ms)
                if not _ws or _we <= _ws:
                    continue
                wins.append((_ws, _we, _o))
            except Exception:
                continue
        if not wins:
            return
        rows, err = await asyncio.to_thread(
            _binance_pay_rows_window,
            min(w[0] for w in wins), max(w[1] for w in wins))
        if err or not rows:
            return
        for _ws, _we, _o in wins:
            try:
                name = str(_o.get("payer_name") or "")
                # নিজের উইন্ডোর বাইরের পেমেন্ট বাদ — অন্য ডিপোজিটের টাকা মিলবে না
                _sub = []
                for it in rows:
                    try:
                        _tt = int(float(it.get("transactionTime") or 0))
                    except Exception:
                        _tt = 0
                    if _ws <= _tt <= _we:
                        _sub.append(it)
                if not _sub:
                    continue
                got = dep_name_match_rows(_sub, name, float(_o.get("amount") or 0))
                if not got:
                    continue
                _mid = int(_o.get("method_id") or 0)
                _m = await asyncio.to_thread(dep_method, _mid) if _mid else None
                if not _m:
                    _m = {"id": _mid, "name": str(_o.get("method_name") or ""),
                          "kind": str(_o.get("kind") or "uid")}
                await _dep_auto_credit(ctx, int(_o.get("user_id") or 0), _m,
                                       got[0], got[1], int(_o.get("id") or 0))
                log.info(f"[DEP-NAME] অটো ক্রেডিট #{_o.get('id')} tx={got[1][:18]}")
            except Exception as _e:
                log.debug(f"[DEP-NAME] item ব্যর্থ: {_e}")
    except Exception as e:
        log.debug(f"[DEP-NAME] job: {e}")


async def job_fb_password_rotate(ctx):
    """প্রতিদিন নির্দিষ্ট সময়ে পাসওয়ার্ড বদল।"""
    try:
        now_bd = datetime.now(BD_TZ)
        hhmm = now_bd.strftime("%H:%M")
        today = now_bd.strftime("%Y-%m-%d")
        tasks = await asyncio.to_thread(_fb_active_tasks_j)
        for t in tasks:
            if not int(t.get("password_auto") or 0):
                continue
            if await asyncio.to_thread(_pw_groups_exist, int(t["id"])):
                continue        # সিট-গ্রুপ আছে → অটো পাসওয়ার্ড বদল হবে না
            if (t.get("password_change_time") or "").strip() != hhmm:
                continue
            if str(t.get("password_last_change") or "").startswith(today):
                continue
            new_pw = _fb_new_password()
            try:
                with _c() as c:
                    c.execute("UPDATE fb_tasks SET password=%s, password_last_change=%s "
                              "WHERE id=%s", (new_pw, now_bd.strftime("%Y-%m-%d %H:%M"), t["id"]))
            except Exception as e:
                log.warning(f"[FB-PW] uid task {t.get('id')} ব্যর্থ: {e}")
                continue
            # ── pending জমাগুলোর পাসওয়ার্ডও নতুন + synced=0 → শিটে নতুন সারি যাবে ──
            try:
                with _c() as c:
                    c.execute("UPDATE fb_submissions SET fb_password=%s, synced=0 "
                              "WHERE task_id=%s AND status='pending'", (new_pw, t["id"]))
            except Exception as e:
                log.warning(f"[FB-PW] subs sync ব্যর্থ task {t.get('id')}: {e}")
            try:
                await ctx.bot.send_message(
                    ADMIN_ID,
                    f"🔑 *পাসওয়ার্ড অটো বদল হয়েছে*\n\n📘 {t.get('name')}\n"
                    f"নতুন Password: `{new_pw}`", parse_mode="Markdown")
            except Exception:
                pass
    except Exception as e:
        log.debug(f"[FB-PW] job: {e}")


async def job_fb_export(ctx):
    """নির্ধারিত সময়ে প্রতি টাস্কের আলাদা CSV অ্যাডমিনকে।"""
    try:
        now_bd = datetime.now(BD_TZ)
        hhmm = now_bd.strftime("%H:%M")
        today = now_bd.strftime("%Y-%m-%d")
        for t in await asyncio.to_thread(_fb_active_tasks_j):
            if (t.get("export_time") or "").strip() != hhmm:
                continue
            if str(t.get("last_export_at") or "").startswith(today):
                continue
            data, fname = await asyncio.to_thread(_fb_csv_bytes, t)
            try:
                await ctx.bot.send_document(
                    ADMIN_ID, document=data, filename=fname,
                    caption=f"📊 {t.get('name')} — Google Sheet (CSV)")
                with _c() as c:
                    c.execute("UPDATE fb_tasks SET last_export_at=%s WHERE id=%s",
                              (now_bd.strftime("%Y-%m-%d %H:%M"), t["id"]))
            except Exception as e:
                log.warning(f"[FB-EXPORT] task {t.get('id')}: {e}")
    except Exception as e:
        log.debug(f"[FB-EXPORT] job: {e}")


def _kick_review():
    """প্যানেলে approve/reject চাপা মাত্রই রিভিউ job চালাও (ফ্লাস্ক থ্রেড থেকেও)।"""
    loop, ctx = _REVIEW_LOOP[0], _REVIEW_CTX[0]
    if loop is None or ctx is None or loop.is_closed():
        return
    try:
        asyncio.run_coroutine_threadsafe(job_fb_ig_review(ctx), loop)
    except Exception as e:
        log.warning(f"[REVIEW] instant kick ব্যর্থ: {e}")


