# ইনপুট ভ্যালিডেশন টাইপ — key থেকে অনুমান, চাইলে ফিল্ডে type দিয়ে বদলানো যায়
_IG_TYPES = ("iguser", "password", "cookies", "2fa", "email", "number", "text")

# Instagram username: ইংরেজি অক্ষর, সংখ্যা, . এবং _ — সর্বোচ্চ ৩০ অক্ষর
_IG_USER_RE = re.compile(r"^[A-Za-z0-9._]{1,30}$")


def _ig_clean_user(txt):
    """@ বাদ, স্পেস বাদ, ছোট হাতের অক্ষরে — তুলনার জন্য।"""
    return re.sub(r"\s+", "", str(txt or "").strip()).lstrip("@").lower()


def _ig_username_ok(u):
    u = _ig_clean_user(u)
    if not u or not _IG_USER_RE.match(u):
        return False
    if u.startswith(".") or u.endswith(".") or ".." in u:
        return False
    if not re.search(r"[a-z0-9]", u):
        return False
    return True


def _ig_guess_type(key):
    k = str(key or "").lower()
    if k in ("username", "user", "ig", "iguser", "handle", "instagram", "user_name"):
        return "iguser"
    if "cookie" in k:
        return "cookies"
    if "2fa" in k or "totp" in k or "2step" in k:
        return "2fa"
    if "pass" in k:
        return "password"
    if "mail" in k:
        return "email"
    return "text"


def _ig_validate(field, txt):
    """(ok, বাংলা এরর, English এরর, extra কোড) — ভুল হলে পরের ধাপে এগোবে না।"""
    typ = (field.get("type") or _ig_guess_type(field.get("key"))).lower()
    v = (txt or "").strip()
    if typ in ("iguser", "username"):
        if not _ig_username_ok(v):
            return (False,
                    "⚠️ এটি সঠিক Instagram Username নয়!\nUsername-এ শুধু *ইংরেজি অক্ষর, সংখ্যা, "
                    "`.` আর `_`* থাকবে (১–৩০ অক্ষর)।\nযেমন: `johhrpv67`",
                    "⚠️ That is not a valid Instagram username!\nUse only English letters, digits, "
                    "`.` and `_` (1–30 characters), e.g. `johhrpv67`.",
                    None)
    elif typ == "cookies":
        _miss = _cookie_missing(v, ("sessionid", "ds_user_id", "csrftoken", "mid",
                                    "ig_did", "rur"))
        if _miss:
            _bn, _en = _cookie_err_msg(
                _miss, "sessionid=1742...%3A...; ds_user_id=1742...; csrftoken=Q4g...; "
                       "mid=auZW...; ig_did=...; rur=NHA...")
            return False, _bn, _en, None
    elif typ == "password":
        if len(v) < 6:
            return (False, "⚠️ Password খুব ছোট মনে হচ্ছে — সঠিক Instagram Password দিন।",
                    "⚠️ That password looks too short — send the correct Instagram password.", None)
    elif typ == "2fa":
        key = _fb_2fa_key(v)
        if not re.fullmatch(r"[A-Z0-9]{4,}", key) or len(re.findall(r"[A-Z]", key)) < 2:
            return (False,
                    "⚠️ এটি সঠিক 2FA key নয়!\nkey-টি *ইংরেজি অক্ষর ও সংখ্যায়* মিনিমাম ৪ অক্ষরের "
                    "হতে হবে (যেমন `EOH5 WAFU GQG3 ABUK`)।\nInstagram-এর *Settings → Security → "
                    "Two-factor authentication → Authentication app* থেকে key-টি কপি করুন।",
                    "⚠️ That is not a valid 2FA key!\nThe key must be in English letters/digits, "
                    "at least 4 characters (e.g. `EOH5 WAFU GQG3 ABUK`).",
                    None)
        try:
            return True, "", "", _fb_totp(key)
        except Exception as _te:
            log.debug(f"[FB-2FA] key decode ব্যর্থ: {_te}")
            return (False,
                    "⚠️ এই key থেকে কোড বানানো গেল না — key-টা ঠিকভাবে কপি হয়নি।\n"
                    "Facebook → Settings → Security → Two-factor authentication → "
                    "Authentication app → *Setup key* থেকে শুধু ইংরেজি অক্ষর/সংখ্যা দিয়ে "
                    "আবার দিন (যেমন `EOH5 WAFU GQG3 ABUK`)।",
                    "⚠️ Could not build a code from that key — the key was copied wrong.\n"
                    "Copy the setup key again from Facebook → Settings → Security → "
                    "Two-factor authentication → Authentication app.",
                    None)
    elif typ == "email":
        if "@" not in v or "." not in v.split("@")[-1]:
            return (False, "⚠️ সঠিক ইমেইল দিন।", "⚠️ Please send a valid email.", None)
    elif typ == "number":
        if not re.fullmatch(r"\d+", v):
            return (False, "⚠️ শুধু সংখ্যা দিন।", "⚠️ Numbers only, please.", None)
    return True, "", "", None

_IG_STATE = {}           # uid → {"task_id","step","answers","login","retry","ts"}
_IG_READY = [False]

# Sheet column token → হেডার লেবেল
_IG_COL_LABELS = {
    "sl": "SL", "date": "Date", "user_id": "Telegram ID", "tg_username": "TG Username",
    "username": "Username", "task": "Task", "account_no": "Account No",
    "login_username": "Login Username", "login_password": "Login Password",
    "uid": "uid", "password": "pass", "pass": "pass", "2fa": "2fa",
    "coki": "coki", "cookies": "coki", "cookie": "coki", "status": "Status",
}

# ছোট/এলোমেলো নাম → আসল কলাম
_IG_COL_ALIAS = {
    "pass": "password", "pw": "password", "ig_pass": "password",
    "user": "username", "iguser": "username", "ig": "username", "handle": "username",
    "coki": "cookies", "cookie": "cookies", "ck": "cookies",
    "totp": "2fa", "2step": "2fa", "auth2": "2fa",
    "tg": "tg_username", "tguser": "tg_username", "tg_id": "user_id",
    "login_user": "login_username", "login_pass": "login_password",
}


def _ig_data_key(task, typ):
    """এই টাইপের ফিল্ডের key (যেমন 2fa ফিল্ডের key) — না থাকলে টাইপের নাম।"""
    try:
        for f in _ig_fields(task or {}):
            if (f.get("type") or "") == typ:
                return f["key"]
    except Exception:
        pass
    return typ


def _ig_init():
    """টেবিল/ইনডেক্স — একবার। ব্যর্থ হলেও বট চলবে।"""
    if _IG_READY[0]:
        return True
    try:
        with _c() as c:
            for q in _IG_DDL:
                try:
                    c.execute(q)
                except Exception as e:
                    log.debug(f"[IG-TASK] DDL skip: {e}")
        _IG_READY[0] = True
        return True
    except Exception as e:
        log.warning(f"[IG-TASK] init ব্যর্থ: {e}")
        return False


def _ig_json(raw, default):
    try:
        v = _json.loads(raw or "")
        return v if isinstance(v, (list, dict)) else default
    except Exception:
        return default


def _ig_task(tid):
    def _q():
        _ig_init()
        try:
            with _c() as c:
                r = c.execute("SELECT * FROM ig_tasks WHERE id=%s", (int(tid),)).fetchone()
            return dict(r) if r else None
        except Exception as e:
            log.warning(f"[IG-TASK] task {tid} পড়া ব্যর্থ: {e}")
            return None
    return _memo_task(("ig", int(tid)), _q)


def _ig_active_tasks():
    _ig_init()
    try:
        with _c() as c:
            rows = c.execute(
                "SELECT * FROM ig_tasks WHERE is_active=1 ORDER BY id DESC").fetchall()
        return [dict(r) for r in rows]
    except Exception as e:
        log.warning(f"[IG-TASK] list ব্যর্থ: {e}")
        return []


def _ig_active_tasks_j():
    """jobs-এর জন্য ৯০ সেকেন্ড ক্যাশ — প্রতি মিনিটে পুরো ig_tasks স্ক্যান বন্ধ।"""
    return _memo_task(("ig_active_job",), _ig_active_tasks, 90) or []


def _ig_active_tasks_c():
    """active টাস্ক লিস্ট ২০s ক্যাশ।"""
    return _memo_task(("ig_active",), _ig_active_tasks, 20) or []


def _ig_counts_map_c(tids, uid=None):
    tids = tuple(int(t) for t in (tids or []))
    return _memo_task(("igcm", tids, uid), lambda: _ig_counts_map(list(tids), uid), 6) or {}


def _ig_fields(task):
    """ইউজারকে যা যা জিজ্ঞেস করা হবে — পুরোটাই অ্যাডমিন-সেট (প্যানেলের ফিল্ড লিস্ট)।

    fields কলাম NULL/ভাঙা → আগের টাস্কের জন্য নিরাপদ ডিফল্ট (2FA)।
    অ্যাডমিন কিছু সেট করলে *ঠিক সেটাই* — কিছু না থাকলে কিছুই জিজ্ঞেস করা হবে না।
    """
    raw = (task or {}).get("fields")
    f = _ig_json(raw, None)
    if f is None:
        return [dict(x) for x in _IG_DEFAULT_FIELDS]
    out = []
    for i, x in enumerate(f):
        if not isinstance(x, dict):
            continue
        _k = str(x.get("key") or f"f{i+1}")
        _t = str(x.get("type") or _ig_guess_type(_k)).lower()
        if _t in _IG_HIDE_TYPES:      # পাসওয়ার্ড অ্যাডমিন সেট করেন, ইউজার থেকে নেওয়া হয় না
            continue
        if _t == "username":
            _t = "iguser"
        out.append({
            "key": _k,
            "label_bn": str(x.get("label_bn") or x.get("label_en") or f"Field {i+1}"),
            "label_en": str(x.get("label_en") or x.get("label_bn") or f"Field {i+1}"),
            "required": 1 if x.get("required", 1) else 0,
            "type": _t,
        })
    return out


def _ig_counts(tid, uid=None):
    """(মোট জমা, এই ইউজারের জমা)"""
    try:
        with _c() as c:
            total = _count(c.execute(
                "SELECT COUNT(*) FROM ig_submissions WHERE task_id=%s", (tid,)).fetchone())
            mine = 0
            if uid:
                mine = _count(c.execute(
                    "SELECT COUNT(*) FROM ig_submissions WHERE task_id=%s AND user_id=%s",
                    (tid, uid)).fetchone())
        return total, mine
    except Exception:
        return 0, 0


def _ig_counts_map(tids, uid=None):
    """{task_id: (মোট, আমার)} — এক কোয়েরিতেই সব টাস্কের হিসাব (N round-trip → 1)।"""
    tids = [int(t) for t in (tids or [])]
    if not tids:
        return {}
    out = {t: (0, 0) for t in tids}
    ph = ",".join(["%s"] * len(tids))
    try:
        with _c() as c:
            rows = c.execute(
                f"SELECT task_id, COUNT(*) AS n, "
                f"       SUM(CASE WHEN user_id=%s THEN 1 ELSE 0 END) AS mine "
                f"  FROM ig_submissions WHERE task_id IN ({ph}) GROUP BY task_id",
                tuple([uid or 0] + tids)).fetchall()
        for r in rows or []:
            out[int(r["task_id"])] = (int(r["n"] or 0), int(r["mine"] or 0))
    except Exception as e:
        log.debug(f"[IG-TASK] counts map ব্যর্থ: {e}")
    return out


def _ig_username_exists(tid, name, ig_pass=None):
    """একই টাস্কে একই Username + একই পাসওয়ার্ড আগে জমা হয়েছে কি না।
    পাসওয়ার্ড বদলালে নতুন জমা (আলাদা সিট)।"""
    u = _ig_clean_user(name)
    if not u:
        return False
    try:
        with _c() as c:
            if ig_pass is None:
                r = c.execute(
                    "SELECT 1 AS x FROM ig_submissions WHERE task_id=%s "
                    "AND LOWER(TRIM(COALESCE(ig_username,''))) = %s LIMIT 1",
                    (int(tid), u.lower())).fetchone()
            else:
                r = c.execute(
                    "SELECT 1 AS x FROM ig_submissions WHERE task_id=%s "
                    "AND LOWER(TRIM(COALESCE(ig_username,''))) = %s "
                    "AND COALESCE(ig_password,'') = %s LIMIT 1",
                    (int(tid), u.lower(), str(ig_pass or "").strip())).fetchone()
        return bool(r)
    except Exception:
        return False
def _ig_live_free(name):
    """Instagram-এ এই Username আগেই আছে কি না — True=ফাঁকা, False=আছে, None=চেক করা গেল না।

    পাবলিক (লগইন ছাড়া) চেক; সার্ভার/IP ব্লক করলে None ফেরে — তখন ইউজার আটকাবে না।
    """
    u = _ig_clean_user(name)
    if not u:
        return None
    now_ts = _time.time()
    hit = _IG_AVAIL.get(u)
    if hit and now_ts - hit[0] < _IG_AVAIL_TTL:
        return hit[1]
    res = None
    try:
        req = urllib.request.Request(
            "https://www.instagram.com/api/v1/users/web_profile_info/?username=" + u,
            headers={"User-Agent": _IG_UA, "x-ig-app-id": "936619743392459",
                     "Accept": "*/*", "Accept-Language": "en-US,en;q=0.9"})
        with urllib.request.urlopen(req, timeout=6) as r:
            body = (r.read(300000) or b"").decode("utf-8", "ignore")
        flat = body.replace(" ", "")
        if '"user":null' in flat or "user not found" in body.lower():
            res = True
        elif '"username":"' in flat:
            res = False
    except urllib.error.HTTPError as e:
        if e.code in (404, 400):
            res = True
    except Exception as e:
        log.debug(f"[IG-TASK] availability check <{u}> failed: {e}")
    _IG_AVAIL[u] = (now_ts, res)
    if len(_IG_AVAIL) > 5000:
        for k, _v in sorted(_IG_AVAIL.items(), key=lambda kv: kv[1][0])[:2000]:
            _IG_AVAIL.pop(k, None)
    return res


def _ig_name_list(task):
    raw = str(task.get("username_list") or "").replace("\r", "\n")
    raw = raw.replace(",", "\n").replace("\t", "\n")
    out = []
    for x in raw.splitlines():
        x = _ig_clean_user(x)
        if x and x not in out:
            out.append(x)
    return out


def _ig_pick(task, idx=0):
    """লগইনের Username — fixed / upload (লিস্ট ধরে ঘুরবে) / random।"""
    mode = (task.get("username_mode") or "fixed").lower()
    fixed = _ig_clean_user(task.get("username"))
    lst = _ig_name_list(task)
    if mode in ("random", "shuffle") and lst:
        return random.choice(lst)
    if mode in ("upload", "list", "cycle") and lst:
        # ১০০ নাম + ২০০ কাজ → ১ম ১০০ আলাদা, পরের ১০০ আবার শুরু থেকে
        return lst[int(idx or 0) % len(lst)]
    if mode == "auto":
        # অ্যাডমিন লিস্ট দিলে সেটাই, না দিলে বট নিজেই ইউজারনেম বানায়
        return lst[int(idx or 0) % len(lst)] if lst else _auto_ig_username()
    if fixed:
        return fixed
    if lst:
        return lst[int(idx or 0) % len(lst)]
    return ""


def _ig_alloc_name(task, idx=0, avoid=(), live=True):
    """বট যে Username দেবে — দেওয়ার *আগে* চেক: এই টাস্কে জমা নেই + Instagram-এ অ্যাকাউন্ট নেই।

    ⚡ আগে প্রতি নামে একটা করে লাইভ Instagram চেক হতো (৬s টাইমাউট) — Start চাপলে
    ২৫টা পর্যন্ত সিরিয়াল রিকোয়েস্টে বট আটকে যেত। এখন চেকগুলো সমান্তরালে (৪টা)।
    """
    _skip = {_ig_clean_user(x) for x in (avoid or ()) if x}
    lst = _ig_name_list(task)
    _mode = (task.get("username_mode") or "").lower()
    tries = 25 if _mode in ("auto", "random") else max(1, min(len(lst) or 1, 25))
    base = int(idx or 0)
    cands = []
    for k in range(tries):
        name = _ig_clean_user(_ig_pick(task, base + k))
        if not name or name in _skip or name in cands or not _ig_username_ok(name):
            continue
        try:
            if _ig_username_exists(int(task["id"]), name):
                continue
        except Exception:
            pass
        cands.append(name)
        if len(cands) >= 4:
            break
    if not cands:
        return ""
    if not live:
        # ⚡ Start আটকাবে না — Instagram চেক পরে ব্যাকগ্রাউন্ডে (_ig_bg_verify)
        return cands[0]
    try:
        from concurrent.futures import ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=min(4, len(cands))) as _ex:
            _res = list(_ex.map(_ig_live_free, cands))
        for name, avail in zip(cands, _res):
            if avail is not False:      # True = ফাঁকা, None = চেক করা গেল না
                return name
    except Exception as _e:
        log.debug(f"[IG-TASK] availability parallel ব্যর্থ: {_e}")
    return cands[0]


def _ig_login(task, idx=0, pw=None):
    """লগইন তথ্য — Username (অ্যাডমিনের লিস্ট) + পাসওয়ার্ড (গ্রুপ / অ্যাডমিন সেট)।"""
    pw = (pw or task.get("password") or "").strip()
    return {
        "username": _ig_pick(task, idx),
        "password": pw or _fb_new_password(),
    }


def _ig_can_start(task, uid):
    """(ok, কারণ) — max accounts / per-user limit / active"""
    if not task or not task.get("is_active"):
        return False, "off"
    total, mine = _ig_counts_c(int(task["id"]), uid)
    mx = int(task.get("max_accounts") or 0)
    if mx > 0 and total >= mx:
        return False, "full"
    lim = _limit_val(task.get("per_user_limit"), 1)
    if lim > 0 and mine >= lim:
        return False, "limit"
    now_ts = _time.time()
    for k in [k for k, v in list(_IG_STATE.items()) if now_ts - v.get("ts", 0) > 3600]:
        _IG_STATE.pop(k, None)
    return True, ""


# ─────────────────────── Google Sheet / CSV ───────────────────────
def _ig_columns(task):
    cols = _ig_json((task or {}).get("sheet_columns"), [])
    cols = [str(c) for c in cols if str(c).strip()]
    return cols or ["sl", "date", "username", "pass", "2fa", "user_id", "tg_username"]


def _ig_col_label(tok):
    tok = str(tok).strip()
    if tok.startswith("f:"):
        return tok[2:]
    return _IG_COL_LABELS.get(_IG_COL_ALIAS.get(tok.lower(), tok), tok)


def _ig_col_value(tok, sub, idx=0, task=None):
    tok = str(tok).strip()
    data = _ig_json(sub.get("data"), {})
    if tok.startswith("f:"):
        return data.get(tok[2:], "")
    tok = _IG_COL_ALIAS.get(tok.lower(), tok)
    if tok in ("2fa", "cookies"):        # যে ফিল্ডে এই টাইপ, তার উত্তর
        if tok == "2fa":
            return (_data_any(data, _ig_data_key(task, "2fa"), "2fa", "totp", "2step")
                    or _data_fuzzy(data, "2fa", "totp", "2step", "auth"))
        return (_data_any(data, _ig_data_key(task, "cookies"), "cookies", "coki", "ck")
                or _data_fuzzy(data, "cookie", "coki"))
    if tok == "sl":
        return idx
    if tok == "date":
        return sub.get("created_at", "")
    if tok == "user_id":
        return sub.get("user_id", "")
    if tok == "tg_username":
        return sub.get("username", "")
    if tok == "task":
        return (task or {}).get("name", "")
    if tok == "account_no":
        return sub.get("account_no", "")
    if tok == "status":
        return sub.get("status", "")
    if tok == "username":                 # ডেটাবেসে ig_username নামে থাকে
        return (sub.get("ig_username", "") or data.get("username", "")
                or data.get(_ig_data_key(task, "iguser"), ""))
    if tok == "password":                 # অ্যাডমিনের সেট করা পাসওয়ার্ড
        _v = sub.get("ig_password", "") or ""
        if str(_v).strip():
            return _v
        _v = _data_any(data, "password", "pass", "pwd") or _data_fuzzy(data, "pass", "pwd")
        if str(_v or "").strip():
            return _v
        return sub.get("login_password", "")
    if tok == "login_username":
        return sub.get("login_username", "")
    if tok == "login_password":
        return sub.get("login_password", "")
    _v = _data_any(data, tok, tok.lower())
    if str(_v or "").strip():
        return _v
    _v = _data_fuzzy(data, tok.lower())
    if str(_v or "").strip():
        return _v
    return sub.get(tok, "") or ""


def _ig_subs(tid, limit=5000, only_unsynced=False):
    q = ("SELECT s.*, COALESCE(u.username,'') AS username FROM ig_submissions s "
         "LEFT JOIN users u ON u.user_id=s.user_id WHERE s.task_id=%s")
    if only_unsynced:
        q += " AND COALESCE(s.synced,0)=0"
    q += " ORDER BY s.id ASC"
    if limit:
        q += f" LIMIT {int(limit)}"
    try:
        with _c() as c:
            rows = c.execute(q, (tid,)).fetchall()
        return [dict(r) for r in rows]
    except Exception as e:
        log.warning(f"[IG-TASK] subs ব্যর্থ: {e}")
        return []


def _ig_csv_bytes(task):
    """CSV (Excel/Google Sheets-এ সোজা খোলে), ম্যাপিং অনুযায়ী কলাম সাজানো।"""
    import csv, io
    cols = _ig_columns(task)
    subs = _ig_subs(int(task["id"]))
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow([_ig_col_label(c) for c in cols])
    for i, s in enumerate(subs, 1):
        w.writerow([_ig_col_value(c, s, i, task) for c in cols])
    data = ("\ufeff" + buf.getvalue()).encode("utf-8")
    safe = re.sub(r"[^A-Za-z0-9_-]+", "_", str(task.get("name") or f"task{task['id']}"))[:40]
    return data, f"ig_{safe}_{datetime.now(BD_TZ).strftime('%Y%m%d_%H%M')}.csv"


def _ig_push_row(sub, task):
    """Apps Script Web App-এ এক সারি পাঠাও। সফল হলে synced=1।"""
    url = _sheet_url_for(task)
    if not url:
        return False
    cols = _ig_columns(task)
    _pwd_on = (task.get("password_last_change") or "").strip()[:10]   # YYYY-MM-DD
    _task_name = task.get("name", "") or ""
    payload = {
        "task": _task_name,
        "task_id": task.get("id"),
        # পাসওয়ার্ড বদলের তারিখসহ আলাদা ট্যাব — নতুন তারিখ মানে নতুন শিট
        "sheet": (f"{_task_name} {_pwd_on}".strip() if _pwd_on else _task_name),
        "password_date": _pwd_on,
        "columns": [_ig_col_label(c) for c in cols],
        "row": [_ig_col_value(c, sub, 0, task) for c in cols],
    }
    try:
        req = urllib.request.Request(
            url, data=_json.dumps(payload).encode("utf-8"),
            headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=12) as resp:
            ok = 200 <= int(getattr(resp, "status", 0) or 0) < 300
    except Exception as e:
        log.warning(f"[IG-SHEET] sub={sub.get('id')} push ব্যর্থ: {e}")
        return False
    if not ok:
        return False
    try:
        with _c() as c:
            c.execute("UPDATE ig_submissions SET synced=1 WHERE id=%s", (sub.get("id"),))
    except Exception:
        pass
    return True


def ig_sync_pending(limit=40):
    """যেসব সারি এখনো Sheet-এ যায়নি — পাঠাও (job চালায়)।"""
    _ig_init()
    for task in _ig_active_tasks():
        if not _sheet_url_for(task):
            continue
        for sub in _ig_subs(int(task["id"]), limit=limit, only_unsynced=True):
            if not _ig_push_row(sub, task):
                break
    return True


def _ig_submit(task, uid, login, answers):
    """জমা সেভ করো — ডুপ্লিকেট Username হলে ('dup', None); না হলে (sub_row, None)।"""
    tid = int(task["id"])
    name = _ig_clean_user(login.get("username") or answers.get("username")
                          or answers.get(_ig_data_key(task, "iguser")) or "")
    if not name:
        return None, "nofield"
    _pri = _ig_uid_prior(tid, name)
    if _pri["approved"]:
        return None, "paid"
    if _pri["rejected"]:
        return None, "rej"
    if _ig_username_exists(tid, name, login.get("password", "")):
        return None, "dup"
    _t, mine = _ig_counts(tid, uid)
    row_id = None
    _review_init()
    try:
        with _c() as c:
            cur = c.execute(
                "INSERT INTO ig_submissions (task_id, user_id, account_no, ig_username, "
                "ig_password, login_username, login_password, data, status, "
                "synced, created_at, paid, notified) "
                "VALUES (%s,%s,%s,%s,%s,%s,%s,%s,'pending',0,%s,0,1) "
                "RETURNING id",
                (tid, uid, mine + 1, name, login.get("password", ""),
                 login.get("username", "") or name, login.get("password", ""),
                 _json.dumps(answers, ensure_ascii=False), now()))
            row_id = cur.lastrowid
            c.execute("UPDATE ig_tasks SET total_done=COALESCE(total_done,0)+1 WHERE id=%s",
                      (tid,))
            # টাকা এখন approve-এর সময়ে যোগ হয় (প্যানেলে Username approve করলে)
    except Exception as e:
        msg = str(e).lower()
        if "unique" in msg or "duplicate" in msg:
            return None, "dup"
        log.warning(f"[IG-TASK] submit ব্যর্থ uid={uid} task={tid}: {e}")
        return None, "err"
    sub = dict(answers)
    sub.update({"id": row_id, "task_id": tid, "user_id": uid, "ig_username": name,
                "ig_password": login.get("password", ""),
                "login_username": login.get("username", "") or name,
                "login_password": login.get("password", ""),
                "data": _json.dumps(answers, ensure_ascii=False), "created_at": now(),
                "account_no": mine + 1, "username": ""})
    if _sheet_url_for(task):
        threading.Thread(target=_ig_push_row, args=(sub, task), daemon=True).start()
    return sub, None


# ─────────────────────── ইউজার ফ্লো (UI) ───────────────────────
def _ig_cred_card(task, login, fields, lang, step=0):
    """ছবির মতো কার্ড — Username + Password, তারপর অ্যাডমিন-সেট করা প্রশ্ন (ক্রম অনুযায়ী)।"""
    cred = (f"👤 Username: `{login.get('username') or '-'}`\n"
            f"🔒 Password: `{login.get('password')}`")
    hint = ("\n\nউপরের ইউজারনেম ও পাসওয়ার্ড দিয়ে Instagram-এ নতুন অ্যাকাউন্ট খুলুন, "
            "তারপর নিচের প্রশ্নের উত্তর দিন।" if lang != "en" else
            "\n\nOpen a new Instagram account with the username and password above, "
            "then answer the question below.")
    ask = _ig_ask_text(fields, int(step or 0), lang)
    return (f"📸 *{task.get('name') or 'Instagram Task'}*\n\n{cred}{hint}\n\n{ask}").strip()


def _ig_card_kb(tid, lang, done=False, uid=0):
    """কার্ডের নিচের বাটন — ১ বার Username বদলানো (+.question না থাকলে 'শেষ' বাটন) + বাতিল।"""
    rows = [[InlineKeyboardButton(
        "🔄 Username পরিবর্তন (১ বার)" if lang != "en" else "🔄 Change username (1 time)",
        callback_data=f"igu:{int(tid)}")]]
    if done:
        rows.append([InlineKeyboardButton(
            "✅ অ্যাকাউন্ট খোলা শেষ" if lang != "en" else "✅ Account created",
            callback_data=f"igd:{int(tid)}")])
    rows.append([InlineKeyboardButton("❌ Cancel", callback_data="igt_cancel")])
    return _rk_markup(uid, rows) if uid else _ig_kb(rows)


def _ig_kb(rows):
    return InlineKeyboardMarkup(rows)


def _ig_ask_text(fields, i, lang):
    """প্রশ্ন + ক্রম (১/৩) — কোনটা আগে/পরে সেটা টাস্কের ফিল্ড-ক্রম অনুযায়ী।"""
    if not fields or i >= len(fields):
        return ""
    f = fields[i]
    q = f.get("label_bn") if lang != "en" else (f.get("label_en") or f.get("label_bn"))
    return f"{i + 1}/{len(fields)}  {q}"


async def ig_show_list(q, uid, lang=None):
    """📸 Instagram Tasks — সব active task এক লিস্টে।"""
    if lang is None:
        lang = await asyncio.to_thread(get_lang, uid)
    tasks = await asyncio.to_thread(_ig_active_tasks_c)
    if not tasks:
        await q.message.reply_text(
            "❌ এখন কোনো Instagram Task নেই।" if lang != "en"
            else "❌ No Instagram task available right now.")
        return
    rows = []
    _cmap = await asyncio.to_thread(_ig_counts_map_c, [int(x["id"]) for x in tasks], uid)
    for t in tasks:
        tid = int(t["id"])
        total, mine = _cmap.get(tid, (0, 0))
        mx = int(t.get("max_accounts") or 0)
        _lim = _limit_val(t.get("per_user_limit"), 1)
        why = ("full" if (mx > 0 and total >= mx) else
               ("limit" if (_lim > 0 and mine >= _lim) else ""))
        ok = not why
        left = (mx - total) if mx > 0 else 0
        tag = "✅ Done" if why in ("limit",) else ("⛔ Full" if why == "full" else "")
        price = float(t.get("price") or 0)
        bits = [f"📸 {t.get('name') or 'Instagram Task'}"]
        if price > 0:
            bits.append(f"${price}")
        if mx > 0:
            bits.append(f"{max(0, left)} left")
        if tag:
            bits.append(tag)
        rows.append([InlineKeyboardButton("  •  ".join(bits), callback_data=f"igtn:{tid}")])
    rows.append([InlineKeyboardButton(
        "✖️ বাতিল" if lang != "en" else "✖️ Cancel", callback_data="task_cancel")])
    await _task_reply_ui(
        q, uid,
        ("📸 *Instagram Tasks*\n\nএকটি টাস্ক বেছে নিন:" if lang != "en"
         else "📸 *Instagram Tasks*\n\nChoose a task:"),
        rows, parse_mode="Markdown", lang=lang)


async def ig_task_rules(q, uid, tid):
    """টাস্কে চাপ → সোজা Rules + Start + Video (মাঝের নাম-ধাপটা বাদ)।"""
    lang, task = await asyncio.gather(
        asyncio.to_thread(get_lang, uid), asyncio.to_thread(_ig_task, tid))
    if not task:
        await q.answer("❌ Task পাওয়া যায়নি")
        return
    rules = (task.get("rules_bn") if lang != "en" else (task.get("rules_en") or task.get("rules_bn"))) or ""
    if not rules.strip():
        rules = ("• সঠিক তথ্য দিন, ভুল হলে রিজেক্ট হবে।" if lang != "en"
                 else "• Submit correct information, wrong data will be rejected.")
    ok, why = await asyncio.to_thread(_ig_can_start, task, uid)
    parts = [f"📸 {task.get('name') or 'Instagram Task'}", "", "📋 Rules", "", rules.strip()]
    price = float(task.get("price") or 0)
    if price > 0:
        parts += ["", f"💵 ${price}"]
    if why == "full":
        parts += ["", "⛔ এই টাস্কের সব স্লট শেষ।" if lang != "en" else "⛔ All slots are full."]
    elif why == "limit":
        parts += ["", "✅ আপনি এই টাস্কের সর্বোচ্চ সংখ্যক অ্যাকাউন্ট জমা দিয়েছেন।" if lang != "en"
                  else "✅ You already submitted the maximum accounts."]
    rows = []
    if ok:
        rows.append([InlineKeyboardButton("▶️ Start", callback_data=f"igts:{tid}")])
    _vid = _task_video_row(task, lang, "ig")
    if _vid:
        rows.append(_vid)
    rows.append([InlineKeyboardButton("❌ বাতিল" if lang != "en" else "❌ Cancel",
                                      callback_data="task_cancel")])
    await _task_reply_ui(q, uid, "\n".join(parts), rows, lang=lang)
    await _autosend_task_video(q.message, task, lang, "ig")


async def ig_task_start(q, uid, tid):
    """Start → বট Username+Password দেয় (ছবির মতো)। Instagram চেক ব্যাকগ্রাউন্ডে।"""
    try:
        await q.answer()          # স্পিনার সাথে সাথে বন্ধ (শিমে no-op)
    except Exception:
        pass
    lang, task = await asyncio.gather(
        asyncio.to_thread(get_lang, uid), asyncio.to_thread(_ig_task, tid))
    if await _task_cool_blocked(q, uid):
        return
    if not task:
        await q.answer("❌ Task পাওয়া যায়নি")
        return
    ok, why = await asyncio.to_thread(_ig_can_start, task, uid)
    if not ok:
        msg = {
            "full": "⛔ সব স্লট শেষ হয়ে গেছে।" if lang != "en" else "⛔ All slots are taken.",
            "limit": "✅ আপনি ইতিমধ্যে সর্বোচ্চ অ্যাকাউন্ট জমা দিয়েছেন।" if lang != "en"
                     else "✅ You already submitted the maximum accounts.",
        }.get(why, "❌ এখন কাজ করা যাবে না।" if lang != "en" else "❌ Not available now.")
        await q.answer(msg, show_alert=True)
        return
    _done = (await asyncio.to_thread(_ig_counts_c, int(task["id"]), uid))[0]
    name = await asyncio.to_thread(_ig_alloc_name, task, _done, (), False)
    if not name:
        await q.answer(
            "❌ এখন কোনো ফ্রি Username পাওয়া যাচ্ছে না — অ্যাডমিনকে জানান।" if lang != "en"
            else "❌ No free username right now — please tell the admin.", show_alert=True)
        return
    _gpw, _gid = await asyncio.to_thread(_pw_group_pick, int(task["id"]), uid, "ig")
    if _gid == "full":
        await q.answer("⛔ সব পাসওয়ার্ডের সিট শেষ — অ্যাডমিনকে জানান।" if lang != "en"
                       else "⛔ All password slots are full — please tell the admin.",
                       show_alert=True)
        return
    login = await asyncio.to_thread(_ig_login, task, _done, _gpw)
    login["username"] = name
    fields = await asyncio.to_thread(_ig_fields, task)
    _IG_STATE[uid] = {"task_id": int(tid), "step": 0, "answers": {}, "login": login,
                      "retry": 0, "ts": _time.time()}
    _sess_begin(uid, "ig", tid)     # ১৫ মিনিটের কাউন্টডাউন শুরু
    _chk_m = await q.message.reply_text(
        "🔍 Username চেক করা হচ্ছে… ওয়েট করুন" if lang != "en"
        else "🔍 Checking username… please wait")
    _sess_track(uid, _chk_m)
    _cred_m = await q.message.reply_text(_ig_cred_card(task, login, fields, lang),
                                         parse_mode="Markdown",
                                         reply_markup=_ig_card_kb(int(tid), lang, done=not fields, uid=uid))
    _sess_track(uid, _cred_m)
    _IG_STATE[uid]["cred_msg"] = _cred_m
    # Start আর আটকাবে না — Instagram চেক এখন ব্যাকগ্রাউন্ডে
    asyncio.create_task(_ig_bg_verify(uid, int(tid), name, _cred_m, _chk_m, lang))


async def _ig_bg_verify(uid, tid, name, card_msg, chk_msg, lang):
    """কার্ড দেওয়ার পরে ব্যাকগ্রাউন্ডে Instagram-এ নামটা ফাঁকা কি না।

    ⚡ আগে Start-এর ভিতরেই চেক হতো (৬s টাইমআউট × একাধিক নাম) — বাটন চাপলে
    বট আটকে থাকত। এখন কার্ড সাথে সাথে আসে; নাম নেওয়া থাকলে চুপচাপ নতুন
    Username সহ নতুন কার্ড পাঠানো হয়।
    """
    try:
        avail = await asyncio.to_thread(_ig_live_free, name)
    except Exception:
        avail = None
    if avail is not False:
        try:
            await chk_msg.delete()
        except Exception:
            pass
        return
    try:
        task = await asyncio.to_thread(_ig_task, tid)
        st = _IG_STATE.get(uid) or {}
        if (not task or st.get("task_id") != int(tid)
                or (st.get("login") or {}).get("username") != name):
            return                       # ইউজার এর মধ্যে বদল/ক্যান্সেল করেছে
        _done = (await asyncio.to_thread(_ig_counts_c, int(task["id"]), uid))[0]
        new = await asyncio.to_thread(_ig_alloc_name, task, _done, (name,), False)
        if not new:
            return
        st["login"] = dict(st.get("login") or {}, username=new)
        fields = await asyncio.to_thread(_ig_fields, task)
        for _m in (card_msg, chk_msg):
            try:
                await _m.delete()
            except Exception:
                pass
        _bot = card_msg.get_bot()
        _new = await _bot.send_message(
            card_msg.chat_id, _ig_cred_card(task, st["login"], fields, lang),
            parse_mode="Markdown",
            reply_markup=_ig_card_kb(int(task["id"]), lang,
                                     done=not fields, uid=uid))
        _sess_track(uid, _new)
        st["cred_msg"] = _new
        await _bot.send_message(
            card_msg.chat_id,
            ("⚠️ আগের Username আগেই নেওয়া ছিল — নতুন Username দেওয়া হলো।" if lang != "en"
             else "⚠️ That username was already taken — a new one is shown above."))
    except Exception as _e:
        log.debug(f"[IG-BG] নাম চেক ব্যর্থ: {_e}")


async def _ig_finish(reply, uid, task, st, lang):
    """সব প্রশ্ন শেষ → জমা সেভ করে রিসিপ্ট পাঠাও। `reply` = reply_text-এর মতো async কলেবল।"""
    sub, err = await asyncio.to_thread(_ig_submit, task, uid, st["login"], st["answers"])
    _IG_STATE.pop(uid, None)
    if err in ("paid", "rej"):
        await reply(
            ("🚫 এই Username আগেই approve হয়ে পেমেন্ট হয়েছে — আবার জমা নেওয়া হলো না।"
             if err == "paid" else
             "🚫 এই Username আগে reject হয়েছে — আবার জমা নেওয়া হলো না।") if lang != "en"
            else ("🚫 Already approved & paid — not accepted again." if err == "paid"
                  else "🚫 Rejected earlier — not accepted again."),
            reply_markup=_rk_markup(uid, [[InlineKeyboardButton(
                "▶️ Start", callback_data="igt_list")]]))
        return
    if err == "dup":
        await reply(
            ("⚠️ এই Username আগেই জমা হয়েছে — অ্যাকাউন্ট সেভ হয়নি।\n"
             "আবার Start চাপলে নতুন Username পাবেন।" if lang != "en" else
             "⚠️ Duplicate username — not saved.\nStart again to get a new username."),
            parse_mode="Markdown",
            reply_markup=_rk_markup(uid, [[InlineKeyboardButton(
                "▶️ Start", callback_data="igt_list")]]))
        return
    if err:
        await reply("❌ সেভ করা যায়নি, আবার চেষ্টা করুন।" if lang != "en"
                    else "❌ Could not save, please try again.")
        return
    price = float(task.get("price") or 0)
    _p_bn = f"\n⏳ Approve হলে +${price} যোগ হবে" if price > 0 else ""
    _p_en = f"\n⏳ +${price} will be added after approval" if price > 0 else ""
    name = (sub.get("ig_username") if sub else "") or (st.get("login") or {}).get("username") or ""
    _ok_msg = await reply(
        ("✅ *অ্যাকাউন্ট খোলা শেষ — জমা হয়েছে!*\n\n"
         f"📸 Task: {task.get('name')}\n👤 Username: `{name}`{_p_bn}\n\n"
         "অ্যাডমিন যাচাই করে দেখবেন।") if lang != "en" else
        ("✅ *Account done — submitted!*\n\n"
         f"📸 Task: {task.get('name')}\n👤 Username: `{name}`{_p_en}\n\n"
         "Admin will review it."),
        parse_mode="Markdown",
        reply_markup=_rk_markup(uid, [[InlineKeyboardButton(
            "◀️ Tasks", callback_data="igt_list")]]))
    # ── জমা হয়ে গেছে → বটের দেওয়া Username/Password ও ইউজারের তথ্য ডিলিট,
    #    শুধু এই রিসিপ্টটা থাকবে ──
    await _sess_purge(uid, _sess_bot(_ok_msg), keep=_ok_msg)


async def ig_done(q, uid):
    """✅ অ্যাকাউন্ট খোলা শেষ — প্রশ্ন না থাকলে ইউজার নিজেই এই বাটনে চাপে।"""
    lang = await asyncio.to_thread(get_lang, uid)
    st = _IG_STATE.get(uid)
    if not st:
        await q.answer("❌ ফ্লো বন্ধ" if lang != "en" else "❌ No active flow")
        return
    task = await asyncio.to_thread(_ig_task, st["task_id"])
    if not task:
        await q.answer("❌ Task পাওয়া যায়নি")
        return
    fields = await asyncio.to_thread(_ig_fields, task)
    if fields and int(st.get("step") or 0) < len(fields):
        await q.answer("❗ আগে সব প্রশ্নের উত্তর দিন" if lang != "en"
                       else "❗ Please answer the questions first", show_alert=True)
        return
    st["ts"] = _time.time()
    await _ig_finish(q.message.reply_text, uid, task, st, lang)


async def ig_on_text(update, ctx):
    """ইউজারের উত্তর নাও — এক ফিল্ড করে (Username/Password বট আগেই দিয়ে দিয়েছে)।"""
    uid = update.effective_user.id
    st = _IG_STATE.get(uid)
    if not st:
        return
    txt = (update.message.text or "").strip()
    # নিচের Reply Keyboard-এর বাটন → উত্তর নয়, on_message হ্যান্ডেল করবে
    # Reply Keyboard-এর বাটন (✅ জমা দিন / 🔄 Username পরিবর্তন / 🔁 নতুন কোড …)
    # → উত্তর নয়; আসল callback ফ্লোতে রাউট করি
    if await _task_kb_dispatch(txt, update.effective_user, update.message, ctx):
        return
    if txt in ("❌ বাতিল", "❌ Cancel", "❌ বাতিল করুন"):
        return
    _sess_track(uid, update.message)   # ইউজার যা পাঠাল — শেষে ডিলিট হবে
    task = await asyncio.to_thread(_ig_task, st["task_id"])
    if not task:
        _IG_STATE.pop(uid, None)
        return
    lang = await asyncio.to_thread(get_lang, uid)
    fields = await asyncio.to_thread(_ig_fields, task)
    if st["step"] >= len(fields):
        _IG_STATE.pop(uid, None)
        return
    f = fields[st["step"]]
    if not txt:
        await update.message.reply_text(
            "❗ ফাঁকা পাঠাবেন না।" if lang != "en" else "❗ Please don't send empty.")
        return
    # ── ফিল্ড-টাইপ অনুযায়ী যাচাই (Username ফরম্যাট, 2FA key, cookies…) ──
    _ok, _err_bn, _err_en, _extra = _ig_validate(f, txt)
    if not _ok:
        await update.message.reply_text(_err_bn if lang != "en" else _err_en,
                                        parse_mode="Markdown",
                                        reply_markup=_ig_cancel_kb(lang, uid))
        return
    st["answers"][f["key"]] = txt
    st["ts"] = _time.time()
    # ── 2FA: key ঠিক থাকলে বট কোড দেবে ──
    if _extra:
        _2fa_m = await update.message.reply_text(
            (f"🔑 আপনার 2FA কোড: `{_extra}`\n⏱ ৩০ সেকেন্ড পর বদলে যাবে — এখনই Instagram-এ দিন।"
             if lang != "en" else
             f"🔑 Your 2FA code: `{_extra}`\n⏱ It changes every 30 seconds — enter it now."),
            parse_mode="Markdown",
            reply_markup=_rk_markup(uid, [
                [InlineKeyboardButton("🔁 নতুন কোড" if lang != "en" else "🔁 New code",
                                      callback_data=f"igc:{st['task_id']}")],
                [InlineKeyboardButton("❌ বাতিল" if lang != "en" else "❌ Cancel",
                                      callback_data="igt_cancel")]]))
        _sess_track(uid, _2fa_m)
    st["step"] += 1
    st["ts"] = _time.time()
    if st["step"] < len(fields):
        _q_m = await update.message.reply_text(_ig_ask_text(fields, st["step"], lang),
                                               reply_markup=_ig_cancel_kb(lang, uid))
        _sess_track(uid, _q_m)
        return
    # সব উত্তর পাওয়া গেছে → সারসংক্ষেপ + "অ্যাকাউন্ট খোলা শেষ / জমা দিন" বাটন
    _sum_m = await update.message.reply_text(
        _ig_summary(task, st, lang),
        reply_markup=_rk_markup(uid, [
            [InlineKeyboardButton("✅ অ্যাকাউন্ট খোলা শেষ — জমা দিন" if lang != "en"
                                  else "✅ Account created — submit",
                                  callback_data=f"igd:{st['task_id']}")],
            [InlineKeyboardButton("❌ বাতিল" if lang != "en" else "❌ Cancel",
                                  callback_data="igt_cancel")],
        ]))
    _sess_track(uid, _sum_m)


def _ig_cancel_kb(lang, uid=0):
    _rows = []
    if uid:
        try:
            _st = _IG_STATE.get(int(uid)) or {}
            _t = _ig_task(_st.get("task_id") or 0) or {}
            _v = _task_video_row(_t, lang)
            if _v:
                _rows.append(_v)
        except Exception:
            pass
    _rows.append([InlineKeyboardButton(
        "❌ বাতিল" if lang != "en" else "❌ Cancel", callback_data="igt_cancel")])
    return _rk_markup(uid, _rows) if uid else _ig_kb(_rows)


def _ig_summary(task, st, lang):
    lines = [f"📸 {task.get('name') or 'Instagram Task'}", "",
             "📝 আপনার দেওয়া তথ্য:" if lang != "en" else "📝 Your answers:", ""]
    for k, v in (st.get("answers") or {}).items():
        val = str(v)
        if len(val) > 80:
            val = val[:80] + "…"
        lines.append(f"• {k}: {val}")
    lines += ["", "সব ঠিক থাকলে “✅ অ্যাকাউন্ট খোলা শেষ” চাপুন।" if lang != "en"
              else "If everything is correct, press “✅ Account created”."]
    return "\n".join(lines)


async def ig_send_2fa(q, uid, tid):
    """ইউজারের দেওয়া 2FA key থেকে নতুন কোড।"""
    lang = await asyncio.to_thread(get_lang, uid)
    st = _IG_STATE.get(uid) or {}
    task = await asyncio.to_thread(_ig_task, tid)
    if not task:
        await q.answer("❌ Task পাওয়া যায়নি")
        return
    key = ""
    for f in await asyncio.to_thread(_ig_fields, task):
        if (f.get("type") or "") == "2fa":
            key = (st.get("answers") or {}).get(f["key"], "")
            break
    if not key:
        await q.answer("❌ আগে 2FA key দিন" if lang != "en" else "❌ Send your 2FA key first")
        return
    try:
        code = _fb_totp(key)
    except Exception:
        await q.answer("❌ Key থেকে কোড হলো না" if lang != "en" else "❌ Bad 2FA key")
        return
    _n2fa_m = await q.message.reply_text(
        (f"🔑 নতুন 2FA কোড: `{code}`\n⏱ ৩০ সেকেন্ড পর বদলে যাবে।" if lang != "en"
         else f"🔑 New 2FA code: `{code}`\n⏱ It changes every 30 seconds."),
        parse_mode="Markdown",
        reply_markup=_rk_markup(uid, [
            [InlineKeyboardButton("🔁 নতুন কোড" if lang != "en" else "🔁 New code",
                                  callback_data=f"igc:{tid}")],
            [InlineKeyboardButton("❌ বাতিল" if lang != "en" else "❌ Cancel",
                                  callback_data="igt_cancel")]]))
    _sess_track(uid, _n2fa_m)


async def ig_retry(q, uid):
    """🔄 বাটন — আরেকটা ফ্রি Username দাও (মাত্র ১ বার), আগেরটা বাতিল।"""
    lang = await asyncio.to_thread(get_lang, uid)
    st = _IG_STATE.get(uid)
    if not st:
        await q.answer("❌ ফ্লো বন্ধ" if lang != "en" else "❌ No active flow")
        return
    if int(st.get("retry") or 0) >= 1:
        await q.answer("⛔ বদলানোর সুযোগ শেষ" if lang != "en" else "⛔ No changes left",
                       show_alert=True)
        return
    task = await asyncio.to_thread(_ig_task, st["task_id"])
    if not task:
        await q.answer("❌ Task পাওয়া যায়নি")
        return
    old = (st.get("login") or {}).get("username") or ""
    _done = (await asyncio.to_thread(_ig_counts_c, int(task["id"]), uid))[0]
    new = await asyncio.to_thread(_ig_alloc_name, task, _done + 1, (old,), False)
    if not new:
        await q.answer("❌ এখন নতুন ফ্রি Username নেই — অ্যাডমিনকে জানান।" if lang != "en"
                       else "❌ No new free username — tell the admin.", show_alert=True)
        return
    st["retry"] = int(st.get("retry") or 0) + 1
    st.setdefault("login", {})["username"] = new
    st["ts"] = _time.time()
    fields = await asyncio.to_thread(_ig_fields, task)
    # আগের (পুরোনো Username-এর) কার্ডটা মুছে দিই — নতুনটাই থাকবে
    _old = st.pop("cred_msg", None)
    if _old is not None:
        try:
            await _old.delete()
        except Exception as _de:
            log.debug(f"[IG-TASK] পুরোনো কার্ড ডিলিট ব্যর্থ: {_de}")
    _rt_m = await q.message.reply_text(
        _ig_cred_card(task, st["login"], fields, lang, step=st.get("step") or 0),
        parse_mode="Markdown",
        reply_markup=_ig_card_kb(int(task["id"]), lang, done=not fields, uid=uid))
    _sess_track(uid, _rt_m)
    st["cred_msg"] = _rt_m


async def ig_cancel(q, uid):
    _IG_STATE.pop(uid, None)
    _TASK_REPLY_KB.pop(int(uid), None)
    try:
        await _sess_purge(uid, _sess_bot(getattr(q, "message", None)))
    except Exception:
        pass
    lang = await asyncio.to_thread(get_lang, uid)
    await q.answer("✅ বাতিল হয়েছে" if lang != "en" else "✅ Cancelled")


# ─────────────────────── অটো কাজ (jobs) ───────────────────────
async def job_ig_sheet_sync(ctx):
    try:
        await asyncio.to_thread(ig_sync_pending)
    except Exception as e:
        log.debug(f"[IG-SHEET] job: {e}")


async def job_ig_password_rotate(ctx):
    """প্রতিদিন নির্দিষ্ট সময়ে পাসওয়ার্ড বদল।"""
    try:
        now_bd = datetime.now(BD_TZ)
        hhmm = now_bd.strftime("%H:%M")
        today = now_bd.strftime("%Y-%m-%d")
        for t in await asyncio.to_thread(_ig_active_tasks_j):
            if not int(t.get("password_auto") or 0):
                continue
            if (t.get("password_change_time") or "").strip() != hhmm:
                continue
            if str(t.get("password_last_change") or "").startswith(today):
                continue
            new_pw = _fb_new_password()
            try:
                with _c() as c:
                    c.execute("UPDATE ig_tasks SET password=%s, password_last_change=%s "
                              "WHERE id=%s", (new_pw, now_bd.strftime("%Y-%m-%d %H:%M"), t["id"]))
            except Exception as e:
                log.warning(f"[IG-PW] task {t.get('id')} ব্যর্থ: {e}")
                continue
            # ── pending জমাগুলোর পাসওয়ার্ডও নতুন + synced=0 → শিটে নতুন সারি যাবে ──
            try:
                with _c() as c:
                    c.execute("UPDATE ig_submissions SET ig_password=%s, synced=0 "
                              "WHERE task_id=%s AND status='pending'", (new_pw, t["id"]))
            except Exception as e:
                log.warning(f"[IG-PW] subs sync ব্যর্থ task {t.get('id')}: {e}")
            try:
                await ctx.bot.send_message(
                    ADMIN_ID,
                    f"🔑 *পাসওয়ার্ড অটো বদল হয়েছে*\n\n📸 {t.get('name')}\n"
                    f"নতুন Password: `{new_pw}`", parse_mode="Markdown")
            except Exception:
                pass
    except Exception as e:
        log.debug(f"[IG-PW] job: {e}")


async def job_ig_export(ctx):
    """নির্ধারিত সময়ে প্রতি টাস্কের আলাদা CSV অ্যাডমিনকে।"""
    try:
        now_bd = datetime.now(BD_TZ)
        hhmm = now_bd.strftime("%H:%M")
        today = now_bd.strftime("%Y-%m-%d")
        for t in await asyncio.to_thread(_ig_active_tasks_j):
            if (t.get("export_time") or "").strip() != hhmm:
                continue
            if str(t.get("last_export_at") or "").startswith(today):
                continue
            data, fname = await asyncio.to_thread(_ig_csv_bytes, t)
            try:
                await ctx.bot.send_document(
                    ADMIN_ID, document=data, filename=fname,
                    caption=f"📊 {t.get('name')} — Google Sheet (CSV)")
                with _c() as c:
                    c.execute("UPDATE ig_tasks SET last_export_at=%s WHERE id=%s",
                              (now_bd.strftime("%Y-%m-%d %H:%M"), t["id"]))
            except Exception as e:
                log.warning(f"[IG-EXPORT] task {t.get('id')}: {e}")
    except Exception as e:
        log.debug(f"[IG-EXPORT] job: {e}")


# ─────────────────────── অ্যাডমিন (বট) কুইক ভিউ ───────────────────────
async def adm_ig_list(q, uid, ctx=None):
    tasks = await asyncio.to_thread(_ig_active_tasks)
    if not tasks:
        await q.message.reply_text("📸 কোনো Instagram Task নেই — ওয়েব প্যানেলে যোগ করুন।")
        return
    lines = ["📸 *Instagram Tasks*"]
    rows = []
    for t in tasks:
        total, _m = await asyncio.to_thread(_ig_counts, int(t["id"]), None)
        mx = int(t.get("max_accounts") or 0)
        lines.append(f"• *{t.get('name')}* — {total}/{mx or '∞'}"
                     + ("  🔑 auto" if int(t.get("password_auto") or 0) else ""))
        _nm = str(t.get('name') or '')[:20]
        rows.append([
            InlineKeyboardButton(f"⬇️ {_nm} (CSV)", callback_data=f"igx:{t['id']}"),
            InlineKeyboardButton("📢 নোটিফাই", callback_data=f"ignt:{t['id']}"),
            InlineKeyboardButton("📽 ভিডিও", callback_data=f"igvideo:{t['id']}"),
        ])
    rows.append([InlineKeyboardButton("🔄 রিফ্রেশ", callback_data="adm_ig")])
    await q.message.reply_text(
        "\n".join(lines)
        + "\n\n📢 = ওই টাস্কের জন্য চ্যানেল + বট ইউজারদের নোটিফিকেশন পাঠাবে।",
        parse_mode="Markdown", reply_markup=_ig_kb(rows))


async def adm_ig_export(q, uid, tid):
    task = await asyncio.to_thread(_ig_task, tid)
    if not task:
        await q.answer("❌ নেই")
        return
    data, fname = await asyncio.to_thread(_ig_csv_bytes, task)
    await q.message.reply_document(document=data, filename=fname,
                                   caption=f"📊 {task.get('name')} — CSV")
    await q.answer("✅ পাঠানো হলো")


# ─── IG Task ক্যালব্যাক রাউটার ───
async def ig_callback(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """igt_list / igtn:<id> / igtr:<id> / igts:<id> / igt_cancel / igu:<id> / igc:<id> /
    adm_ig / igx:<id>"""
    q = update.callback_query
    uid = q.from_user.id
    try:
        await q.answer()
    except Exception:
        pass
    data = q.data or ''
    try:
        _u = await asyncio.to_thread(get_user, uid)
        if _u and int(_u.get('is_banned') or 0):
            await q.message.reply_text('🚫 আপনি ব্যান হয়েছেন।')
            return
    except Exception:
        pass
    try:
        if data == 'igt_list':
            await ig_show_list(q, uid)
        elif data.startswith('igtn:'):
            await ig_task_rules(q, uid, int(data.split(':', 1)[1]))
        elif data.startswith('igtr:'):
            await ig_task_rules(q, uid, int(data.split(':', 1)[1]))
        elif data.startswith('igts:'):
            await ig_task_start(q, uid, int(data.split(':', 1)[1]))
        elif data == 'igt_cancel':
            await ig_cancel(q, uid)
        elif data.startswith('igu:'):
            await ig_retry(q, uid)
        elif data.startswith('igd:'):
            await ig_done(q, uid)
        elif data.startswith('igc:'):
            await ig_send_2fa(q, uid, int(data.split(':', 1)[1]))
        elif data == 'adm_ig':
            if uid != ADMIN_ID and not await asyncio.to_thread(is_admin, uid):
                return
            await adm_ig_list(q, uid, ctx)
        elif data.startswith('igvid:'):
            _vt = await asyncio.to_thread(_ig_task, int(data.split(':', 1)[1]))
            _vf = ((_vt or {}).get('video_url') or '').strip()
            if _vf.startswith('tg:'):
                try:
                    await q.message.reply_video(_vf[3:], caption='📽 Video')
                except Exception as _e:
                    log.warning(f'[IG-VIDEO] {_e}')
                    await q.message.reply_text('❌ ভিডিও পাঠানো যায়নি।')
            elif _vf.lower().startswith(('http://', 'https://')):
                await q.message.reply_text(
                    '📽 Video', disable_web_page_preview=True,
                    reply_markup=InlineKeyboardMarkup([[
                        InlineKeyboardButton('🎬 Video', url=_vf)]]))
            else:
                await q.message.reply_text('📽 এই টাস্কের ভিডিও এখনো যোগ করা হয়নি।')
        elif data.startswith(('igvideo:', 'igvurl:', 'igvup:', 'igvdel:')):
            if uid != ADMIN_ID and not await asyncio.to_thread(is_admin, uid):
                return
            _act, _tid = data.split(':', 1)
            _tid = int(_tid)
            if _act == 'igvideo':
                await _video_admin_panel(q, 'ig', _tid)
            elif _act == 'igvurl':
                ctx.user_data['state'] = 'fbt_video_url'
                ctx.user_data['tv_kind'] = 'ig'
                ctx.user_data['tv_tid'] = _tid
                await q.message.reply_text(
                    "🔗 ভিডিওর লিংক পাঠান (YouTube / Drive / MP4)।\n\n/cancel — বাতিল",
                    disable_web_page_preview=True)
            elif _act == 'igvup':
                ctx.user_data['state'] = 'fbt_video_file'
                ctx.user_data['tv_kind'] = 'ig'
                ctx.user_data['tv_tid'] = _tid
                await q.message.reply_text(
                    "⬆️ ভিডিওটি এখানে পাঠান (video বা video ফাইল হিসেবে)।\n\n/cancel — বাতিল")
            else:
                await asyncio.to_thread(_set_task_video, 'ig', _tid, '')
                await q.answer('ভিডিও মুছে ফেলা হয়েছে', show_alert=True)
                await _video_admin_panel(q, 'ig', _tid)
        elif data.startswith('ignt:'):
            if uid != ADMIN_ID and not await asyncio.to_thread(is_admin, uid):
                return
            await adm_ig_notify(ctx, q, uid, int(data.split(':', 1)[1]))
        elif data.startswith('igx:'):
            if uid != ADMIN_ID and not await asyncio.to_thread(is_admin, uid):
                return
            await adm_ig_export(q, uid, int(data.split(':', 1)[1]))
    except Exception as e:
        log.warning(f'[IG-TASK] callback {data}: {e}')


def _ig_state_filter(update) -> bool:
    try:
        return bool(update.effective_user and update.effective_user.id in _IG_STATE)
    except Exception:
        return False






def main():
    # ── ProxyError fix: httpx যেন system proxy ignore করে (503 এড়াতে) ───
    for _pvar in ("HTTP_PROXY","HTTPS_PROXY","http_proxy","https_proxy","ALL_PROXY","all_proxy"):
        os.environ.pop(_pvar, None)

    # ── Single-instance lock — দুটো instance একসাথে চলতে পারবে না ─
    import fcntl, sys
    _pid_file = open("/tmp/task_earn_bot.lock", "w")
    try:
        fcntl.flock(_pid_file, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        log.error("❌ Bot ইতিমধ্যে চলছে (PID lock)। দুটো instance একসাথে চলবে না।")
        sys.exit(1)

    # PostgreSQL ব্যবহার হচ্ছে — file backup/restore দরকার নেই
    init_db()
    _warm_pool_async()      # DB connection আগেই তৈরি — প্রথম /start ধীর হবে না
    # ── Security init background-এ — DB ধীর/লক থাকলেও বট চালু হবে ──
    try:
        threading.Thread(target=_security_boot, name="sec-boot", daemon=True).start()
    except Exception as _se:
        log.warning(f"[SECURITY-DB] boot thread ব্যর্থ: {_se}")
    _auto_configure()
    _setup_uptimerobot()  # no-ops if UPTIMEROBOT_API_KEY not set
    async def post_init(application):
        global _app
        _app = application   # immediate backup scheduling এর জন্য
        try:
            _lag_t = asyncio.create_task(_loop_lag_monitor())
            _background_tasks.add(_lag_t); _lag_t.add_done_callback(_bg_task_done)
        except Exception:
            pass
        try:
            await asyncio.to_thread(_vrf_base_sync)   # পুরোনো ডোমেইন → নতুন
        except Exception:
            pass
        # ── Step 1: DB না থাকলে Telegram থেকে নিজেই restore করো ──
        # PostgreSQL — auto-restore দরকার নেই
        # ── Step 2: Startup backup পাঠাও ──────────────────────────
        log.info("✅ PostgreSQL connected — data permanently stored in CockroachDB.")
        # DB এর পরপরই user report পাঠাও — background-এ, যাতে polling দেরি না হয়
        _startup_rep = asyncio.create_task(_send_startup_report(application.bot))
        _background_tasks.add(_startup_rep)
        _startup_rep.add_done_callback(_bg_task_done)
        # ── DB pool + button cache আগেই গরম করো — প্রথম ক্লিকেও দেরি হবে না ──
        async def _warmup():
            try:
                await asyncio.to_thread(_get_pool)
                await asyncio.to_thread(get_all_btns, "bn")
                await asyncio.to_thread(get_all_btns, "en")
                await asyncio.to_thread(get_setting, "bot_status")
                await asyncio.to_thread(_ensure_indexes)      # একবারই — বাকি সময় ফ্ল্যাগ
                await asyncio.to_thread(_perf_indexes)        # hot-path ইনডেক্স
                await asyncio.to_thread(_backfill_devices)    # পুরোনো হ্যাশ → devices
                await asyncio.to_thread(_dep_backfill)        # পুরোনো ডিপোজিট-হিসাব
                log.info("🔥 [WARMUP] DB pool + caches প্রস্তুত")
            except Exception as _we:
                log.warning(f"[WARMUP] ব্যর্থ: {_we}")
        async def _vrf_boot_diag():
            """Security boot শেষ হলে অ্যাডমিনকে একবার অবস্থা জানাও (সমস্যা থাকলে)।"""
            for _ in range(60):
                await asyncio.sleep(2)
                if _SEC_STATE.get("v2") in ("done", "failed"):
                    break
            try:
                if verify_enabled():
                    log.info("[VRF] verification ON — অ্যাডমিনকে আলাদা বার্তা লাগবে না")
                    return
                txt = (
                    "⚠️ *Verification চালু হয়নি*\n\n"
                    f"• state: `{dict(_SEC_STATE)}`\n"
                    f"• panel base: `{_vrf_panel_base() or '-'}`\n"
                    f"• token: `{'vtoken.py' if _vtoken else 'inline'}`\n\n"
                    "`/start` দিলে এখন পুরোনো মতোই স্বাগতম আসবে।\n"
                    "বিস্তারিত: `/vrfdiag`"
                )
                await application.bot.send_message(ADMIN_ID, txt, parse_mode="Markdown")
            except Exception as _e:
                log.warning(f"[VRF] boot diag DM ব্যর্থ: {_e}")
        _vrf_diag_task = asyncio.create_task(_vrf_boot_diag())
        _background_tasks.add(_vrf_diag_task)
        _vrf_diag_task.add_done_callback(_bg_task_done)
        _warm_task = asyncio.create_task(_warmup())
        _background_tasks.add(_warm_task)
        _warm_task.add_done_callback(_bg_task_done)
        # ── IP retention: পুরোনো user_ips/ip_history পরিষ্কার (১২ ঘণ্টা পর পর) ──
        _ret_task = asyncio.create_task(_ip_retention_loop())
        _background_tasks.add(_ret_task)
        _ret_task.add_done_callback(_bg_task_done)
        # ── Step 3: Pending notification watcher শুরু করো ─────────
        # Bot restart হলেও DB থেকে pending notifications ধরবে।
        _watcher_task = asyncio.create_task(_pn_watcher(application.bot))
        _background_tasks.add(_watcher_task)
        _watcher_task.add_done_callback(_bg_task_done)
        log.info("✅ Pending-notification watcher started (প্রতি ৩০ সেকেন্ড চেক করবে)")
        # ── Binance ডিপোজিট অটো-ওয়াচ (১ ঘণ্টা, প্রতি ৪৫ সে.) ──
        try:
            log.info("ℹ️ Binance deposit auto-watch বন্ধ — শুধু বাটনে চাপলে চেক হবে")

            async def _dep_boot_report(minutes=60):
                """বুট/আপডেটের পর অ্যাডমিনকে পূর্ণ ডায়াগনস্টিক DM (সবসময়, ৩ বার চেষ্টা)।"""
                _host = (os.environ.get("RENDER_EXTERNAL_HOSTNAME") or "").strip()
                _px = (os.environ.get("BINANCE_PROXY")
                       or os.environ.get("BINANCE_HTTPS_PROXY") or "").strip()
                _head = (f"🚀 *বট চালু — নতুন ফাইল লোড হয়েছে*\n"
                         f"build: `{BOT_BUILD}`\n"
                         f"🌍 হোস্ট: `{_host or 'লোকাল'}`\n"
                         f"🔌 Proxy: `{'সেট' if _px else 'নেই'}`\n"
                         f"🕒 {now()}\n"
                         "━━━━━━━━━━━━━━\n"
                         "_নিচে Binance চেকের ফল — কিছু ভুল হলে 🔁 বাটনে চাপুন_")
                _kb = InlineKeyboardMarkup([[
                    InlineKeyboardButton("🔁 Binance আবার টেস্ট", callback_data="depdiag")]])
                try:
                    if not await asyncio.to_thread(dep_binance_ready):
                        _t = ("\n\n⚠️ *Binance API সেট করা নেই*\n"
                              "Admin → 💳 ডিপোজিট → 🔌 API Key/Secret দিন।")
                    else:
                        _ok, _rep = await asyncio.to_thread(
                            dep_api_test, "binance", int(minutes))
                        _t = "\n\n" + _rep
                        log.info(f"[BINANCE] boot self-test {'OK' if _ok else 'FAIL'}")
                except Exception as _te:
                    _t = f"\n\n⚠️ টেস্ট চলেনি: `{str(_te)[:120]}`"
                _msg = _head + _t
                for _att in range(3):
                    try:
                        await application.bot.send_message(
                            ADMIN_ID, _msg, parse_mode="Markdown", reply_markup=_kb)
                        log.info("[BINANCE] boot report পাঠানো হয়েছে")
                        return
                    except Exception as _e1:
                        try:      # Markdown ভাঙলে প্লেইন টেক্সটে
                            await application.bot.send_message(
                                ADMIN_ID, _msg.replace("*", "").replace("`", ""),
                                reply_markup=_kb)
                            log.info("[BINANCE] boot report (plain) পাঠানো হয়েছে")
                            return
                        except Exception as _e2:
                            log.warning(f"[BINANCE] boot report চেষ্টা {_att+1}/3 ব্যর্থ: "
                                        f"{str(_e2)[:120]}")
                            await asyncio.sleep(20)
                log.error("[BINANCE] boot report ৩ বার ব্যর্থ — ডেলিভারি হয়নি")

            async def _dep_api_boot_check():
                await asyncio.sleep(20)
                for _try in range(3):
                    try:
                        await _dep_boot_report(60)
                        return
                    except Exception as _be:
                        log.warning(f"[BINANCE] boot check {_try+1}/3: {str(_be)[:120]}")
                        await asyncio.sleep(30)

            _depchk = asyncio.create_task(_dep_api_boot_check())
            _background_tasks.add(_depchk)
            _depchk.add_done_callback(_bg_task_done)

            async def _dep_fund_base_init():
                """বুটে ফান্ডিং-ব্যালেন্স বেসলাইন — পেমেন্ট আগে এলেও ধরা পড়বে।"""
                await asyncio.sleep(35)
                try:
                    _b = await asyncio.to_thread(funding_usdt_balance)
                    if _b is None:
                        return
                    if await asyncio.to_thread(_fund_base_get) is None:
                        await asyncio.to_thread(_fund_base_set, _b)
                        log.info(f"[DEP-FUND] বেসলাইন (boot): {_b:g}$")
                    else:
                        log.info(f"[DEP-FUND] বেসলাইন আগেই আছে "
                                 f"({await asyncio.to_thread(_fund_base_get)}), "
                                 f"এখন {_b:g}$")
                except Exception as _fe:
                    log.debug(f"[DEP-FUND] boot baseline: {str(_fe)[:100]}")

            _fbi = asyncio.create_task(_dep_fund_base_init())
            _background_tasks.add(_fbi)
            _fbi.add_done_callback(_bg_task_done)

            async def _dep_hide_loop():
                """approved/rejected ডিপোজিট ১ দিন পর অ্যাডমিন তালিকা থেকে সরাও।"""
                await asyncio.sleep(90)
                while True:
                    try:
                        _hn = await asyncio.to_thread(dep_hide_old, 24)
                        if _hn:
                            log.info(f"[DEP-HIDE] {_hn}টি পুরোনো ডিপোজিট অ্যাডমিন "
                                     "তালিকা থেকে সরানো হলো (ইউজার হিস্ট্রি অটুট)")
                    except Exception as _he:
                        log.debug(f"[DEP-HIDE] {str(_he)[:100]}")
                    await asyncio.sleep(1800)

            async def _shop_refund_loop():
                """৩০ মিনিটে ডেলিভারি না হলে অ্যাডমিনকে রিমাইন্ডার (প্রতি অর্ডারে একবার)।"""
                await asyncio.sleep(120)
                while True:
                    try:
                        _st = await asyncio.to_thread(shop_stale_orders, 30)
                        for _o in (_st or []):
                            _oid2 = int(_o["id"])
                            _okb = InlineKeyboardMarkup([[
                                InlineKeyboardButton("✅ ডেলিভারি দিন",
                                                     callback_data=f"shopao:{_oid2}"),
                                InlineKeyboardButton("💸 রিফান্ড",
                                                     callback_data=f"shopar:{_oid2}"),
                            ]])
                            try:
                                await notify_full_admins(
                                    application.bot,
                                    (f"⏳ *অর্ডার #{_oid2} — ৩০ মিনিটেও ডেলিভারি হয়নি*\n\n"
                                     f"🛍 {_md_esc(str(_o['product_name'] or ''))}\n"
                                     f"👤 `{int(_o['user_id'])}` · 💵 `{_o['price']}`\n\n"
                                     "ডেলিভারি দিতে পারলে ✅, স্টক না থাকলে 💸 — "
                                     "সাথে সাথে টাকা ফেরত যাবে।"),
                                    reply_markup=_okb)
                                _SHOP_REMINDED.add(_oid2)
                                log.info(f"[SHOP] #{_oid2} রিমাইন্ডার পাঠানো হলো")
                            except Exception:
                                pass
                    except Exception as _re:
                        log.debug(f"[SHOP] রিমাইন্ডার লুপ: {str(_re)[:100]}")
                    await asyncio.sleep(300)

            _srl = asyncio.create_task(_shop_refund_loop())
            _background_tasks.add(_srl)
            _srl.add_done_callback(_bg_task_done)

            _dhide = asyncio.create_task(_dep_hide_loop())
            _background_tasks.add(_dhide)
            _dhide.add_done_callback(_bg_task_done)
        except Exception as _dwe:
            log.warning(f"[DEP-WATCH] চালু হয়নি: {_dwe}")
        # ── Step 4: পুরানো bio users কে নতুন text জানাও (একবারই) ──
        _bio_notify_task = asyncio.create_task(_notify_bio_text_change(application.bot))
        _background_tasks.add(_bio_notify_task)
        _bio_notify_task.add_done_callback(_bg_task_done)
        # ── সিকিউরিটি পলিসি v2: ১ ফোন = ১ অ্যাকাউন্ট, এক IP-তে ২টি ──
        try:
            if (get_setting("sec_policy_v2") or "") != "done":
                set_setting("sec_device_limit", "1")
                set_setting("sec_ip_limit", "2")
                set_setting("sec_policy_v2", "done")
                log.info("[SEC2] policy v2 প্রয়োগ: device_limit=1, ip_limit=2")
        except Exception as _pv:
            log.debug(f"[SEC2] policy migrate ব্যর্থ: {_pv}")
        # ── policy v3: ডিভাইস/IP ডুপ্লিকে অটো-ব্যান নয় (block + alert) ──
        try:
            if (get_setting("sec_policy_v3") or "") != "done":
                if get_setting("sec_auto_ban") is None:
                    set_setting("sec_auto_ban", "off")
                set_setting("sec_policy_v3", "done")
                log.info("[SEC2] policy v3: অটো-ব্যান বন্ধ (verify-লেভেলে ব্লক)")
        except Exception as _p3:
            log.debug(f"[SEC2] policy v3 ব্যর্থ: {_p3}")

        # ── নোটিশ ডি-ডুপ: যার কাছে এই বিল্ডে নোটিশ গেছে আর যাবে না (একবারই) ──
        try:
            await asyncio.to_thread(_vrf_notice_backfill)
        except Exception as _nb:
            log.warning(f"[NOTICE] backfill: {_nb}")

        # ── নতুন বিল্ডে সব ইউজার আবার শুরু থেকে (auto reset) ──
        _reset_task = asyncio.create_task(_maybe_reset_on_update(application.bot))
        _background_tasks.add(_reset_task)
        _reset_task.add_done_callback(_bg_task_done)

        # ── ওয়েব প্যানেল থেকে বদলানো মান সাথে সাথে বটে কাজ করবে ──
        try:
            import webadmin as _wadm_mod

            def _web_settings_hook(keys=None):
                try:
                    if keys:
                        for _k in keys:
                            _settings_cache.pop(_k, None)
                    _settings_cache.clear()
                except Exception:
                    pass
                try:
                    _invalidate_btn_cache()
                except Exception:
                    pass
                log.info(f"[WEB] settings বদলেছে → cache clear {list(keys or [])}")

            def _web_user_hook(uid=None):
                try:
                    if uid:
                        _invalidate_user_cache(int(uid))
                except Exception:
                    pass

            _wadm_mod.set_settings_hook(_web_settings_hook)
            _wadm_mod.set_user_hook(_web_user_hook)
            log.info("✅ [WEB] settings/user cache hook রেজিস্টার্ড")
            # প্যানেলে FB/IG approve-reject চাপা মাত্রই বটের job (আর ২০s অপেক্ষা নয়)
            try:
                _REVIEW_LOOP[0] = asyncio.get_running_loop()
                _REVIEW_CTX[0]  = type("ReviewCtx", (), {"bot": application.bot})()
                _wadm_mod.set_review_hook(_kick_review)
                log.info("✅ [WEB] review→bot instant hook রেজিস্টার্ড")
            except Exception as _rh:
                log.warning(f"[WEB] review hook ব্যর্থ: {_rh}")
        except Exception as _wh:
            log.warning(f"[WEB] hook রেজিস্টার ব্যর্থ: {_wh}")

        # ── প্যানেলে Verify শেষ হলে বট নিজেই মেনু পাঠাবে (কমান্ড ছাড়াই) ──
        try:
            import panel as _panel_mod
            _panel_mod.set_verify_hook(_vrf_after_web_verify, asyncio.get_running_loop())
            log.info("✅ [VRF] web→bot auto-start hook রেজিস্টার্ড")
        except Exception as _he:
            log.warning(f"[VRF] auto-start hook ব্যর্থ: {_he}")

        async def _vrf_signal_watch():
            """ফলব্যাক — hook কাজ না করলেও সিগন্যাল টেবিল থেকে মেনু পাঠাবে।"""
            await asyncio.sleep(8)
            while True:
                try:
                    for _u in await asyncio.to_thread(_vrf_pending_signals):
                        await _vrf_after_web_verify(_u, application.bot)
                except Exception as _e2:
                    log.debug(f"[VRF] signal watcher: {_e2}")
                await asyncio.sleep(5)

        try:
            _vrf_sig_task = asyncio.create_task(_vrf_signal_watch())
            _background_tasks.add(_vrf_sig_task)
            _vrf_sig_task.add_done_callback(_bg_task_done)
        except Exception as _ve:
            log.warning(f"[VRF] signal watcher চালু হয়নি: {_ve}")
        # Fallback dirty-check: ৬০ সেকেন্ড পরপর (immediate scheduling ব্যর্থ হলে)
        if application.job_queue is not None:
            application.job_queue.run_repeating(
                job_dirty_backup,
                interval=300,   # ১২০s → ৩০০s — ব্যাকআপ ডাটা ছাড়া কাজ নেই
                first=300,
                name="dirty_backup"
            )
            application.job_queue.run_repeating(
                job_health_check,
                interval=3600,
                first=300,
                name="health_check"
            )
            application.job_queue.run_repeating(
                job_fb_sheet_sync, interval=300, first=120, name="fb_sheet_sync")
            application.job_queue.run_repeating(
                job_dep_name_watch, interval=60, first=30, name="dep_name_watch")
            application.job_queue.run_repeating(
                job_dep_mail_watch, interval=60, first=20, name="dep_mail_watch")
            application.job_queue.run_repeating(
                job_fb_password_rotate, interval=60, first=45, name="fb_pw_rotate")
            application.job_queue.run_repeating(
                job_fb_export, interval=60, first=75, name="fb_export")
            application.job_queue.run_repeating(
                job_ig_sheet_sync, interval=300, first=150, name="ig_sheet_sync")
            application.job_queue.run_repeating(
                job_ig_password_rotate, interval=60, first=50, name="ig_pw_rotate")
            application.job_queue.run_repeating(
                job_ig_export, interval=60, first=80, name="ig_export")
